window.UNIVERSITY = {"name": "Açık Akademi", "shortName": "Açık Akademi", "tagline": "Ücretsiz dersler, sınav hazırlığı ve çalışma masası", "issuer": "Açık Akademi", "issuerUrl": "", "passMark": 0.7, "codePrefix": "AAK", "colors": {"primary": "#1b2a4a", "accent": "#b08d4a", "paper": "#f8f4ea"}, "showNotebookLinks": true, "plannedCourses": 0, "storageKey": "a-k-i-lahiyat-niversitesi", "exams": [{"id": "2026-guz-vize", "name": "Güz ara sınavı (vize)", "date": "2026-12-05", "end": "2026-12-06", "scope": "vize"}, {"id": "2026-guz-final", "name": "Güz dönem sonu sınavı (final)", "date": "2027-01-16", "end": "2027-01-17", "scope": "final"}, {"id": "2027-yaz", "name": "Yaz okulu sınavı", "date": "2027-08-21", "scope": "final"}], "grading": {"midterm": 30, "final": 70, "passMin": 35, "questions": 20, "source": "2025-26 dönemi için basında aktarılan AÖF kurallarıdır (geçme sınırını Senato belirler)"}};
window.COURSES = [{"slug": "teknik-gelistirim", "subject": "Teknik Gelişim", "course": "IFS Enterprise Oracle Architecture & DBA Training Program", "professor": "", "school": "IFS Cloud & Oracle DBA Eğitim Programı", "playlist": "", "note": "Kurumsal Oracle veritabanı ve IFS Cloud işletim eğitimi: yüksek erişilebilirlik (RAC, Data Guard, MAA), uygulama sürekliliği (Application Continuity / TAC), performans yönetimi (AWR, ASH, ADDM) ve işletim gözetimi (OEM, Server Alert Log). Kaynaklar Oracle ile IFS resmî dokümanları ve eğitim programının kendi çalışma notlarıdır.", "kind": "sources", "notebook": "https://notebooklm.google.com/notebook/d9fbd16b-86fb-45ab-af81-dc503b2c5aad", "sourceCount": 94, "language": "en", "chapters": [{"title": "Program Orientation and IFS Cloud Oracle Architecture", "summary": "This chapter covers the foundational enterprise architecture and administration practices required to manage Oracle Database 19c environments for IFS Applications and IFS Cloud. The curriculum covers Multitenant Container Database (CDB) and Pluggable Database (PDB) isolation, dynamic memory architecture tuning for sga_target and pga_aggregate_target, and Release Update (RU) and Release Update Revision (RUR) patch lifecycles. The chapter also covers operational governance, background job lifecycle management, deployment prerequisites, and telemetry monitoring using the Application Monitoring Console in IFS Cloud 26R2, alongside operational report development in IFS Cloud 25R1.", "objectives": ["administer Multitenant Container Database (CDB) structures and Pluggable Database (PDB) tenant isolation while tuning memory parameters sga_target and pga_aggregate_target for Oracle Database 19c.", "align quarterly Release Update (RU) and Release Update Revision (RUR) patch maintenance cycles with IFS Applications and IFS Cloud maintenance windows.", "execute operational governance, background process cleanup, deployment prerequisites, and server alert log monitoring within IFS Cloud 26R2 environments."], "lectures": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": "", "type": "markdown"}, {"title": "IFS Oracle DBA Training Setup", "url": "", "type": "gemini_chat"}, {"title": "Chapter 1 Core Topics Overview", "url": "", "type": "gemini_chat"}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": "", "type": "pdf"}, {"title": "IFS Oracle DBA Training Progress", "url": "", "type": "gemini_chat"}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": "", "type": "gemini_chat"}, {"title": "Training Progress and Chapter 6 Start", "url": "", "type": "gemini_chat"}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": "", "type": "gemini_chat"}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": "", "type": "markdown"}], "notes": "Based on the provided sources, here is the detailed explanation of each specified objective.\n\n---\n\n### Objective 1: Multitenant CDB Structures, PDB Tenant Isolation, and Memory Tuning\n\nFor this objective, the following is covered:\n\n* **CDB and PDB Architecture:** Managing the single root container database CDB$ROOT, which handles background processes, shared system metadata, and global memory. Creating and administering dedicated pluggable databases, including PDB$SEED and User PDBs such as IFS_PROD, IFS_TEST, and DEV, to isolate distinct IFS application instances on shared server hardware.\n* **Tenant Isolation and Session Management:** Managing PDB states, switching container contexts, and isolating transactional schema objects across environments.\n* **Resource Manager Governance:** Configuring Oracle Resource Manager policies using `CREATE_CDB_PLAN` to assign CPU shares (`shares`) and utilization limits (`utilization_limit`) at the CDB level, preventing non-production environments from starving production resources.\n* **Dynamic Memory Tuning:** Configuring `sga_target` under Automatic Shared Memory Management (ASMM) to dynamically balance the Buffer Cache, Shared Pool, and Large Pool for high-volume OLTP transactions. Configuring `pga_aggregate_target` optimizes per-process memory for sort operations and hash joins, preventing temporary tablespace spilling during large batch runs.\n* **Capacity Parameters:** Tuning `open_cursors` and `processes` to support concurrent mid-tier application connection pools.\n* **Version Application:** The training sources apply these multitenant and parameter tuning concepts to IFS Applications (including IFS Cloud, IFS Applications 10, and IFS Applications 9) and specify Oracle 19c for the underlying storage tier in IFS Cloud 26R2. Where the training sources present core ASMM parameter definitions without specifying a database version, the sources do not explicitly name the version.\n\n---\n\n### Objective 2: RU and RUR Patch Maintenance Alignment\n\nFor this objective, the following is covered:\n\n* **Release Updates (RU):** Understanding quarterly cumulative patches that contain security vulnerability fixes, high-value bug fixes, and critical stability enhancements, which increment the minor database release version.\n* **Release Update Revisions (RUR):** Understanding security and regression-focused patches that extend the lifespan of an existing RU without introducing new functional bug fixes, preserving production stability.\n* **Maintenance Window Alignment:** Aligning Oracle quarterly RU and RUR patching strategies with IFS Cloud and IFS Applications update and release cycles across production and non-production environments.\n* **Version Application:** The sources present RU and RUR patch alignment for IFS Cloud as well as IFS Applications 10 and IFS Applications 9 without stating a specific database version limitation for the patch definition.\n\n---\n\n### Objective 3: Operational Governance, Process Cleanup, Prerequisites, and Alert Monitoring in IFS Cloud 26R2\n\nFor this objective, the following is covered from the official IFS Cloud 26R2 documentation:\n\n* **Background Process Lifecycle:** Deferred transactions and automated maintenance operations progress through states to terminal states Ready, Warning, or Error.\n* **System Retention Parameters:** Automated purging is executed by Foundation1 Light Cleanup based on System Parameters in Solution Manager. The default retention intervals are 7 days for completed jobs in state Ready, 30 days for jobs in state Warning, 180 days for jobs in state Error, and 7 days for inactive Scheduled tasks. Setting the \"Exclude from Cleanup\" flag on a job overrides standard retention limits to preserve diagnostic data. The system parameter \"Number of background processes\" defaults to 10 and is limited by Oracle's `JOB_QUEUE_PROCESSES` parameter.\n* **Pre-Deployment Cleanup Isolation Sequence:** Executing Light Cleanup 24 hours prior to deployment to clear job backlogs and invalid materialized views. Disabling scheduled maintenance tasks \"Shrink LOB segments\" and \"Heavy Cleanup\" in Solution Manager, setting batch queues to a stopped state to drain Executing jobs, and inspecting active Oracle sessions to terminate lingering background slave processes before running deployment scripts.\n* **Deployment Prerequisites Checklist:** Locking the Application Owner account for Remote Deployment models. Verifying that active Oracle RMAN database archiving and continuous logging are healthy. Pausing batch queues and suspending scheduled task daemons to prevent schema modification during delivery. Confirming ICAM Blob and SMB file storage configuration, Kubernetes node labeling, persistent volume claims (PVCs), middle-tier container memory directives in `ifscloud-values.yaml` for pods such as `ifsapp-connect`, and pausing or draining transport connectors and IFS Connect message queues.\n* **Server Alert Log Architecture:** Accessing database diagnostic logs via Solution Manager under Solution Manager / Monitoring / Server Alert Log. Log entries record Category ID, Text 1 (primary error text), Text 2 (detailed SQL or PL/SQL block), F1 Identity, and OS Identity. Categories are configured in Server Alert Log Categories using Enable, Cleanup, and Days to keep parameters. Standard categories include Ddl Audit, Debug, Deployment, Deployment detail, Event errors, Server Errors (triggered by AFTER ERROR), Sql Injections (triggered by `Assert_SYS`), and In-Memory. In production IFS Cloud 26R2 environments, Sql Injections and Server Errors are recommended to remain active, while trigger-based categories like Ddl Audit should be disabled during normal operations to avoid performance overhead.\n\n---\n\n💡 **Next Steps:** Would you like to generate a practice quiz covering these three modules, or explore the specific step-by-step SQL runbooks for PDB isolation and CDB Resource Manager configuration?", "cites": [], "image": "assets/teknik-gelistirim/chapter-1.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Multitenant Database Administration: CDB and PDB", "summary": "This chapter covers how to administer Oracle Database 19c Multitenant Container Databases (CDB) and manage Pluggable Database (PDB) structural architecture, including CDB$ROOT, PDB$SEED, and user PDBs. This chapter examines operational environment isolation and resource management techniques across IFS Applications instances to prevent data contamination and resource starvation. Additionally, the curriculum covers configuring PDB memory thresholds such as sga_target and pga_aggregate_limit, setting PDB Resource Manager profiles, and executing independent PDB lifecycle operations like cloning and unplugging without disrupting sibling databases.", "objectives": ["administer Oracle Database 19c Multitenant architecture by managing CDB$ROOT, PDB$SEED, and user PDB structures to maintain schema and metadata isolation across IFS Applications environments.", "configure PDB Resource Manager profiles and memory limits such as sga_target and pga_aggregate_limit in Oracle Database 19c to allocate CPU shares and prevent resource starvation.", "execute independent Pluggable Database lifecycle operations, including switching container contexts, provisioning from PDB$SEED, and cloning or unplugging PDBs without impacting sibling databases."], "lectures": [{"title": "Container Database (CDB) Administration", "url": "", "type": "gemini_chat"}, {"title": "Pluggable Database (PDB) Isolation & Operations", "url": "", "type": "gemini_chat"}, {"title": "Oracle Database Database Administrator's Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/admin/", "type": "web_page"}, {"title": "Oracle Database Database Concepts, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/cncpt/", "type": "web_page"}], "notes": "Here is what each objective covers, based strictly on the provided sources.\n\n---\n\n### Objective 1: Administering Oracle Database 19c Multitenant Architecture and Managing CDB$ROOT, PDB$SEED, and User PDB Structures\n\n* **Container Architecture Fundamentals:** Oracle Multitenant architecture divides database infrastructure into a single root container database (CDB$ROOT) and one or more Pluggable Databases (PDBs).\n* **Root Container Management:** CDB$ROOT manages common background processes, shared system metadata, global database memory, common user accounts, and global initialization parameters.\n* **Pluggable Database Types:** PDB$SEED functions as a system-supplied template PDB used to rapidly provision new pluggable databases for additional IFS environments. User PDBs are dedicated pluggable databases that hold user data schemas, tablespaces, and application-specific metadata required by IFS Applications.\n* **Metadata and Schema Isolation:** Each PDB maintains its own private data dictionary for user-created tables, indexes, and application schemas while CDB$ROOT handles shared system metadata. Mid-tier connection pools interact exclusively with their assigned PDB service, ensuring sessions in non-production instances cannot access or modify Production schema objects.\n* **IFS Application Stage Isolation:** In IFS Applications (specifically IFS Cloud and IFS Applications 10/9), tenant and environment isolation isolates ERP transaction data and schema objects across distinct operational stages (such as DEV, TEST, and PROD) while sharing physical hardware resources.\n* **Official Oracle 19c Manuals:** The official manuals **Oracle Database Database Administrator's Guide, 19c** and **Oracle Database Database Concepts, 19c** provide the core administrative framework and concepts for managing multitenant database structures.\n\n---\n\n### Objective 2: Configuring PDB Resource Manager Profiles and Memory Limits (sga_target, pga_aggregate_limit)\n\n* **Resource Isolation Rationale:** In high-demand environments running IFS Cloud or IFS Applications 10/9, PDB-level resource controls must be configured to prevent heavy testing workloads or runaway queries from starving critical OLTP production workloads.\n* **PDB Resource Manager Profiles:** Configuring PDB Resource Manager profiles to allocate specific shares of CPU, parallel execution queues, and session limits per PDB.\n* **Memory Limit Parameters:** Memory boundaries can be configured per PDB using parameters such as `sga_min_size`, `sga_target`, and `pga_aggregate_limit`. Setting limits like `pga_aggregate_limit` (for example, 4G) and `sga_target` (for example, 8G) on a non-production PDB shields host memory from being exhausted by individual containers.\n* **Official Governance Framework:** Database Resource Management and Task Scheduling concepts are governed by Part IV of the **Oracle Database Database Administrator's Guide, 19c**.\n\n---\n\n### Objective 3: Executing Independent Pluggable Database Lifecycle Operations and Container Management\n\n* **Independent Lifecycle Operations:** DBAs can unplug, clone, or drop an individual PDB without interrupting active operations on sibling PDBs running on the same container instance.\n* **PDB Provisioning:** Rapid provisioning of new pluggable databases across IFS application stages is executed using the template PDB$SEED.\n* **Container Context Switching:** DBAs switch session container contexts between CDB$ROOT and target PDBs using SQL commands such as `ALTER SESSION SET CONTAINER = <container_name>;`.\n* **PDB State and Context Verification:** DBAs alter PDB states using commands like `ALTER PLUGGABLE DATABASE <pdb_name> OPEN;` and verify session container contexts via `sys_context('USERENV', 'CON_NAME')`, `sys_context('USERENV', 'CON_ID')`, `v$pdbs`, and `v$session`.\n* **Official Oracle 19c Lifecycle Standard:** Official multitenant lifecycle management procedures are defined in the **Oracle Database Database Administrator's Guide, 19c**.\n\n---\n\n🛠️ **Suggested Next Step:** Would you like to generate a step-by-step SQL runbook for setting up PDB Resource Manager profiles and memory limits, or create flashcards to test your knowledge on CDB/PDB administration?", "cites": [], "image": "assets/teknik-gelistirim/chapter-2.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "summary": "This chapter covers how to manage software maintenance, patch execution, and database upgrades for Oracle Database 19c supporting enterprise applications. The curriculum details the quarterly Release Update (RU) and Release Update Revision (RUR) lifecycle alignment, pre-patch verification with OPatch, two-stage binary patching via opatch apply, and post-patch SQL automation using datapatch across CDB$ROOT and pluggable databases (PDBs). Additionally, the chapter examines upgrade methodologies including AutoUpgrade, DBUA, and Parallel Upgrade Utility, alongside cloud infrastructure maintenance and zero-downtime patching tools such as OS Management Hub and Ksplice.", "objectives": ["differentiate between quarterly Release Update (RU) and Release Update Revision (RUR) patch strategies to align Oracle Database 19c maintenance with enterprise application change management policies.", "execute two-stage patch maintenance using OPatch for binary updates in $ORACLE_HOME and datapatch for post-patch SQL metadata automation across CDB$ROOT and pluggable databases (PDBs).", "plan and execute database upgrades to Oracle Database 19c using AutoUpgrade, DBUA, or Parallel Upgrade Utility while leveraging OS Management Hub and Ksplice for Linux infrastructure maintenance."], "lectures": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": "", "type": "gemini_chat"}, {"title": "Patch Application Execution", "url": "", "type": "gemini_chat"}, {"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf", "type": "pdf"}, {"title": "Oracle Database Database Upgrade Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/upgrd/", "type": "web_page"}], "notes": "### Objective 1: Differentiating Between Release Update (RU) and Release Update Revision (RUR) Patch Strategies\n\n* **Release Update (RU) Definition:** A Release Update is a quarterly, cumulative patch that contains security vulnerability fixes, proactive high-value bug fixes, and critical stability enhancements.\n* **RU Version Impact:** Applying an RU moves the database to a new minor release version, such as updating from 19.3.0 to 19.4.0 or from 19.11 to 19.12 in Oracle Database 19c.\n* **Release Update Revision (RUR) Definition:** A Release Update Revision extends the operational lifespan of an existing RU by delivering strictly critical security fixes and regression fixes for that specific RU without incorporating new functional bug fixes.\n* **RUR Version Impact:** Applying an RUR increments the revision digit of Oracle Database 19c, such as advancing from 19.3.0 to 19.3.1 or 19.3.2, or from 19.11.0 to 19.11.1.\n* **Release Frequency:** RUs and RURs are both released quarterly in January, April, July, and October, with up to two revisions delivered per RU for RURs.\n* **Non-Production Strategy:** In multitenant CDB and PDB environments supporting IFS Applications (including IFS Cloud, IFS Applications 10, and IFS Applications 9), an RU strategy is recommended for non-production environments (DEV and TEST) during major update cycles to validate performance changes and execution plans.\n* **Production Strategy:** An RUR strategy is used for production environments where strict enterprise change management policies require security updates while locking core execution behavior between major IFS application upgrade windows.\n* **Version Application:** The training architecture notes distinguish Oracle Database 19c version numbers in worked examples and explicitly list IFS Cloud, IFS Applications 10, and IFS Applications 9.\n\n---\n\n### Objective 2: Executing Two-Stage Patch Maintenance Using OPatch and Datapatch\n\n* **Maintenance Rationale:** Applying RUs and RURs ensures that Oracle Database backends supporting IFS Applications remain secure, stable, and bug-free.\n* **OPatch Version Alignment:** Database administrators must update the opatch utility to the minimum version specified in the Oracle Patch Readme before executing patch routines.\n* **Conflict Detection:** Running conflict checks against the target $ORACLE_HOME prevents partial patch applications and verifies prerequisites before shutting down database services.\n* **Stage 1 - Binary Patching (`opatch apply`):** Binary patching replaces executable binaries, libraries, and header files within $ORACLE_HOME while database services are down.\n* **Stage 2 - Post-Patch SQL Automation (`datapatch`):** Post-patch SQL automation updates SQL metadata, data dictionary objects, and PL/SQL packages inside CDB$ROOT and all pluggable databases (PDBs) once the database is reopened.\n* **Registry Verification:** DBAs verify the patch application state across the Oracle home and pluggable databases by querying the `registry$history` and `dba_registry_sqlpatch` views.\n* **Version Application:** The source outlines this two-stage pipeline for CDB$ROOT and PDB structures without restricting the `opatch apply` and `datapatch` command steps to a single database version.\n\n---\n\n### Objective 3: Planning and Executing Upgrades to Oracle Database 19c and Managing Linux Infrastructure\n\n* **Upgrade Scope:** The official manual **Oracle Database Database Upgrade Guide, 19c** provides procedures for upgrading Oracle Database to release 19c (19.0.0.0).\n* **AutoUpgrade Method:** Upgrades to Oracle Database 19c can be planned and executed using AutoUpgrade.\n* **Parallel Upgrade Utility Method:** Upgrades to Oracle Database 19c can be performed manually using the Parallel Upgrade Utility.\n* **DBUA Method:** Upgrades to Oracle Database 19c can be conducted using the Oracle Database Upgrade Assistant (DBUA).\n* **Zero-Downtime Patching with Ksplice:** On the operating system level, Oracle Linux provides Ksplice for zero-downtime kernel patching.\n* **OS Management Hub Administration:** Oracle OS Management Hub provides a single management console in OCI to automate, streamline, and simplify update and patch management for Oracle Linux systems.\n* **Continuous Availability:** OS Management Hub integrates with Ksplice, enabling administrators to apply select security updates on Oracle Linux without rebooting, reducing application disruptions and maintaining continuous availability.\n* **Version Application:** The upgrade tools (AutoUpgrade, Parallel Upgrade Utility, DBUA) apply specifically to Oracle Database 19c as documented in the 19c Database Upgrade Guide, while the sources do not state database version limits for OS Management Hub and Ksplice on Oracle Linux.\n\n---\n\n💡 Would you like to generate a step-by-step SQL script for querying `dba_registry_sqlpatch` to verify your current patch revision level across all PDBs?", "cites": [], "image": "assets/teknik-gelistirim/chapter-3.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Storage, ASM and Capacity Management", "summary": "This chapter covers how to design and manage storage architecture using Oracle Automatic Storage Management (ASM) disk groups, including DATA and RECO, while configuring coarse-grained and fine-grained striping alongside redundancy models for high-concurrency OLTP workloads in IFS Cloud 25R1 and IFS Applications 10. This chapter examines table partitioning strategies such as Range, List, and Hash partitioning for high-volume transaction tables in Oracle Database 19c, utilizing partition pruning, local index maintenance, and Partition Maintenance Operations (PMO) to optimize query performance and disk reclamation. Additionally, the curriculum covers setting up warning thresholds at 85 percent and critical thresholds at 95 percent using DBMS_SERVER_ALERT in Oracle Enterprise Manager (OEM) to monitor logical tablespaces and physical ASM disk space, preventing unhandled out-of-space errors.", "objectives": ["configure Oracle Automatic Storage Management (ASM) DATA and RECO disk groups in Oracle Database 19c using fine-grained striping for online redo logs and coarse-grained striping for data files under external, normal, or high redundancy models.", "implement Range, List, and Hash table partitioning alongside local index strategies for high-volume transaction tables in Oracle Database 19c supporting IFS Cloud 25R1 to enable partition pruning and Partition Maintenance Operations.", "set warning thresholds at 85 percent and critical thresholds at 95 percent via DBMS_SERVER_ALERT and Oracle Enterprise Manager (OEM) to monitor tablespace and ASM disk group capacity boundaries."], "lectures": [{"title": "Disk Group Architecture (DATA & RECO)", "url": "", "type": "gemini_chat"}, {"title": "ASM Striping & Redundancy for OLTP", "url": "", "type": "gemini_chat"}, {"title": "Table Partitioning for Massive Transaction Tables", "url": "", "type": "gemini_chat"}, {"title": "Tablespace & ASM Disk Space Thresholds", "url": "", "type": "gemini_chat"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-010-planning-installation-010-storage-tier-considerations-010-oracle-db-19c-Oracle-19c-Enterprise-Edition-19c-options-and-feat.pdf", "url": "", "type": "pdf"}, {"title": "Oracle Automatic Storage Management Administrator's Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/ostmg/", "type": "web_page"}, {"title": "Oracle Database Database Reference, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/refrn/", "type": "web_page"}], "notes": "---\n\n### Objective 1: Configuring ASM DATA and RECO Disk Groups, Striping Strategies, and Redundancy Models\n\n* **Dedicated Disk Group Architecture:** Oracle Automatic Storage Management (ASM) organizes physical disks into logical Disk Groups. \n * The **DATA disk group** serves as the primary operational storage area housing active data files, index tablespaces, system tablespaces (SYSTEM, SYSAUX), temporary files, and online redo log groups. High read and write IOPS performance is prioritized in DATA to process active IFS mid-tier transactions.\n * The **RECO (or FRA) disk group** serves as the dedicated recovery storage area housing archive logs, RMAN backup sets, control file copies, Flashback logs, and multiplexed copies of online redo logs. Isolating recovery files in RECO prevents backup or archiving operations from competing for disk bandwidth with primary transactional data operations.\n* **ASM Striping Strategies:** \n * **Coarse-Grained Striping:** Uses full Allocation Units (typically 1 MB to 4 MB or larger) designed for large, sequential I/O operations. Target files include database data files, index tablespaces, temporary files, and RMAN backup sets.\n * **Fine-Grained Striping:** Breaks Allocation Units into smaller 128 KB stripe sets distributed across all member disks. Fine-grained striping is optimized for low-latency, small-payload write operations to minimize write latency and distribute rapid concurrent writes across physical devices. Target files include Online Redo Logs (ORLs), Control Files, and Flashback Logs.\n* **ASM Redundancy Models:**\n * **External Redundancy:** Delegates data protection entirely to underlying enterprise SAN hardware or host-level RAID controllers (such as RAID 10), providing no mirroring within ASM.\n * **Normal Redundancy:** Implements 2-way mirroring across ASM Failure Groups, requiring a minimum of two Failure Groups to protect against single-disk or array failures.\n * **High Redundancy:** Implements 3-way mirroring across ASM Failure Groups, requiring a minimum of three Failure Groups for mission-critical IFS setups demanding maximum data availability.\n* **Version Application:** The official **Oracle Automatic Storage Management Administrator's Guide** documents these ASM storage management concepts for Release 19c. The training program's architecture notes apply these storage configurations to IFS Applications (including IFS Cloud, IFS Applications 10, and IFS Applications 9).\n\n---\n\n### Objective 2: Implementing Range, List, and Hash Table Partitioning and Local Indexes\n\n* **Table Partitioning Strategy:** Table Partitioning breaks massive physical tables into smaller, manageable, independent logical segments. This enables the Oracle Cost-Based Optimizer (CBO) to execute **partition pruning**, which scans only specific partitions relevant to a query and improves performance across high-volume operational tables.\n* **Partitioning Methods:**\n * **Range Partitioning:** Maps data to partitions based on ranges of column values (such as transaction dates or order timestamps), making it the standard choice for time-series data like IFS audit logs and historical orders.\n * **List Partitioning:** Explicitly maps rows to partitions based on discrete lists of values in a column (such as regional site codes, business units, or country codes).\n * **Hash Partitioning:** Distributes data evenly across a specified number of partitions using a hash algorithm applied to a partitioning key column, preventing I/O hotspots on high-concurrency staging or interface tables.\n* **Index Strategies and Partition Maintenance:**\n * **Local Indexes:** Automatically partition in alignment with underlying table partitions; when a table partition is added or dropped, local indexes update automatically without requiring a full index rebuild.\n * **Global Indexes:** Span across all partitions independently of table structure, requiring maintenance or rebuilding after specific partition structural operations.\n * **Partition Maintenance Operations (PMO):** Allows database administrators to drop, truncate, merge, or split individual partitions instantly (such as dropping an obsolete archive partition via `ALTER TABLE DROP PARTITION`) without locking the entire table or executing expensive `DELETE` statements.\n* **Support and Version Context:** According to official IFS technical documentation for Release 25R1 (**screencapture-docs-ifs-techdocs-25r1-070...pdf**), **Oracle Partitioning** is an option supported for use with IFS Cloud and verified on IFS Applications 9 & 10, with table partitioning, global index partitions, and local index partitions tested and verified. The training architecture notes present table partitioning for massive transaction tables in Oracle Database 19c supporting IFS Cloud and IFS Applications 10/9.\n\n---\n\n### Objective 3: Setting Warning and Critical Storage Thresholds via DBMS_SERVER_ALERT and OEM\n\n* **Storage Threshold Architecture:** sudden tablespace exhaustion or ASM disk group filling can cause abrupt transaction failures, database freezes, and critical system outages in IFS Applications. Configuring proactive alert thresholds in Oracle Enterprise Manager (OEM) ensures early notification before storage capacity reaches 100 percent.\n* **Warning and Critical Threshold Levels:**\n * **Warning Thresholds:** Set at 85 percent capacity utilization to notify DBAs to investigate growing data files, clean up old staging tables, or schedule storage expansions during regular maintenance windows.\n * **Critical Thresholds:** Set at 95 percent capacity utilization to signify urgent storage pressure demanding immediate intervention to prevent space exhaustion and database halts.\n* **Alert Target Scope:**\n * **Tablespace Thresholds:** Monitor logical space allocation within individual data files and container/pluggable databases (CDB/PDB).\n * **ASM Disk Group Thresholds:** Monitor physical free space across physical disks and failure groups within shared storage pools like DATA and RECO.\n* **Programmatic Configuration (`DBMS_SERVER_ALERT`):**\n * Database administrators programmatically configure tablespace warning thresholds at 85 percent and critical thresholds at 95 percent using `DBMS_SERVER_ALERT.SET_THRESHOLD` with `metric_id => DBMS_SERVER_ALERT.TABLESPACE_SPACE_USAGE` and `dbobject_type => 'TABLESPACE'`.\n * DBAs verify registered threshold settings by querying the `DBA_THRESHOLDS` dictionary view.\n* **ASM Capacity Verification:** DBAs connect to the ASM instance (`+ASM`) and inspect disk group capacity and utilization percentages across `DATA` and `RECO` by querying `V$ASM_DISKGROUP`.\n* **Version Application:** The official **Oracle Database Database Reference, 19c** defines static data dictionary views such as `DBA_THRESHOLDS` and dynamic performance views such as `V$ASM_DISKGROUP` for Release 19c. The training architecture notes detail these threshold configurations for Oracle Database 19c environments supporting IFS Cloud and IFS Applications 10/9.", "cites": [], "image": "assets/teknik-gelistirim/chapter-4.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "RAC and Grid Infrastructure", "summary": "This chapter covers how active-active Oracle Real Application Clusters (RAC) clustering and Oracle Grid Infrastructure provide high availability, operational redundancy, and horizontal scalability for enterprise database workloads. The curriculum covers private Interconnect networking, High Availability IP (HAIP), Cache Fusion block transfers, and Global Resource Directory (GRD) synchronization over shared Automatic Storage Management (ASM) disk groups. Additionally, the chapter examines Oracle Maximum Availability Architecture (MAA) Silver, Gold, and Platinum tiers for Oracle Database 18c and 19c alongside dynamic workload management using SCAN listeners, Dynamic Database Services, and Fast Application Notification (FAN).", "objectives": ["configure Oracle Grid Infrastructure and private Interconnect networks using High Availability IP (HAIP) to enable Cache Fusion data block transfers and Global Resource Directory (GRD) lock coordination in Oracle RAC environments.", "evaluate Oracle Maximum Availability Architecture (MAA) Silver, Gold, and Platinum reference tiers for Oracle Database 19c to implement active-active clustering and disaster recovery solutions.", "administer Dynamic Database Services, Single Client Access Name (SCAN) listeners, and Fast Application Notification (FAN) in Oracle Database 18c and 19c to enable automated connection load balancing and high availability failover."], "lectures": [{"title": "Active-Active Node Clustering", "url": "", "type": "gemini_chat"}, {"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": "", "type": "gemini_chat"}, {"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf", "type": "pdf"}, {"title": "Oracle Real Application Clusters Real Application Clusters Administration and Deployment Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/", "type": "web_page"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/", "type": "web_page"}], "notes": "---\n\n### Objective 1: Configuring Grid Infrastructure, Private Interconnect Networks, HAIP, Cache Fusion, and GRD Lock Coordination\n\n* **Grid Infrastructure and Clusterware Architecture:** Oracle Grid Infrastructure combines Oracle Clusterware and Automatic Storage Management (Oracle ASM) into a single software stack that sits between the operating system and database instances. Oracle Clusterware provides the required infrastructure to run Oracle RAC and manages high-availability resources such as Virtual Internet Protocol (VIP) addresses, databases, listeners, and services.\n * **Cluster Synchronization Services (CSS):** CSS tracks node membership across the cluster, monitors node responsiveness, and executes node eviction if a node fails or loses communication to prevent split-brain scenarios.\n * **Cluster Ready Services (CRS) / Cluster Ready Services Daemon (CRSD):** CRSD manages high-availability resources including VIPs, Single Client Access Name (SCAN) listeners, database instances, and services, automatically restarting or relocating failed resources.\n * **Event Manager (EVM) / Event Manager Daemon (EVMD):** EVM publishes cluster events and alerts generated by Clusterware components to initiate rapid failover routines.\n* **Private Interconnect Network and HAIP Configuration:** Oracle RAC requires dedicated private network connectivity, known as the interconnect, used exclusively for inter-node and inter-instance communication.\n * **Interconnect Functionality:** The private interconnect network handles internal cluster communication, heartbeat signals, and Cache Fusion data block transfers directly between instance System Global Areas (SGAs) without writing data to disk.\n * **High Availability IP (HAIP):** High Availability IP (HAIP) or operating system level network interface card (NIC) bonding uses multiple physical NICs through Redundant Interconnect Usage to guarantee high throughput and zero downtime if an interconnect NIC fails.\n * **Verification:** Database administrators verify private interconnect configuration and active interfaces by querying the dynamic performance views V$CLUSTER_INTERCONNECTS and V$CONFIGURED_INTERCONNECTS.\n* **Cache Fusion and Global Resource Directory (GRD) Coordination:** Cache Fusion is a diskless cache coherency mechanism in Oracle RAC that transfers copies of data blocks directly from the memory cache of a holding instance to a requesting instance over the high-speed private interconnect.\n * **Resource Coordination:** Global Cache Service (GCS) and Global Enqueue Service (GES) coordinate buffer cache blocks and enqueues in the Global Resource Directory (GRD).\n * **GRD Functionality:** The GRD is distributed across all active instances and tracks the state, location, and lock status of every cached data block across all nodes to maintain transactional consistency.\n * **Background Processes:** Global Cache Service Processes (LMS / LMSn) record data file statuses and cached block information in the GRD, control message flow, and transmit block images between instance buffer caches. Global Enqueue Service Monitor (LMON) monitors global enqueues and resources across the cluster and performs global enqueue recovery. Global Enqueue Service Daemon (LMD) manages incoming remote resource requests within each instance.\n* **Version Application:** Redundant Interconnect Usage / HAIP is available in Oracle Grid Infrastructure 11g Release 2 (11.2) and later. Official manuals document these concepts for Oracle Database 19c. The training architecture notes apply Grid Infrastructure, private Interconnect, and Cache Fusion to IFS Applications (IFS Cloud, IFS Applications 10/9).\n\n---\n\n### Objective 2: Evaluating Oracle MAA Reference Tiers, Active-Active Clustering, and Disaster Recovery\n\n* **Oracle High Availability Framework and MAA:** Oracle Maximum Availability Architecture (MAA) provides an Oracle best practices blueprint based on proven Oracle high availability technologies and recommendations to remove complexity in designing an optimal high availability architecture.\n * **High Availability Blueprint Scope:** The official manual High Availability Best Practices and Overview for Release 19 structures high availability best practices across Oracle RAC and Clusterware best practices, Oracle Data Guard best practices, and MAA Platinum with Oracle GoldenGate best practices.\n * **Disaster Recovery Strategy:** For comprehensive protection against disasters, including data corruptions and regional disasters, Oracle recommends combining Oracle Data Guard with Oracle RAC.\n* **Active-Active Node Clustering Mechanics:** Active-Active Node Clustering using Oracle Real Application Clusters (RAC) enables multiple database instances running on separate physical servers to concurrently access a single shared database hosted on shared Automatic Storage Management (ASM) disk groups.\n * **Multi-Node Resource Execution:** In an active-active cluster, every node runs its own set of memory structures (SGA) and background processes. All active nodes actively accept connections and process concurrent transactions from application server pools.\n * **Application Redundancy:** Active-active clustering ensures continuous availability, operational redundancy, and seamless horizontal scalability for IFS mid-tier application server pools in IFS Applications (IFS Cloud, IFS Applications 10/9).\n * **Service-Level Prioritization:** On the service level, DBAs can define Gold, Silver, and Bronze services mapped to Resource Manager consumer groups to prioritize application workloads.\n* **Version Application:** High Availability Best Practices and Overview is documented for Release 19. Real Application Clusters Administration and Deployment Guide is documented for 19c. Active-active node clustering is applied to IFS Applications (IFS Cloud, IFS Applications 10/9) in the training architecture notes.\n\n---\n\n### Objective 3: Administering Dynamic Database Services, SCAN Listeners, and FAN in Oracle Database 18c and 19c\n\n* **Dynamic Database Services Administration:** Dynamic Database Services enable DBAs to group database workloads, route work to optimal instances, and achieve high availability.\n * **User-Defined Service Requirement:** Oracle Database automatically creates a default database service (identified by DB_NAME, DB_UNIQUE_NAME, or PDB_NAME), but Oracle strongly recommends that clients do not use default database services for application connections; DBAs should create user-defined dynamic database services using SRVCTL or Oracle Enterprise Manager.\n * **Resource Manager and Deployment Placement:** Services integrate with Oracle Database Resource Manager to map services to consumer groups and priorities. Services can be configured as singleton (running on one server instance at a time) or uniform (running across all active servers in a server pool).\n* **Single Client Access Name (SCAN) and Listener Routing:** Single Client Access Name (SCAN) is a single network name defined in DNS or Grid Naming Service (GNS) that round-robins to three IP addresses, allowing clients to connect without changing client connection strings when nodes are added to or removed from the cluster.\n * **Connection Routing Workflow:**\n 1. The client connects to SCAN (which includes a SCAN VIP on a public network) and provides a valid service name.\n 2. The SCAN listener determines which database instance hosts the service and routes the client to the local node listener on that node.\n 3. The local node listener (listening on a node VIP and port) connects the client to the instance on the local node.\n * **HTTP Protocol Awareness:** Starting in Oracle Database 12c Release 2 (12.2), SCAN listeners support HTTP protocol awareness to redirect HTTP clients across cluster nodes.\n * **Valid Node Checking:** Valid Node Checking for Registration (VNCR) restricts dynamic service registration with SCAN listeners to valid nodes and subnets.\n* **Fast Application Notification (FAN) and Connection Load Balancing:** Fast Application Notification (FAN) is part of the Oracle RAC high availability framework that publishes real-time cluster state notifications (UP and DOWN events for instances, services, nodes, networks, and load balancing metrics).\n * **ONS Transport:** All clients beginning with Oracle Database 12c Release 2 (12.2) use Oracle Notification Service (ONS) to receive FAN events.\n * **Failure Interruption:** FAN notifies integrated Oracle clients (JDBC Thin, OCI, ODP.NET, Universal Connection Pool, WebLogic Server Active GridLink) immediately when failures occur, breaking clients out of TCP/IP timeouts and preventing application hangs. Integrated clients use FAN DOWN events to clean up terminated connections immediately, and FAN UP events to route new connections to newly available instances.\n * **Connection Load Balancing:** Client-side load balancing (configured via LOAD_BALANCE=ON in client connection definitions) balances initial requests across SCAN listeners. Server-side load balancing uses SCAN listeners to direct connection requests based on the service connection load balancing goal (-clbgoal LONG or SHORT), with Oracle recommending -clbgoal LONG for server-side load balancing.\n * **Runtime Load Balancing:** Runtime connection load balancing uses Load Balancing Advisory events published via ONS (SERVICEMETRICS) with -rlbgoal SERVICE_TIME or THROUGHPUT to allocate connections in connection pools based on current service quality.\n* **Session Draining and Continuous Availability:** FAN planned DOWN events trigger session draining at request boundaries, enabling active work to complete without exposing errors to end users before taking an instance offline.\n * **Version Application:** Server-side session draining during planned maintenance was introduced in Oracle Database 18c. Transparent Application Continuity (TAC) was introduced in Oracle Database 18c as a functional mode of Application Continuity enabled by setting FAILOVER_TYPE=AUTO on database services. In Oracle Database 19c, TAC automatically tracks session and transactional state to enable transparent failover and safe replay boundaries.\n\n---\n\n💡 **Next Steps:** Would you like to review practice questions from your saved **RAC and Grid Infrastructure** quiz, or explore how FAN events interact with Universal Connection Pool (UCP) data sources during planned node draining?", "cites": [], "image": "assets/teknik-gelistirim/chapter-5.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Data Guard, MAA Standards and Failover Operations", "summary": "This chapter covers how to design, implement, and operate high availability and disaster recovery solutions for Oracle Database 19c supporting IFS Applications and IFS Cloud workloads. The curriculum covers Oracle Maximum Availability Architecture (MAA) Gold and Platinum standards, combining Oracle Real Application Clusters (RAC) with Active Data Guard (ADG), Real-Time Redo Apply via Standby Redo Logs (SRLs), and Data Guard Broker (dgmgrl) automation to achieve Recovery Point Objective (RPO = 0) and Recovery Time Objective (RTO < 5 minutes). Additionally, the chapter covers how to set proactive alert thresholds in Oracle Enterprise Manager (OEM) using DBMS_SERVER_ALERT for host CPU utilization at 85 percent warning and 95 percent critical, as well as Data Guard apply lag at 300 seconds warning and 900 seconds critical, while configuring dynamic mid-tier failover using SCAN listeners.", "objectives": ["deploy Oracle Maximum Availability Architecture (MAA) Gold and Platinum tiers for Oracle Database 19c by combining Oracle Real Application Clusters (RAC), Active Data Guard (ADG), and Edition-Based Redefinition (EBR) to enforce RPO = 0 and RTO < 5 minutes.", "administer Oracle 19c Data Guard Broker (dgmgrl) to execute automated planned switchover and emergency failover runbooks while managing Standby Redo Logs (SRLs) and Real-Time Redo Apply.", "configure warning and critical metric thresholds in Oracle Enterprise Manager (OEM) using DBMS_SERVER_ALERT for host CPU utilization at 85 percent warning and 95 percent critical, as well as Data Guard replication apply lag at 300 seconds warning and 900 seconds critical."], "lectures": [{"title": "Automated Switchover & Failover Runbooks", "url": "", "type": "gemini_chat"}, {"title": "Gold & Platinum MAA Standards Implementation", "url": "", "type": "gemini_chat"}, {"title": "RPO & RTO High Availability Optimization", "url": "", "type": "gemini_chat"}, {"title": "Real-Time Replica Synchronization", "url": "", "type": "gemini_chat"}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": "", "type": "gemini_chat"}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf", "type": "pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/", "type": "web_page"}], "notes": "---\n\n### Objective 1: Deploying Oracle MAA Gold and Platinum Tiers for Oracle Database 19c\n\n* **MAA Blueprint Scope:** Oracle Maximum Availability Architecture (MAA) provides a best practices blueprint and reference architecture for database high availability, disaster recovery, and data protection.\n* **Tier Selection for IFS Applications:** For enterprise environments running IFS Applications (IFS Cloud, IFS Applications 10/9), organizations target Gold and Platinum tiers to eliminate single points of failure, provide active-active scalability, and enforce strict Recovery Point Objectives (RPO = 0) and Recovery Time Objectives (RTO < 5 minutes).\n* **Gold Tier Architecture:** The MAA Gold tier combines Oracle Real Application Clusters (RAC) for local node failure protection with Active Data Guard (ADG) for remote disaster recovery. Gold tier uses synchronous or fast asynchronous redo transport, Application Continuity for transparent mid-tier session failover, and RMAN and Flashback technologies.\n* **Platinum Tier Architecture:** The MAA Platinum tier builds upon Gold by integrating active-active or multi-master replication solutions such as Oracle GoldenGate alongside Active Data Guard and RAC to eliminate maintenance window impact. Platinum tier utilizes Edition-Based Redefinition (EBR) to enable zero-downtime online application schema upgrades while the system is fully operational.\n* **Enforcing RPO and RTO Targets:** Enforcing RPO = 0 (zero data loss) is achieved by using Oracle Data Guard in synchronous (SYNC) protection mode. Achieving RTO < 5 minutes is accomplished by automating failover workflows using Data Guard Broker and Fast-Start Failover (FSFO).\n* **Version Application:** The training notes apply these MAA standards to IFS Applications (IFS Cloud, IFS Applications 10/9). Where general MAA tier definitions do not restrict a feature to a single database version, the sources do not explicitly state a database version limitation.\n\n---\n\n### Objective 2: Administering Oracle 19c Data Guard Broker (dgmgrl), Standby Redo Logs (SRLs), and Real-Time Redo Apply\n\n* **Role Transition Governance:** In enterprise deployments running IFS Applications (IFS Cloud, IFS Applications 10/9), Data Guard Switchover and Failover procedures maintain business continuity during planned maintenance or site outages. Data Guard Broker (dgmgrl) automates and validates planned switchover and emergency failover sequences across primary and standby nodes.\n* **Planned Switchover Operations:** A planned Switchover executes a clean, two-way role reversal that flushes pending redo data to guarantee zero data loss (RPO = 0) without database re-creation. During a switchover, IFS Applications mid-tier connection pools dynamically fail over using Single Client Access Name (SCAN) listeners and Fast Connection Failover (FCF) services.\n* **Emergency Failover Operations:** An emergency Failover executes a one-way role transition that forcibly promotes a standby database to primary status following an unexpected primary database failure.\n* **Standby Redo Logs (SRLs) Configuration:** Active Data Guard relies on Standby Redo Logs (SRLs) created on the standby database, which must be sized identically to the primary database online redo logs.\n* **Redo Transport Mechanics:** The Log Network Server (LNS) process on the primary instance transmits redo data over the network, and the Remote File Server (RFS) process on the standby instance receives the stream and writes it directly into Standby Redo Logs.\n* **Real-Time Redo Apply Execution:** Real-Time Redo Apply uses the Recovery Writer process (MRP0) to apply redo changes from active Standby Redo Logs immediately as they fill, eliminating traditional archive log shipping delays.\n* **Read-Only Reporting Offload:** Real-Time Apply enables the physical standby database to remain open in read-only mode, allowing IFS reporting queries and backups to offload production CPU overhead while staying current down to the last committed transaction.\n* **Version Application:** Official documentation details Data Guard concepts and administration for Oracle Data Guard Concepts and Administration, 19c, while training notes apply these workflows to IFS Applications (IFS Cloud, IFS Applications 10/9).\n\n---\n\n### Objective 3: Configuring Warning and Critical Metric Thresholds in OEM via DBMS_SERVER_ALERT\n\n* **OEM Metric Threshold Architecture:** For enterprise systems running IFS Applications (IFS Cloud, IFS Applications 10/9), configuring warning and critical alert thresholds in Oracle Enterprise Manager (OEM) ensures DBAs receive early notifications before performance bottlenecks disrupt core ERP, EAM, and FSM workloads. OEM evaluates monitored targets against predefined boundaries and triggers automated alerts when metrics cross limits.\n* **Host CPU Utilization Thresholds:** Host CPU utilization warning threshold is set at 85% utilization over a sustained interval to alert DBAs to investigate runaway queries, unindexed SQL statements, or insufficient server resource allocation. Host CPU utilization critical threshold is set at 95% utilization, signaling severe CPU saturation that causes process queuing, throttling, and mid-tier connection timeouts.\n* **Data Guard Replication Apply Lag Thresholds:** Data Guard replication apply lag warning threshold is set at 300 seconds (5 minutes), signaling that the physical standby database is falling behind the primary transaction stream and risking RPO compliance. Data Guard replication apply lag critical threshold is set at 900 seconds (15 minutes) or aligned with strict service level agreements, indicating major network transport bottlenecks, storage latency on Standby Redo Logs, or MRP apply stalls.\n* **Programmatic Configuration & Verification:** Host CPU utilization alert thresholds are programmatically configured using the DBMS_SERVER_ALERT package. Standby replication apply lag metrics and synchronization status are monitored and verified using dynamic performance views such as V$DATAGUARD_STATS.\n* **Version Application:** The training notes apply host CPU and Data Guard apply lag thresholds to IFS Applications (IFS Cloud, IFS Applications 10/9). The sources do not state a specific database version restriction for setting metric thresholds via DBMS_SERVER_ALERT.\n\n---\n\n💡 **Next Steps:** Would you like to review the step-by-step `dgmgrl` commands for testing Fast-Start Failover (FSFO), or create flashcards covering the OEM threshold parameters and V$DATAGUARD_STATS views?", "cites": [], "image": "assets/teknik-gelistirim/chapter-6.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Application Continuity and Resilience", "summary": "This chapter covers how to deploy Application Continuity (AC) and Transparent Application Continuity (TAC) in Oracle Database 19c and Oracle Database 18c environments supporting IFS Applications and enterprise ERP workloads. The curriculum details how Active Data Guard read-only open mode enables offloading heavy analytical queries away from the primary database while Managed Recovery Process (MRP) maintains real-time synchronization via Standby Redo Logs (SRLs). Additionally, the chapter examines Fast Connection Failover (FCF), Fast Application Notification (FAN), Transaction Guard commit outcome verification, and IFS mid-tier reconnection testing to achieve continuous application availability during planned maintenance or unplanned outages.", "objectives": ["configure Transparent Application Continuity (TAC) and Application Continuity (AC) service parameters in Oracle Database 19c using srvctl, including failovertype AUTO or TRANSACTION, commit_outcome TRUE, and failover_restore AUTO.", "offload read-only queries and operational reporting to an Active Data Guard physical standby database opened in read-only mode with real-time apply enabled using Standby Redo Logs (SRLs).", "test IFS mid-tier reconnection logic and Fast Connection Failover (FCF) using Oracle Notification Service (ONS) and SCAN listeners to ensure transparent session failover and session draining."], "lectures": [{"title": "Read-Only Query & Reporting Offloading", "url": "", "type": "gemini_chat"}, {"title": "IFS Mid-Tier Re-connection Logic Testing", "url": "", "type": "gemini_chat"}, {"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html", "type": "web_page"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf", "type": "pdf"}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": "", "type": "markdown"}], "notes": "Based on the provided sources, here is what each specified objective covers.\n\n---\n\n### Objective 1: Configuring TAC and AC Service Parameters in Oracle Database 19c Using `srvctl`\n\n* **Service Management Utility:** User-defined database application services supporting Application Continuity (AC) and Transparent Application Continuity (TAC) on Oracle RAC are created and modified using the `srvctl` command-line utility. (For single-instance databases, the `DBMS_SERVICE` package is used instead.)\n* **Failover Type Parameter (`-failovertype`):** \n * Setting `-failovertype AUTO` activates Transparent Application Continuity (TAC), introduced in Oracle Database 18c and supported in Oracle Database 19c. TAC dynamically analyzes session state transitions and transparently tracks session context, NLS settings, and transaction boundaries without requiring application code modifications or explicit request boundary declarations.\n * Setting `-failovertype TRANSACTION` enables manual Application Continuity (AC), introduced in Oracle Database 12c, which relies on application-aware connection pools and explicit request boundary declarations (`beginRequest` / `endRequest`) to track and replay uncommitted requests.\n* **Commit Outcome Parameter (`-commit_outcome`):** Setting `-commit_outcome TRUE` activates Transaction Guard. Transaction Guard assigns a persistent, globally unique Logical Transaction ID (LTXID) to user requests, enabling the replay engine to query the transaction outcome following an outage and prevent duplicate transaction execution.\n* **Failover Restore Parameter (`-failover_restore`):** \n * Setting `-failover_restore AUTO` enforces automatic session state restoration for TAC in Oracle Database 18c and 19c. In Oracle Database 19c, specifying `-failovertype AUTO` automatically sets `-failover_restore` to `AUTO`. This restores common session states, package variables, NLS formats, and temporary table contexts upon reconnection.\n * For manual Application Continuity (`-failovertype TRANSACTION`), setting `-failover_restore LEVEL1` restores preset common initial session states.\n* **Implicit Request Begin in Oracle Database 19c:** Starting in Oracle Database 19c, setting `FAILOVER_TYPE` to `AUTO` causes the Oracle JDBC driver to implicitly begin a request on each new physical connection created through the replay data source, enabling third-party connection pools to leverage TAC without code changes.\n* **Additional Operational Parameters:** Database administrators programmatically configure associated service parameters via `srvctl`, including `-clbgoal SHORT` (or `LONG`), `-rlbgoal SERVICE_TIME`, `-failoverretry 30` (or `10`), `-failoverdelay 10` (or `3`), `-replay_init_time 1800` (or `600`), `-retention 86400`, `-notification TRUE` (enabling FAN event delivery), `-drain_timeout 300` seconds, and `-stopoption IMMEDIATE`.\n\n---\n\n### Objective 2: Offloading Read-Only Queries and Operational Reporting to an Active Data Guard Physical Standby Database\n\n* **Active Data Guard Read-Only Open Mode:** In enterprise environments running IFS Applications (IFS Cloud, IFS Applications 10/9) or ERP workloads, Active Data Guard enables a physical standby database to open in read-only open mode (`READ ONLY`) while simultaneously applying incoming redo streams in real time.\n* **Real-Time Apply Mechanics:** Real-Time Apply uses the Managed Recovery Process (`MRP0` or `MRP`) to continuously apply redo blocks received from the primary database via Standby Redo Logs (SRLs) as they fill. This provides reporting sessions with near-instantaneous data synchronization (Recovery Point Objective, RPO near zero) without blocking or locking primary transaction writes.\n* **Workload Isolation Benefits:** Offloading resource-intensive analytical queries, end-of-month financial reports, and custom BI integrations to the physical standby database protects CPU and I/O capacity on primary production RAC nodes, maintaining high transaction throughput for core OLTP operations.\n* **Configuration Steps:** To open a physical standby database for read-only reporting offload:\n 1. Temporarily cancel active managed recovery: `ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL;`\n 2. Open the standby database instance in read-only mode: `ALTER DATABASE OPEN;`\n 3. Resume real-time apply while keeping the database open read-only: `ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT;`\n* **Diagnostic Verification:** DBAs verify operational status by querying `v$database` to confirm `DATABASE_ROLE` is `PHYSICAL STANDBY` and `OPEN_MODE` is `READ ONLY`, checking `v$managed_standby` to verify process `MRP0` status is `APPLYING_LOG`, and inspecting `v$dataguard_stats` to confirm `apply lag` is near zero.\n* **Version Application:** The training architecture notes detail Active Data Guard read-only offloading and SRL sizing for Oracle 19c Maximum Availability Architecture. The working notes apply read-only offloading procedures to IFS Applications (IFS Cloud, IFS Applications 10/9). Where general SQL commands do not specify a version limit, the sources do not name a version restriction.\n\n---\n\n### Objective 3: Testing IFS Mid-Tier Reconnection Logic, Fast Connection Failover (FCF), ONS, and SCAN Listeners\n\n* **Fast Connection Failover (FCF) and ONS Framework:** Fast Connection Failover (FCF) uses Oracle Clusterware and database events published via Oracle Notification Service (ONS) over TCP port 6200 to notify mid-tier connection pools (such as JDBC Universal Connection Pool or WebLogic Data Sources) immediately when a database instance or node fails. ONS notifications break client threads out of TCP/IP timeout hangs, allowing connection pools to instantly invalidate dead connections and re-route traffic to surviving or newly promoted nodes.\n* **Single Client Access Name (SCAN) Routing:** SCAN listeners direct initial client connection requests to available cluster nodes and load balance connections across active RAC instances.\n* **JDBC Thin Connection String Guidelines:** Starting in Oracle Database Release 12.1.0.2 / 12.2, JDBC Thin client connection descriptors require HA parameters including `TRANSPORT_CONNECT_TIMEOUT`, `CONNECT_TIMEOUT`, `RETRY_COUNT`, `RETRY_DELAY`, `FAILOVER=ON`, and `ADDRESS_LIST` definitions pointing to SCAN VIPs. Enabling ONS in UCP / Java data sources requires setting `fastConnectionFailoverEnabled=true` and configuring `onsConfiguration` or relying on auto-ONS via recommended TNS URLs.\n* **Planned Maintenance Session Draining:** Starting in Oracle Database 18c, the database marks sessions to drain during planned maintenance when instances, PDBs, or services are stopped or relocated. FAN planned-down events signal FAN-aware connection pools to clear idle sessions and allow active requests to complete gracefully within the allocated `drain_timeout` (e.g. 300 seconds) before `stopoption` (`IMMEDIATE`) applies.\n* **IFS Mid-Tier Reconnection Testing Procedure:** \n 1. Configure the IFS mid-tier data source URL with SCAN listener syntax and enable ONS configuration parameters (`PoolDataSourceFactory` property `setONSConfiguration`).\n 2. Initiate a planned Data Guard switchover from the Data Guard Broker command-line utility (`dgmgrl`) using `SWITCHOVER TO <standby_database>;`.\n 3. Inspect application server log files to verify that ONS failover events are received, broken pool connections are cleaned up, and SQL execution resumes seamlessly against the newly promoted primary database without manual intervention or application crashes.\n* **Version Application:** Auto-ONS configuration applies to Oracle Database 12c client drivers and later. Connection string parameters like `TRANSPORT_CONNECT_TIMEOUT` apply to Oracle Database Release 12.1.0.2 / 12.2 and higher. Server-side session draining was introduced in Oracle Database 18c. The training working notes detail mid-tier reconnection testing for IFS Applications (IFS Cloud, IFS Applications 10/9).\n\n---\n\n💡 **Next Steps:** Would you like to review practice questions covering TAC and AC service parameters, or explore how `srvctl` commands interact with Data Guard role transitions?", "cites": [], "image": "assets/teknik-gelistirim/chapter-7.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Performance Management and Tuning", "summary": "This chapter covers how to diagnose and optimize database performance across memory architecture, session capacity, SQL execution, and recovery subsystems for IFS Applications. The curriculum covers instance memory tuning for sga_target and pga_aggregate_target, capacity parameter tuning for open_cursors and processes, AWR and ADDM report profiling during peak business hours and batch runs, and root-cause analysis of wait events including db file sequential read, db file scattered read, enq: TX - row lock contention, and latch contention. Additionally, the chapter covers Active Session History (ASH) diagnostics, execution plan profiling using DBMS_XPLAN.DISPLAY_CURSOR, and single-command RMAN table-level point in time recovery (RECOVER TABLE) introduced in Oracle Database 12c and extended in Oracle Database 19c and Oracle 26ai.", "objectives": ["configure instance memory parameters sga_target and pga_aggregate_target alongside session parameters open_cursors and processes to optimize SGA memory pools and prevent ORA-01000 and ORA-00020 capacity errors in Oracle Database 19c.", "evaluate Automatic Workload Repository (AWR) reports, Automatic Database Diagnostic Monitor (ADDM) recommendations, and Active Session History (ASH) sampling metrics to isolate I/O bottlenecks, row-level locking, and latch contention.", "execute RMAN table-level point in time recovery (RECOVER TABLE PITR) with an auxiliary destination in Oracle Database 12c, Oracle Database 19c, and Oracle 26ai to restore dropped or purged tables without full database restores or system downtime."], "lectures": [{"title": "Memory Architecture Tuning (sga_target & pga_aggregate_target)", "url": "", "type": "gemini_chat"}, {"title": "Session & Cursor Capacity Parameter Tuning (open_cursors & processes)", "url": "", "type": "gemini_chat"}, {"title": "Execution Plan Profiling & Index Strategies", "url": "", "type": "gemini_chat"}, {"title": "ADDM Report Analysis & Proactive Recommendations", "url": "", "type": "gemini_chat"}, {"title": "Peak Hours & Batch Run AWR Generation", "url": "", "type": "gemini_chat"}, {"title": "I/O Bottleneck Identification", "url": "", "type": "gemini_chat"}, {"title": "AWR Performance Metrics Interpretation", "url": "", "type": "gemini_chat"}, {"title": "Locking & Latch Contention Drill-Downs", "url": "", "type": "gemini_chat"}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html", "type": "web_page"}, {"title": "Database Performance Tuning Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/tgdba/", "type": "web_page"}, {"title": "Recovering Tables and Table Partitions", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-recovering-tables-partitions.html", "type": "web_page"}, {"title": "Transporting Data Across Platforms", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-transporting-data-across-platforms.html", "type": "web_page"}], "notes": "---\n\n### Objective 1: Memory Architecture and Capacity Parameter Tuning (sga_target, pga_aggregate_target, open_cursors, processes)\n\n* **System Global Area (SGA) Tuning (sga_target):** The System Global Area (SGA) is an instance-wide shared memory structure allocated at database startup. Setting `sga_target` to a non-zero value activates Automatic Shared Memory Management (ASMM), allowing Oracle to dynamically tune memory pools including the Buffer Cache (caching data blocks read from disk to optimize query response times), Shared Pool (storing parsed SQL, PL/SQL code, execution plans, and data dictionary information essential for IFS mid-tier session reuse), Large Pool, and Java Pool. Dynamically tuning SGA memory pools prevents hard parses and disk I/O bottlenecks during peak transactional hours in environments running IFS Applications (IFS Cloud and IFS Applications 10/9).\n* **Program Global Area (PGA) Tuning (pga_aggregate_target):** The Program Global Area (PGA) is non-shared memory allocated individually for each server process handling a user session connection. Setting `pga_aggregate_target` establishes an instance-wide global target for total PGA memory allocated across all sessions. Oracle dynamically controls memory allocated to individual work areas for sort operations (ORDER BY), hash joins, and bitmap merges to stay within this limit under peak batch workloads, preventing excessive temporary tablespace spilling during heavy batch reports.\n* **Processes Capacity Parameter Tuning (processes):** The static initialization parameter `processes` defines the maximum number of operating system user processes that can simultaneously connect to the Oracle Database instance. Dedicated mid-tier connection pools, background processes (such as PMON, DBWn, and LGWR), and DBA sessions consume process slots. Setting `processes` too low causes connection rejections with `ORA-00020: maximum number of processes exceeded`, preventing mid-tier application servers from establishing new sessions during traffic spikes.\n* **Open Cursors Capacity Parameter Tuning (open_cursors):** The dynamic parameter `open_cursors` specifies the maximum number of open cursors a single session can hold simultaneously in the Private SQL Area. Cursors handle parsed SQL statements and PL/SQL blocks, and mid-tier frameworks (such as Java/JDBC pools in IFS) cache statement handles to boost execution speed. Setting `open_cursors` sufficiently high accommodates statement caching per session without leaking cursors or exceeding Shared Pool memory limits, preventing `ORA-01000: maximum open cursors exceeded` errors.\n* **Version Application:** The training sources apply these memory and capacity parameter configurations to IFS Applications (IFS Cloud and IFS Applications 10/9) workloads. The provided sources do not specify a database version restriction (such as Oracle Database 19c) for these parameter definitions, so the sources do not explicitly state which database version applies to these parameters.\n\n---\n\n### Objective 2: Performance Evaluation using AWR Reports, ADDM Recommendations, and ASH Sampling Metrics\n\n* **Automatic Workload Repository (AWR) Analysis:** AWR serves as Oracle's built-in historical performance data warehouse, automatically capturing snapshots (defaulting to 60 minutes) and retaining statistics (defaulting to 8 days) in the SYSAUX tablespace via the Memory Monitor (MMON) background process. Database administrators analyze AWR reports to evaluate DB Time (cumulative time spent by active non-idle user sessions inside the database) against Elapsed Time (total wall-clock time between snapshots); if DB Time significantly exceeds Elapsed Time, the system is running under high concurrency or encountering severe wait contention. AWR Load Profile metrics track per-second and per-transaction throughput, including logical reads, physical reads, block changes, redo size, and hard parses, generated using the standard script `awrrpt.sql`. AWR Compare Period reports (`awrddrpt.sql` for single-instance or `awrddrpi.sql` for RAC environments) generate side-by-side metric comparisons between two distinct time periods to evaluate performance changes before and after applying patches.\n* **Automatic Database Diagnostic Monitor (ADDM) Recommendations:** ADDM serves as an intelligent diagnostic engine built directly into Oracle Database that executes automatically after every AWR snapshot (by default, every 60 minutes). ADDM analyzes the performance delta between snapshot pairs based on DB Time consumption, conducts a tree-structured top-down bottleneck analysis, eliminates non-problem areas, and delivers prioritized recommendations covering hardware capacity, database configuration (`sga_target`, `pga_aggregate_target`, `open_cursors`, `processes`), and schema/SQL optimization. ADDM findings can be queried programmatically via `DBA_ADDM_FINDINGS` and `DBA_ADDM_TASKS` or viewed via `addmrpt.sql`.\n* **Active Session History (ASH) Diagnostics:** ASH samples active database sessions every second into an SGA ring buffer (`v$active_session_history`), capturing fine-grained performance data for active sessions consuming CPU or waiting on non-idle wait events. Second-by-second sampling allows DBAs to isolate transient, short-term performance spikes during batch runs that hourly AWR snapshot averages smooth out. Historical ASH data flushed to disk by MMON is queried via `dba_hist_active_sess_history`.\n* **Isolating Physical I/O Bottlenecks:** Physical I/O bottlenecks are isolated in ASH views (`v$active_session_history` or `dba_hist_active_sess_history`) by analyzing specific wait events: `db file sequential read` (single-block reads typical for index lookups or nested loop joins; high wait counts indicate unindexed queries, fragmented indexes, storage latency on DATA disk groups, or unselective B-Tree index range scans), `db file scattered read` (multi-block reads typical for Full Table Scans or Fast Full Index Scans), and `direct path read` / `direct path write` (direct I/O bypassing the buffer cache, caused by large sorts, hash joins spilling to temporary tablespaces, or parallel queries). Joining `v$active_session_history` with `dba_users` and `dba_objects` maps active sessions directly to specific SQL IDs (`sql_id`), usernames, programs, and database objects experiencing disk contention. Combining ASH queries with execution plan profiling via `DBMS_XPLAN.DISPLAY_CURSOR` allows DBAs to inspect runtime access paths (`TABLE ACCESS FULL`, `INDEX RANGE SCAN`) and compare estimated rows (`E-Rows`) against actual rows (`A-Rows`) to identify stale table statistics or suboptimal optimizer plans.\n* **Isolating Row-Level Locking Contention:** Transactional row-level locking contention is isolated using the wait event `enq: TX - row lock contention`, which occurs when sessions wait for row-level locks held by uncommitted transactions. High enqueue wait counts in IFS environments typically stem from concurrent updates to the same customer order, inventory balance, or financial ledger records without proper queuing.\n* **Isolating Memory Latch Contention:** Internal memory latches are lightweight serialization mechanisms protecting shared data structures within the System Global Area (SGA). `Cache Buffers Chains` latch contention arises from hot blocks (frequently accessed data blocks accessed concurrently by multiple sessions, such as sequence generators or high-frequency status update tables). Shared Pool and Library Cache latches and mutexes (such as `cursor: mutex S`, `cursor: mutex X`, `cursor: pin S`, `cursor: pin S wait on X`, `cursor: pin X`, and `library cache: mutex X`) are triggered by excessive hard parsing, unshared SQL statements, or frequent cursor reloads under high mid-tier connection volume.\n* **Version Application:** The official manual Database Performance Tuning Guide 19c provides database performance tuning fundamentals, while Database Reference 18 documents wait event descriptions. The training notes apply AWR, ADDM, and ASH profiling workflows to IFS Applications (IFS Cloud and IFS Applications 10/9) workloads. Where general AWR, ADDM, and ASH mechanics are presented without specifying a single database version, the sources do not explicitly state a version restriction.\n\n---\n\n### Objective 3: RMAN Table-Level Point in Time Recovery (RECOVER TABLE PITR)\n\n* **Purpose and Benefits:** The RMAN `RECOVER TABLE` command enables database administrators to recover one or more tables or table partitions to a specified point in time from RMAN backups without affecting remaining database objects or requiring full database restores or system downtime. This is useful when recovering tables that have been logically corrupted or dropped and purged, when Flashback Table is not possible because the target time is older than available undo, or when DDL structural changes (such as truncate table operations) prevent Flashback Table.\n* **Prerequisites and Required Backups:** The target database must be in ARCHIVELOG mode and read-write mode. RMAN requires a full backup of undo, SYSTEM, SYSAUX, and the tablespaces containing the target tables or partitions. For pluggable databases (PDBs), backups of the SYSTEM, SYSAUX, and undo tablespaces of the root container (CDB$ROOT), CDB seed (PDB$SEED), and the specific PDB containing the tables are required. Tables or partitions belonging to the SYS schema or SYSTEM and SYSAUX tablespaces cannot be recovered.\n* **Point-in-Time Specification:** The point in time for recovery is specified using `UNTIL TIME` (a timestamp expression), `UNTIL SCN` (System Change Number), or `UNTIL SEQUENCE` (redo log sequence number and thread).\n* **Automated Auxiliary Database Workflow:**\n 1. RMAN determines which backup contains the target tables or partitions based on the specified point in time.\n 2. RMAN checks space availability on the target host and automatically provisions an auxiliary database instance using the `AUXILIARY DESTINATION` clause (or `SET NEWNAME` commands) to store data files for the auxiliary database.\n 3. RMAN restores the necessary data files and recovers the specified tables or partitions to the designated point in time inside the auxiliary database.\n 4. RMAN creates a Data Pump export dump file containing the recovered objects, with the directory specified via `DATAPUMP DESTINATION` (defaulting to `AUXILIARY DESTINATION` or `$ORACLE_HOME/dbs` on Linux) and the filename specified via `DUMP FILE`.\n 5. By default, RMAN automatically imports the Data Pump export dump file into the target database. Specifying `NOTABLEIMPORT` recovers the tables to the specified point in time and generates the dump file without performing the import, allowing manual import later via Data Pump Import.\n* **Remapping Tables, Schemas, and Tablespaces:** DBAs use the `REMAP TABLE` clause to rename recovered tables or table partitions in the target database. Starting in Oracle Database 12c Release 2 (12.2), `REMAP TABLE` also enables recovering tables or table partitions into a schema different from the original source schema. The `REMAP TABLESPACE` clause imports recovered objects into a tablespace different from their original tablespace.\n* **PDB Support:** In multitenant environments, tables in a PDB are recovered using `RECOVER TABLE ... OF PLUGGABLE DATABASE <pdb_name>` while connected to the root container or target PDB, recovering the table without impacting other objects in the PDB.\n* **Version Application:** The official manual Backup and Recovery User Guide 19 documents `RECOVER TABLE` procedures for Oracle Database 19c and highlights schema remapping introduced in Oracle Database 12c Release 2 (12.2). The provided sources do not mention or state facts regarding Oracle 26ai for `RECOVER TABLE`.\n\n---\n\n💡 **Next Steps:** Would you like to review practice questions from your saved **Performance Management and Tuning** quiz app, or explore the SQL scripts for querying `v$active_session_history` during peak batch runs?", "cites": [], "image": "assets/teknik-gelistirim/chapter-8.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Monitoring, Alerting and Incident Management", "summary": "This chapter covers how to establish and maintain centralized enterprise monitoring infrastructure using Oracle Enterprise Manager (OEM) Cloud Control 13c/14c, encompassing Oracle Management Service (OMS), Oracle Management Repository (OMR), and multi-node Oracle Management Agent (OMA) administration using emctl. The curriculum covers automated event management, incident rule set promotion, notification pipelines, blackout scheduling, and EFK stack log monitoring in IFS Cloud 25R1. Additionally, the chapter covers operational telemetry governance in IFS Cloud 26R2 using Application Monitoring Metrics (AMM), Application Monitoring Console, Server Alert Log categories, Oracle Advanced Queues, and Streams background job notifications.", "objectives": ["deploy and administer Oracle Enterprise Manager (OEM) Cloud Control 13c/14c infrastructure components, including Oracle Management Service (OMS), SYSMAN repository schema, and Oracle Management Agent (OMA) processes using the emctl CLI utility.", "configure OEM event management, incident rule set logic, blackout schedules, and notification delivery methods to automatically promote metric alerts to actionable incidents while suppressing false-positive alerts.", "utilize Application Monitoring Console (AMM) metrics, Server Alert Log categories, Oracle Advanced Queues, Streams background job notifications, and EFK stack dashboards to oversee system performance in IFS Cloud 25R1 and IFS Cloud 26R2."], "lectures": [{"title": "OEM 13c/14c Infrastructure Setup", "url": "", "type": "gemini_chat"}, {"title": "OEM Agent Administration across Nodes", "url": "", "type": "gemini_chat"}, {"title": "Automated Incident Rule sets & Notifications", "url": "", "type": "gemini_chat"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": "", "type": "pdf"}], "notes": "---\n\n### Objective 1: Deploying and Administering OEM Cloud Control 13c/14c Infrastructure Components\n\n* **Enterprise Infrastructure Architecture:** Oracle Enterprise Manager (OEM) Cloud Control provides a multi-tier management framework to collect, process, and store performance diagnostics across managed targets, including Oracle RAC nodes, ASM instances, PDBs/CDBs, and host servers.\n* **Oracle Management Service (OMS):** OMS is a middle-tier Java EE application running on Oracle WebLogic Server. It processes metrics uploaded by host agents, renders the browser-based Cloud Control management console, dispatches administrative jobs, and manages notification alerts.\n* **Oracle Management Repository (OMR):** OMR is a dedicated Oracle Database that houses the SYSMAN repository schema. It stores configuration data, target health metrics, historical performance baselines, job execution logs, and incident tracking data.\n* **Oracle Management Agent (OMA):** OMA processes deploy directly on each managed host server to continuously sample host CPU utilization, memory thresholds, ASM disk group space, and database instance availability. Agents communicate securely with the central OMS via dedicated bidirectional TCP port 3872 using HTTP/HTTPS protocols.\n* **Management Plug-ins:** Plug-ins are software extensions integrated into OMS and OMA to extend monitoring capabilities to specific hardware, storage arrays, third-party databases, or enterprise application mid-tiers.\n* **CLI Administration via `emctl`:** Database administrators use the `emctl` utility on the OMS host server to verify WebLogic services, HTTP server status, and repository connectivity. On managed cluster nodes, DBAs navigate to the agent execution directory (such as `/u01/app/oracle/agent/agent_inst/bin`) and run `./emctl status agent` to verify agent process health and OMS ping connectivity, or `./emctl upload agent` to force an immediate upload of collected telemetry payload files to the OMS repository.\n* **Version Context:** The training notes title this infrastructure setup as OEM 13c/14c Infrastructure Setup for environments running IFS Applications (IFS Cloud, IFS Applications 10/9). Where the sources describe component roles and `emctl` commands without distinguishing between 13c and 14c, the sources do not specify a version limitation.\n\n---\n\n### Objective 2: Configuring OEM Event Management, Incident Rule Sets, Blackout Schedules, and Notifications\n\n* **Event to Incident Promotion Framework:** The Oracle Management Agent (OMA) continuously samples target metrics and generates an Event when a metric crosses a warning or critical threshold, such as host CPU utilization exceeding 95%. Pre-configured incident rules evaluate event severity and automatically promote severe events into tracked Incidents in OEM, representing actionable operational issues requiring administrative intervention.\n* **Incident Rule Sets:** Rule sets define the core logic for processing events and incidents. They govern automated actions such as sending email notifications, executing corrective action scripts, or creating tickets in external enterprise ticketing systems (such as ServiceNow or Jira) based on target criteria, severity levels, and time windows.\n* **Notification Delivery Methods:** OEM incorporates a notification framework supporting transport channels including SMTP email, SNMP traps, and operating system scripts or webhooks. Subscriber lists map specific incident severity levels to designated notification subscribers.\n* **Blackouts:** Administrative Blackouts can be scheduled during planned maintenance windows to temporarily suppress notifications and prevent false-positive alerts across IFS staging or production environments.\n* **Incident History Verification:** DBAs verify active critical incidents by querying the OMR repository view `sysman.em_incidents` for `target_name`, `target_type`, `incident_name`, `severity`, `creation_date`, and `status`.\n* **Version Context:** The training source applies event management and incident rule sets to IFS Applications (IFS Cloud, IFS Applications 10/9). The source does not state a specific database version restriction for setting up OEM incident rule sets and blackout schedules.\n\n---\n\n### Objective 3: Utilizing Monitoring Frameworks, Alert Logs, Advanced Queues, Streams, and EFK Stack Dashboards in IFS Cloud\n\n* **IFS Cloud 25R1 Log Monitoring with EFK Stack:** In IFS Cloud 25R1 Remote Deployment, log monitoring uses an EFK stack comprising Elasticsearch, Fluentd, and Kibana. Elasticsearch stores system activity logs with a 7-day data retention period, managed by a daily curator cronjob. Fluentd acts as a log shipper collecting and forwarding log data. Kibana provides data visualization and dashboards using Kibana Query Language (KQL). Imported Kibana dashboards include the Response Time Detail View Dashboard, which displays projection and entity metrics automatically sorted from highest response time to lowest response time by default.\n* **IFS Cloud 26R2 Application Monitoring Metrics (AMM):** In IFS Cloud 26R2, AMM structures health indicators across a hierarchy of Metric, Threshold, Service, Service Groups, Expression, and Interval. AMM exported metric categories include BATCH_QUEUES (such as BATCH_QUEUE_CONFIG, BATCH_QUEUE_ACTIVE, BATCH_QUEUE_PROC, QUEUE_PROCESSES, DEFERRED_JOBS_EXECUTING_12H, and STUCK_BATCH_QUEUE_PROCESSES), QUEUE_ENTRIES - Background Jobs (QUEUE_READY, QUEUE_WAIT, QUEUE_EXEC, QUEUE_ERROR), and DATABASE_CONFIG (SGA_TARGET, PGA_AGGREGATE_LIMIT, DB_SESSIONS, DB_ACTIVE_SESSIONS, DB_BLOCKED_SESSIONS).\n* **IFS Cloud 26R2 Application Monitoring Console:** Accessed in Solution Manager under Solution Manager / Monitoring / Application Monitoring Console, this console displays upper and lower warning limits for monitored entries. It features a \"Show Alarms Only\" filter and a Details view to inspect granular data, such as active batch queue processes.\n* **IFS Cloud 26R2 Server Alert Log Categories:** Located in Solution Manager under Solution Manager / Monitoring / Server Alert Log Categories, administrators configure logging using Category ID, Description, Enable, Cleanup, and Days to keep parameters. Standard categories include Ddl Audit (logs database DDL statements via a database trigger), Debug, Deployment, Deployment detail, Event errors, Server Errors (traces database errors via an AFTER ERROR trigger), Sql Injections (traces suspected SQL injections via `Assert_SYS`), and In-Memory (logs index removal for In-Memory tables).\n* **IFS Cloud 26R2 Oracle Advanced Queues:** The Oracle Queues window in IFS Cloud enables starting, stopping, and purging queue tables for asynchronous background messaging, while the Oracle Queue Subscribers window tracks registered consumers and allows removing subscribers.\n* **IFS Cloud 26R2 Streams Background Jobs:** Streams functionality alerts end users when background jobs or reports finish running, handling one-time background jobs (`Transaction_SYS.Deferred_Call`) and scheduled tasks (`Batch_SYS.New_Batch_Schedule`) executed by the `Transaction_SYS.Process_All_Pending` scheduler. Notifications are configured using opt-in parameters `stream_msg_on_completion_` (set to TRUE) and `stream_notes_`. Notification text can be customized using the Hooking API `Transaction_SYS.Modify_Stream_Notification`.\n* **IFS Cloud 26R2 System Performance Screens:** Real-time database performance monitoring utilizes the `v$sql` view in Solution Manager. The Custom Field Runtime Performance Overview screen filters active queries with an average elapsed time exceeding 2 seconds, while the All SQL Runtime Performance Overview screen displays overall SQL execution metrics sorted by default in descending order of Elapsed Time / Exec (s).\n* **Version Context:** The sources explicitly distinguish between IFS Cloud 25R1 (EFK stack and Kibana Response Time Detail View) and IFS Cloud 26R2 (AMM metrics, Application Monitoring Console, Server Alert Log Categories, Oracle Queues, Streams background job notifications, and `v$sql` performance screens).\n\n---\n\n💡 **Next Steps:** Would you like to generate practice flashcards covering OEM `emctl` commands and AMM metric categories, or create a quiz to test your understanding of IFS Cloud 26R2 alert log categories and Streams notifications?", "cites": [], "image": "assets/teknik-gelistirim/chapter-9.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Backup, Recovery and Operational Practice", "summary": "This chapter covers how to design, execute, and evaluate backup, recovery, and disaster recovery architectures for enterprise Oracle database environments supporting IFS Applications and ERP workloads. The curriculum covers Oracle Maximum Availability Architecture (MAA) Silver and Gold deployment topologies on Oracle Database@Azure, cross-platform migration from legacy Big-Endian environments to Oracle Database 19c or 26ai using Cross-Platform Transportable Tablespaces (XTTS v4) and Full Transportable Export/Import (FTEX), and Recovery Manager (RMAN) backup and recovery workflows. Additionally, the chapter covers post-outage incident reviews, investigating uncompleted batch cleanup processes using diagnostic queries against dba_scheduler_job_run_details and v$diag_alert_ext to refine pre-deployment checklists without requiring Diagnostics or Tuning Pack licenses, while completing comprehensive skills assessments on database resilience.", "objectives": ["deploy Oracle Maximum Availability Architecture (MAA) Silver and Gold topologies on Oracle Database@Azure and execute cross-platform migration to Oracle Database 19c and 26ai using Cross-Platform Transportable Tablespaces (XTTS v4) with Full Transportable Export/Import (FTEX).", "execute Recovery Manager (RMAN) backup, restore, and recovery operations in Oracle Database 19c, managing commands such as RESTORE, RECOVER, DUPLICATE, and FLASHBACK DATABASE while accounting for the deprecation of the Data Recovery Advisor (DRA).", "conduct post-outage incident investigations for incomplete IFS batch cleanup jobs using queries against dba_scheduler_job_run_details and v$diag_alert_ext to refine pre-deployment checklists and monitoring thresholds."], "lectures": [{"title": "IFS Enterprise Oracle Architecture & DBA Training Program Practice Test", "url": "", "type": "gemini_chat"}, {"title": "Kesinti incelemesi hazırlığı, 11.11.2026.docx", "url": "", "type": "docx"}, {"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf", "type": "pdf"}, {"title": "Backup and Recovery User Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/", "type": "web_page"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html", "type": "web_page"}, {"title": "Transporting Data Across Platforms", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-transporting-data-across-platforms.html", "type": "web_page"}], "notes": "Based on the selected sources, here is what each specified objective covers.\n\n---\n\n### Objective 1: Deploying MAA Silver and Gold Topologies on Oracle Database@Azure and Cross-Platform Migration\n\n* **MAA Silver Architecture on Oracle Database@Azure:** the MAA Silver reference architecture on Exadata Database Service on Dedicated Infrastructure (ExaDB-D) protects against local compute or software failures within a single Azure Availability Zone (AZ) using Oracle RAC for transparent node failover. MAA Silver integrates with Autonomous Recovery Service (ARS) for an incremental forever backup strategy with real-time data protection. Deploying application VMs in the same Availability Zone as the database cluster achieves low application-to-database latency between 200 and 400 microseconds (or 300 to 500 microseconds).\n* **MAA Gold Architecture on Oracle Database@Azure:** the MAA Gold architecture uses Oracle Data Guard across separate Azure Availability Zones or regions to enforce zero data loss (Recovery Point Objective, RPO = 0) and rapid recovery (Recovery Time Objective, RTO). Cross-AZ Gold deployments use zero-data-loss synchronous replication, while cross-region deployments use OCI VCN Peering (recommended for higher single-process throughput) or Azure VNet Peering, with TDE encryption keys replicated via OCI Private Vault.\n* **MAA Platinum Architecture on Oracle Database@Azure:** MAA Platinum Option 1 requires Oracle AI Database 26ai or higher and Oracle Active Data Guard.\n* **Cross-Platform Migration:** RMAN supports cross-platform data transport using image copies (`CONVERT TABLESPACE`, `CONVERT DATAFILE`, `CONVERT DATABASE`) and backup sets (`BACKUP ... FOR TRANSPORT` or `TO PLATFORM`, `RESTORE ... FROM PLATFORM`) based on platform endian formats listed in `V$TRANSPORTABLE_PLATFORM`. \n* **Coverage Limitation:** The selected sources do not cover Cross-Platform Transportable Tablespaces (XTTS v4) or Full Transportable Export/Import (FTEX).\n\n---\n\n### Objective 2: RMAN Backup, Restore, and Recovery Operations in Oracle Database 19c and Data Recovery Advisor (DRA) Deprecation\n\n* **Deprecation of Data Recovery Advisor (DRA) in Oracle Database 19c:** Starting in Oracle Database 19c, the Data Recovery Advisor (DRA) feature is deprecated. This deprecation includes the Recovery Manager (RMAN) commands `LIST FAILURE`, `ADVISE FAILURE`, `REPAIR FAILURE`, and `CHANGE FAILURE`. Database administrators no longer have access to these commands in Oracle Database 19c, and Oracle provides no replacement feature for DRA.\n* **Executing RMAN `RESTORE` in Oracle Database 19c:** The `RESTORE` command restores data files, control files, server parameter files (spfile), or archived redo logs from backup sets or disk copies. In Oracle Database 19c (and 18c), `RESTORE` supports `AS ENCRYPTED` or `AS DECRYPTED` clauses when moving unencrypted or encrypted databases between on-premises environments and Oracle Cloud. `RESTORE` also supports restoring cross-platform backups using `RESTORE FROM PLATFORM` or `RESTORE ALL FOREIGN DATAFILES`.\n* **Executing RMAN `RECOVER` in Oracle Database 19c:** The `RECOVER` command applies redo log files and incremental backups to restored data files. In Oracle Database 19c, the `RECOVER...SNAPSHOT TIME` method of point-in-time recovery using storage snapshots is deprecated. Oracle recommends executing `ALTER DATABASE BEGIN/END BACKUP` around storage snapshots, followed by `RECOVER...UNTIL TIME` to a timestamp or SCN after the `END BACKUP` completion time. `RECOVER` supports recovering pluggable databases (`RECOVER PLUGGABLE DATABASE`) and table recovery (`RECOVER TABLE`).\n* **Executing RMAN `DUPLICATE` in Oracle Database 19c:** The `DUPLICATE` command creates a duplicate database with a unique DBID for testing or a standby database retaining the primary DBID for Data Guard. Starting in release 18c and supported in Oracle Database 19c, `DUPLICATE PLUGGABLE DATABASE` allows duplicating a PDB into an existing CDB when `COMPATIBLE` is set to 18.0.0 or higher. `DUPLICATE` supports `AS ENCRYPTED` or `AS DECRYPTED` clauses when duplicating databases to or from Oracle Cloud.\n* **Executing RMAN `FLASHBACK DATABASE`:** The `FLASHBACK DATABASE` command rewinds the entire database (CDB) or a specific PDB to a target time, SCN, log sequence number, or restore point using flashback logs stored in the fast recovery area without restoring data files. Flashback operations on a proxy PDB are not supported.\n\n---\n\n### Objective 3: Post-Outage Incident Investigations for Incomplete IFS Batch Cleanup Jobs\n\n* **Incident Context and Sequential Cleanup:** Investigating past system outages caused when batch cleanup processes failed to finish prior to a deployment. Cleanup steps execute sequentially, meaning if one step gets stuck, subsequent steps wait.\n* **Executing Diagnostic SQL Queries:** Database administrators run read-only SQL queries that do not require Oracle Diagnostics Pack or Tuning Pack licenses:\n * **`dba_scheduler_job_run_details` View:** Querying `dba_scheduler_job_run_details` inspects Oracle Scheduler job execution history during the incident timeframe (`WHERE actual_start_date BETWEEN :bas AND :bit`), examining `owner`, `job_name`, `status`, `actual_start_date`, `run_duration`, and `error#`.\n * **`v$diag_alert_ext` View:** Querying `v$diag_alert_ext` inspects Oracle alert log entries during the incident window (`WHERE originating_timestamp BETWEEN :bas AND :bit`), filtering for error messages containing `%ORA-%` or `%deadlock%`.\n* **Refining Pre-Deployment Checklists and Monitoring Thresholds:**\n * Investigation findings are used to add a mandatory pre-deployment verification check (\"no active running background jobs\") to the DBA runbook and pre-flight deployment checklist to halt deployment while background jobs remain active.\n * Investigation findings help establish monitoring rules and alarm thresholds to track active background job durations, error counts for waiting or failed jobs, and the last successful completion timestamp of Cleanup tasks.\n\n---\n\n💡 Would you like to review practice questions from your saved **RMAN Quiz** app, or generate a detailed runbook covering the diagnostic SQL queries for `dba_scheduler_job_run_details` and `v$diag_alert_ext`?", "cites": [], "image": "assets/teknik-gelistirim/chapter-10.jpg", "aofInfographic": null, "nlmInfographic": null}], "quiz": [{"question": "In Oracle Database 19c, which server-side service attribute must be set to enable Transparent Application Continuity (TAC) on a database service?", "answerOptions": [{"text": "FAILOVER_TYPE = AUTO", "isCorrect": true, "rationale": "Setting FAILOVER_TYPE to AUTO enables the database server and driver infrastructure to transparently track session state and inject implicit request boundaries."}, {"text": "FAILOVER_TYPE = TRANSACTION", "isCorrect": false, "rationale": "FAILOVER_TYPE set to TRANSACTION configures manual Application Continuity, which requires explicit request boundary declarations."}, {"text": "FAILOVER_RESTORE = LEVEL1", "isCorrect": false, "rationale": "FAILOVER_RESTORE set to LEVEL1 restores preset initial session states, but does not activate the state-tracking infrastructure of TAC on its own."}, {"text": "COMMIT_OUTCOME = TRUE", "isCorrect": false, "rationale": "COMMIT_OUTCOME set to TRUE enables Transaction Guard for outcome verification, which is a prerequisite for Application Continuity but does not enable TAC."}], "hint": "Consider the parameter value that instructs the driver to automatically track state without requiring application code changes.", "type": "multiple_choice"}, {"question": "How does the Oracle JDBC Thin driver handle Application Continuity replay when a connection obtained from an XA-capable data source participates in a global/XA transaction?", "answerOptions": [{"text": "Replay is disabled on that connection until the next request begins.", "isCorrect": true, "rationale": "Engaging in any global or XA transaction operation disables replay protection on that connection for safety until the connection starts its next request boundary."}, {"text": "The global transaction is transparently converted to a local transaction during failover.", "isCorrect": false, "rationale": "XA transactions involve multi-resource coordination and cannot be converted into local single-resource transactions by the replay driver."}, {"text": "Application Continuity replays the transaction standardly across all involved XA resources.", "isCorrect": false, "rationale": "Application Continuity support for XA data sources only extends to local transactions executed on those connections, not active global transactions."}, {"text": "An exception is thrown immediately when calling getXAResource() on the connection.", "isCorrect": false, "rationale": "Standard XA operations function normally without throwing immediate exceptions, but replay capability is disabled for the duration of the request."}], "hint": "Recall how multi-resource global transaction state affects safety guarantees during failover replay.", "type": "multiple_choice"}, {"question": "In IFS Cloud 26R2, which Server Alert Log Category ID creates a system-level AFTER ERROR database trigger upon activation to log database failures?", "answerOptions": [{"text": "Server Errors", "isCorrect": true, "rationale": "Activating the Server Errors category automatically creates an AFTER ERROR trigger in the database to intercept and log all runtime ORA-errors."}, {"text": "Ddl Audit", "isCorrect": false, "rationale": "Ddl Audit traps schema alteration commands such as CREATE, ALTER, or DROP rather than generic runtime database errors."}, {"text": "Event errors", "isCorrect": false, "rationale": "Event errors intercepts exceptions encountered during the evaluation or execution of IFS Custom Events and Event Actions."}, {"text": "Debug", "isCorrect": false, "rationale": "Debug provides persistent tracing facilities for application developers using explicit internal PL/SQL framework calls."}], "hint": "Look for the category designed specifically to capture transient database ORA-errors raised across application sessions.", "type": "multiple_choice"}, {"question": "According to Oracle Maximum Availability Architecture (MAA) reference standards, which tier combines High Availability Clustering, Disaster Recovery, and Backup for mission-critical applications?", "answerOptions": [{"text": "Gold Tier", "isCorrect": true, "rationale": "The Gold MAA tier incorporates high availability clustering with database replication for disaster recovery to protect mission-critical business systems."}, {"text": "Silver Tier", "isCorrect": false, "rationale": "The Silver tier focuses on high availability clustering and backups for production systems, but lacks a remote disaster recovery site."}, {"text": "Bronze Tier", "isCorrect": false, "rationale": "The Bronze tier represents single-instance database configurations backed up regularly for non-critical or development workloads."}, {"text": "Platinum Tier", "isCorrect": false, "rationale": "The Platinum tier targets zero downtime and zero data loss architectures for extreme mission-critical applications beyond standard DR patterns."}], "hint": "Think of the standard MAA progression step between local HA clustering and extreme zero-downtime solutions.", "type": "multiple_choice"}, {"question": "What is the primary operational distinction between an Oracle Release Update (RU) and a Release Update Revision (RUR)?", "answerOptions": [{"text": "RUs contain quarterly cumulative functional and security fixes that increment the minor release, whereas RURs extend an existing RU with security and regression fixes only.", "isCorrect": true, "rationale": "RUs deliver broad proactive bug fixes and minor release increases, while RURs lock core execution behavior while providing strictly critical security and regression updates."}, {"text": "RUs are delivered monthly for production environments, while RURs are released quarterly for non-production environments.", "isCorrect": false, "rationale": "Both RUs and RURs are delivered on a quarterly cadence by Oracle."}, {"text": "RUs increment the revision digit (e.g., 19.11.0 to 19.11.1), while RURs increment the minor release version (e.g., 19.3.0 to 19.4.0).", "isCorrect": false, "rationale": "Applying an RU increments the minor release version digit, whereas applying an RUR increments the revision digit."}, {"text": "RURs introduce brand-new application features, whereas RUs strictly contain security patches.", "isCorrect": false, "rationale": "RUs contain proactive functional enhancements and security fixes, whereas RURs contain no new functional features."}], "hint": "Identify which patch maintenance strategy targets stability-focused systems by limiting functional scope changes.", "type": "multiple_choice"}, {"question": "Which Oracle database background process is responsible for flushing in-memory statistics from the SGA into Automatic Workload Repository (AWR) tables in SYSAUX?", "answerOptions": [{"text": "MMON", "isCorrect": true, "rationale": "The Memory Monitor (MMON) background process handles the periodic flushing of active session history and SGA performance statistics to the AWR repository."}, {"text": "ONS", "isCorrect": false, "rationale": "ONS (Oracle Notification Service) is a communications infrastructure used for Fast Application Notification events, not database performance sampling."}, {"text": "PMON", "isCorrect": false, "rationale": "PMON cleans up failed user process resources and manages background process recovery."}, {"text": "CKPT", "isCorrect": false, "rationale": "CKPT updates data file headers and signals the database writer during checkpoints, but does not flush performance telemetry to AWR."}], "hint": "Identify the background process focused on memory statistics collection and repository maintenance.", "type": "multiple_choice"}, {"question": "When configuring a database service for Application Continuity, what value is assigned to FAILOVER_RESTORE when FAILOVER_TYPE is set to AUTO?", "answerOptions": [{"text": "AUTO", "isCorrect": true, "rationale": "Setting FAILOVER_TYPE to AUTO automatically sets FAILOVER_RESTORE to AUTO, enforcing session initial state restoration."}, {"text": "LEVEL1", "isCorrect": false, "rationale": "LEVEL1 is used for manual Application Continuity configurations where FAILOVER_TYPE is set to TRANSACTION."}, {"text": "NONE", "isCorrect": false, "rationale": "NONE is the default value when FAILOVER_RESTORE is unconfigured, but it is overridden when FAILOVER_TYPE is set to AUTO."}, {"text": "MANUAL", "isCorrect": false, "rationale": "MANUAL is not a valid attribute setting for the FAILOVER_RESTORE service parameter."}], "hint": "The value of this restore attribute automatically inherits the setting mode specified for the failover type.", "type": "multiple_choice"}, {"question": "To retain mutable function results (such as SYSDATE or SYS_GUID) during Application Continuity replay, what SQL privilege must a DBA grant to the application database user?", "answerOptions": [{"text": "KEEP privilege (e.g., KEEP DATE TIME, KEEP SYSGUID)", "isCorrect": true, "rationale": "DBAs grant KEEP privileges to ensure Application Continuity can save and restore mutable function results for code executed by custom or app users."}, {"text": "EXECUTE privilege on DBMS_REPLAY", "isCorrect": false, "rationale": "DBMS_REPLAY is part of Database Replay for database workload testing, not the Application Continuity driver runtime state retention."}, {"text": "ALTER SESSION system privilege", "isCorrect": false, "rationale": "ALTER SESSION permits session-level parameter adjustments, but does not grant authority to retain mutable function values during replay."}, {"text": "FLASHBACK ANY TABLE privilege", "isCorrect": false, "rationale": "FLASHBACK privileges allow querying historical table data, but do not control mutable function outcome retention in JDBC replay."}], "hint": "Think of the grant syntax keyword specifically intended to preserve or keep function return values consistent.", "type": "multiple_choice"}, {"question": "To enforce a strict Recovery Point Objective of zero ($RPO = 0$) in an Oracle Data Guard architecture, which redo transport mode must be enabled on the primary database?", "answerOptions": [{"text": "Synchronous (SYNC) transport mode", "isCorrect": true, "rationale": "Synchronous transport ensures transaction commits on the primary are held until the redo data is written to standby redo logs on the remote site, preventing data loss."}, {"text": "Asynchronous (ASYNC) transport mode", "isCorrect": false, "rationale": "Asynchronous transport allows the primary database to commit transactions without waiting for standby acknowledgment, leaving a potential data loss window."}, {"text": "Maximum Performance mode", "isCorrect": false, "rationale": "Maximum Performance protection mode utilizes asynchronous redo transport, which prioritizes primary performance over zero data loss."}, {"text": "Fast-Start Failover delay mode", "isCorrect": false, "rationale": "Fast-Start Failover affects automated recovery time (RTO), but does not define the underlying redo log transport synchronization mode."}], "hint": "Consider how transaction commits must wait for network acknowledgment from standby redo logs.", "type": "multiple_choice"}, {"question": "Which explicit APIs are provided by the oracle.jdbc.OracleConnection interface to allow Java applications to declare request boundaries for memory purging and replay safety?", "answerOptions": [{"text": "beginRequest() and endRequest()", "isCorrect": true, "rationale": "The beginRequest and endRequest methods explicitly mark units of work, enabling the JDBC Replay Driver to purge call history and manage memory efficiently."}, {"text": "startTransaction() and commitTransaction()", "isCorrect": false, "rationale": "These are non-existent or standard transaction demarcations, not the explicit Application Continuity request boundary APIs."}, {"text": "enableReplay() and disableReplay()", "isCorrect": false, "rationale": "Dynamic replay control APIs are located on replay connection proxies, but do not define explicit request boundary markers."}, {"text": "checkOutConnection() and checkInConnection()", "isCorrect": false, "rationale": "Connection checkout and checkin are connection pool lifecycle operations rather than methods on the OracleConnection interface."}], "hint": "Look for methods named directly after opening and closing a request boundary.", "type": "multiple_choice"}, {"question": "Starting with Oracle Database Release 12.1.0.2, which set of parameters is explicitly recommended in the JDBC thin driver connection URL to improve connection acquisition during failover and planned outages?", "answerOptions": [{"text": "RETRY_COUNT, RETRY_DELAY, CONNECT_TIMEOUT, and TRANSPORT_CONNECT_TIMEOUT", "isCorrect": true, "rationale": "These parameters optimize network connection acquisition timing across SCAN listeners and database host VIPs during runtime and failover events."}, {"text": "AUTOCOMMIT, STATEMENT_CACHE_SIZE, MAX_POOL_SIZE, and INACTIVE_TIMEOUT", "isCorrect": false, "rationale": "These settings govern connection pool memory and transaction autocommit behavior rather than network failover transport retries."}, {"text": "INSTANCE_NAME, SID, SERVER_TYPE, and SERVICE_NAME", "isCorrect": false, "rationale": "Connecting by SID or INSTANCE_NAME is deprecated for high availability and does not direct connections to known good instances during failover."}, {"text": "FAILOVER_MODE, TYPE=SELECT, METHOD=BASIC, and RETRIES=10", "isCorrect": false, "rationale": "This syntax represents legacy TAF (Transparent Application Failover) configuration parameters rather than modern JDBC Thin Net Services parameters."}], "hint": "Focus on parameters controlling client-side socket connection timeouts and retry attempts.", "type": "multiple_choice"}, {"question": "According to the IFS Cloud 25R1 technical documentation for Oracle 19c Enterprise Edition options, what is the official support status of Oracle Database Vault?", "answerOptions": [{"text": "Not tested/verified for IFS Cloud", "isCorrect": true, "rationale": "The official IFS Cloud 25R1 matrix specifically marks Oracle Database Vault as 'Not tested/verified for IFS Cloud' (N)."}, {"text": "Fully supported and verified on IFS Applications 10 and IFS Cloud", "isCorrect": false, "rationale": "Active Data Guard, Advanced Security, and In-Memory are listed as verified, but Database Vault is explicitly marked as untested."}, {"text": "Supported only with Standard Edition 2", "isCorrect": false, "rationale": "Standard Edition 2 does not include enterprise options like Database Vault, nor is it listed as supported for Database Vault in IFS matrices."}, {"text": "Mandatory for all production installations", "isCorrect": false, "rationale": "Database Vault is an optional security component and is not mandated or verified in standard IFS deployment matrices."}], "hint": "Check the verification table status for Database Vault in contrast to Active Data Guard or Advanced Security.", "type": "multiple_choice"}], "pair": "teknik-gelistirim-tr", "audio": {"1": {"src": "audio/teknik-gelistirim/chapter-1.mp3", "dur": 330, "bytes": 2639561}, "2": {"src": "audio/teknik-gelistirim/chapter-2.mp3", "dur": 333, "bytes": 2667785}, "3": {"src": "audio/teknik-gelistirim/chapter-3.mp3", "dur": 380, "bytes": 3036617}, "4": {"src": "audio/teknik-gelistirim/chapter-4.mp3", "dur": 376, "bytes": 3010889}, "5": {"src": "audio/teknik-gelistirim/chapter-5.mp3", "dur": 330, "bytes": 2641289}, "6": {"src": "audio/teknik-gelistirim/chapter-6.mp3", "dur": 289, "bytes": 2309513}, "7": {"src": "audio/teknik-gelistirim/chapter-7.mp3", "dur": 318, "bytes": 2543945}, "8": {"src": "audio/teknik-gelistirim/chapter-8.mp3", "dur": 348, "bytes": 2785097}, "9": {"src": "audio/teknik-gelistirim/chapter-9.mp3", "dur": 315, "bytes": 2522441}, "10": {"src": "audio/teknik-gelistirim/chapter-10.mp3", "dur": 349, "bytes": 2795465}}}, {"slug": "teknik-gelistirim-tr", "subject": "Teknik Gelişim (Türkçe)", "course": "IFS Cloud ve Oracle DBA Eğitim Programı", "professor": "", "school": "IFS Cloud & Oracle DBA Eğitim Programı", "playlist": "", "note": "Kurumsal Oracle veritabanı ve IFS Cloud işletim eğitimi (Türkçe): yüksek erişilebilirlik (RAC, Data Guard, MAA), uygulama sürekliliği (Application Continuity / TAC), performans yönetimi (AWR, ASH, ADDM) ve geri yükleme uygulamaları.", "kind": "sources", "notebook": "https://notebooklm.google.com/notebook/d9fbd16b-86fb-45ab-af81-dc503b2c5aad", "sourceCount": 94, "language": "tr", "chapters": [{"title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "summary": "IFS Cloud ve IFS Applications platformlarının Oracle 19c veritabanı altyapı mimarisi, kurumsal mimari standartları ve eğitim programının temel bileşenleri öğrenilir. Mimari tasarım prensipleri, veritabanı kurulum hazırlıkları ve temel bellek ile süreç parametrelerinin genel yapısı incelenir. Ayrıca platform gereksinimleri ve lisanslama standartları ele alınır.", "objectives": ["IFS Cloud 25R1 ve 26R2 mimarisi için Oracle 19c veritabanı depolama tier ve sunucu gereksinimlerini planlayabilir.", "IFS Applications 10 ve IFS Cloud platformlarında veritabanı parametrelerinin temel ölçeklendirme standartlarını yapılandırabilir.", "enterprise ERP yükleri için veritabanı altyapı mimarisi kurulum ve oryantasyon adımlarını yönetebilir."], "lectures": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": "", "type": "markdown"}, {"title": "IFS Oracle DBA Training Setup", "url": "", "type": "gemini_chat"}, {"title": "Memory Architecture Tuning (sga_target & pga_aggregate_target)", "url": "", "type": "gemini_chat"}, {"title": "Chapter 1 Core Topics Overview", "url": "", "type": "gemini_chat"}, {"title": "Session & Cursor Capacity Parameter Tuning (open_cursors & processes)", "url": "", "type": "gemini_chat"}, {"title": "Oracle Database Database Concepts, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/cncpt/", "type": "web_page"}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": "", "type": "pdf"}], "notes": "Belirtilen öğrenme hedefleri doğrultusunda, sağlanan kaynaklara dayanarak öğrenilenler aşağıda açıklanmaktadır:\n\n### Hedef 1: IFS Cloud 25R1 ve 26R2 Mimarisi İçin Oracle 19c Veritabanı Depolama Tier ve Sunucu Gereksinimlerini Planlama\n\n* **Kaynak Kapsamı:** Seçilen kaynaklar içerisinde IFS Cloud 25R1 ve IFS Cloud 26R2 sürümlerine özel Oracle 19c veritabanı depolama tier (storage tier) ve sunucu kapasite gereksinimlerine dair somut teknik veriler bulunmamaktadır.\n* **Genel ERP Altyapı Bağlamı:** Kaynaklar, IFS Applications (IFS Cloud, IFS Applications 10/9) platformlarının kritik ERP, EAM ve FSM operasyonlarında Oracle Database arka uçlarına dayandığını belirtmektedir. Kaynaklar belirli bir sürüm (IFS Cloud 25R1 veya 26R2) için depolama tier ve sunucu boyutlandırma ayrıntılarını vermediğinden, kaynaklarda yer almayan hususlar kapsama dahil edilmemiştir.\n\n---\n\n### Hedef 2: IFS Applications 10 ve IFS Cloud Platformlarında Veritabanı Parametrelerinin Temel Ölçeklendirme Standartlarını Yapılandırma\n\n* **System Global Area (SGA) Akortlama (`sga_target`):** `sga_target` parametresinin sıfır olmayan bir değere ayarlanması Otomatik Paylaşılan Bellek Yönetimini (ASMM) etkinleştirir. ASMM sayesinde Oracle; Buffer Cache (diskten okunan veri bloklarını önbelleğe alarak sorgu yanıt sürelerini optimize eder), Shared Pool (IFS orta katman oturumlarının yeniden kullanımı için ayrıştırılmış SQL, PL/SQL kodlarını, yürütme planlarını ve veri sözlüğü bilgilerini saklar), Large Pool ve Java Pool (paralel yürütme, RMAN yedekleme süreçleri ve gömülü JVM operasyonlarını destekler) bellek havuzlarının boyutlarını dinamik olarak dengeler. SGA bellek havuzlarının dinamik akortlanması, IFS Applications (IFS Cloud ve IFS Applications 10/9) bünyesindeki yüksek hacimli OLTP işlemlerinde sabit ayrıştırma (hard parse) ve disk I/O darboğazlarını önler.\n* **Program Global Area (PGA) Akortlama (`pga_aggregate_target`):** PGA, her bir sunucu süreci için bireysel olarak ayrılan paylaşılmayan bellek alanıdır. Sıralama işlemleri (ORDER BY), hash join ve bitmap birleştirme iş alanları için kullanılır. `pga_aggregate_target` parametresi, tüm oturumlar genelinde tahsis edilen toplam PGA belleği için küresel bir hedef belirler. Oracle, iş alanlarına ayrılan belleği dinamik olarak kontrol ederek büyük toplu iş raporlarında geçici tablespace (temp tablespace) alanına aşırı veri taşmasını engeller.\n* **Süreç Kapasite Parametresi Akortlama (`processes`):** Statik başlangıç parametresi `processes`, veritabanı örneğine aynı anda bağlanabilecek maksimum işletim sistemi kullanıcı süreci sayısını tanımlar. Her adanmış orta katman bağlantı havuzu, arka plan süreçleri (PMON, DBWn, LGWR) ve veritabanı yöneticisi (DBA) oturumu bir süreç yuvası tüketir. Bu parametrenin çok düşük yapılandırılması gelen bağlantıların reddedilmesine ve `ORA-00020: maximum number of processes exceeded` hatasına yol açarak orta katman sunucularının yeni oturum açmasını engeller.\n* **Açık İmleç Kapasite Parametresi Akortlama (`open_cursors`):** Dinamik parametre `open_cursors`, Özel SQL Alanında (Private SQL Area) tek bir oturumun aynı anda açık tutabileceği maksimum imleç sayısını belirler. İmleçler ayrıştırılmış SQL ifadelerini ve PL/SQL bloklarını işler. IFS ortamındaki Java/JDBC bağlantı havuzları gibi orta katman çatıları yürütme hızını artırmak için ifade tanıtıcılarını önbelleğe alır. `open_cursors` parametresinin yeterince yüksek ayarlanması, imleç sızıntılarını ve Shared Pool bellek sınırlarının aşılmasını önleyerek `ORA-01000: maximum open cursors exceeded` hatasını engeller.\n* **Sürüm Uygulaması:** Mimari notlar ve çalışma notları bu bellek ve kapasite parametre ölçeklendirme standartlarını IFS Applications (IFS Cloud ve IFS Applications 10/9) iş yüklerine uygular. Kaynaklar bu parametre tanımları için belirli bir veritabanı sürümü kısıtlaması (örneğin Oracle Database 19c) belirtmemektedir.\n\n---\n\n### Hedef 3: Enterprise ERP Yükleri İçin Veritabanı Altyapı Mimarisi Kurulum ve Oryantasyon Adımlarını Yönetme\n\n* **Çok Kiracılı Mimari (CDB ve PDB) Yönetimi:** Kök konteyner veritabanı (CDB$ROOT); arka plan süreçlerini, paylaşılan sistem metadatasını ve küresel belleği yönetir. Ayrı IFS uygulama örneklerini (DEV, TEST ve PROD gibi ortamlar) aynı sunucu donanımı üzerinde izole etmek için adanmış Pluggable Database'ler (PDB$SEED, Kullanıcı PDB'leri) oluşturulur ve yönetilir. PDB durumları, konteyner bağlamları ve şema izolasyonu yönetilerek veritabanı seviyesinde ayrıştırma sağlanır.\n* **Yama Yönetimi ve Bakım Döngüleri (RU / RUR):** Release Update (RU); güvenlik açıklarını, yüksek değerli hata düzeltmelerini ve kararlılık iyileştirmelerini içeren ve ikincil veritabanı sürüm numarasını artıran üç aylık birikimli yamalardır. Release Update Revision (RUR); yeni işlevsel hata düzeltmesi eklemeden mevcut bir RU'nun ömrünü uzatan, güvenlik ve regresyon odaklı yamalardır. Oracle yama uygulama stratejileri IFS Cloud ve IFS Applications güncelleme döngüleriyle hizalanır.\n* **Temel Veritabanı Parametre Yapılandırması:** Yüksek işlem hacimli ERP yükleri için `sga_target`, `pga_aggregate_target`, `open_cursors` ve `processes` parametreleri yapılandırılarak altyapı performansı optimize edilir.\n* **Eğitim Kurulumu ve Oryantasyon Süreci:** IFS Oracle DBA Eğitim Programı oryantasyonunda, kullanıcı hedefleri (örneğin Oracle RAC kurulumu, AWR/ASH performans akortlaması veya Data Guard yüksek erişilebilirlik çözümleri) belirlenir ve mimari kılavuzlar doğrultusunda eğitim içeriği yapılandırılır.\n\n---\n\n💡 **Sonraki Adımlar:** `open_cursors` ve `processes` parametrelerinin dinamik izleme sorgularını incelemek veya SGA bellek havuzlarının anlık dağılımını `V$SGA_DYNAMIC_COMPONENTS` görünümünden sorgulayan örnek SQL kodlarını gözden geçirmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-1.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "summary": "Oracle Database 19c Multitenant mimarisinde CDB$ROOT, PDB$SEED ve kullanıcı Pluggable Database (PDB) yapılarının yönetimi öğrenilir. Farklı IFS ortamları (PROD, TEST, DEV) arasında veritabanı seviyesinde izolasyon sağlama, PDB kaynak yöneticisi profillerini yapılandırma ve PDB yaşam döngüsü operasyonları kapsanmaktadır. PDB klonlama, takma/çıkarma ve PDB seviyesinde SGA/PGA kaynak sınırlandırmaları detaylandırılır.", "objectives": ["Oracle Database 19c Multitenant mimarisinde CDB$ROOT ve PDB yapılarını yöneterek ortamlar arası veri ve metadata izolasyonunu sağlayabilir.", "PDB seviyesinde sga_target ve pga_aggregate_limit parametreleri ile kaynak kotalarını belirleyip kaynak çakışmalarını önleyebilir.", "PDB klonlama, takma, çıkarma ve PDB$SEED üzerinden yeni PDB oluşturma operasyonlarını diğer veritabanlarını etkilemeden gerçekleştirebilir."], "lectures": [{"title": "Container Database (CDB) Administration", "url": "", "type": "gemini_chat"}, {"title": "Pluggable Database (PDB) Isolation & Operations", "url": "", "type": "gemini_chat"}, {"title": "Table Partitioning for Massive Transaction Tables", "url": "", "type": "gemini_chat"}, {"title": "Oracle Database Database Administrator's Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/admin/", "type": "web_page"}], "notes": "Belirtilen hedefler doğrultusunda öğrenilen konular, sağlanan kaynaklara dayanarak aşağıda açıklanmaktadır:\n\n### Hedef 1: CDB$ROOT ve PDB Yapılarını Yöneterek Ortamlar Arası Veri ve Metadata İzolasyonunu Sağlama\n\n* **Çok Kiracılı Mimari Yapısı:** Oracle Multitenant mimarisinin veritabanı altyapısını tek bir kök konteyner veritabanı (CDB$ROOT) ve bir veya daha fazla Pluggable Database (PDB) yapısına ayırdığını öğrenir.\n * **CDB$ROOT:** Ortak arka plan süreçlerini, paylaşılan sistem metadatasını, ortak kullanıcı hesaplarını ve küresel veritabanı belleğini yönetir.\n * **PDB$SEED:** Yeni pluggable veritabanlarını hızlı bir şekilde oluşturmak amacıyla kullanılan, sistem tarafından sağlanan şablon PDB'dir.\n * **Kullanıcı PDB'leri:** IFS Applications için gerekli olan kullanıcı veri şemalarını, tablespace yapılarını ve uygulamaya özel metadataları barındırır.\n* **Mantıksal ve Şema İzolasyonu:** IFS Applications (IFS Cloud, IFS Applications 10/9) ortamında Development (DEV), Testing (TEST), Staging ve Production (PROD) gibi farklı uygulama aşamaları aynı fiziksel donanım üzerinde tam operasyonel izolasyonla çalıştırılır.\n * **Özel Veri Sözlüğü:** CDB$ROOT ortak sistem metadatasını yönetirken, her PDB kullanıcı tarafından oluşturulan tablolar, indeksler ve uygulama şemaları için kendi özel veri sözlüğünü (private data dictionary) korur.\n * **İşlemsel Bağlam İzolasyonu:** Orta katman bağlantı havuzları yalnızca kendilerine atanan PDB servisi ile etkileşime girer; böylece üretim dışı (DEV veya TEST) ortam oturumlarının üretim (PROD) şema nesnelerine erişmesi veya bunları değiştirmesi engellenir.\n* **Bağlam Yönetimi ve Doğrulama:** Oturum konteynır bağlamı `ALTER SESSION SET CONTAINER = ifsprod;` ile değiştirilir ve PDB `ALTER PLUGGABLE DATABASE ifsprod OPEN;` komutuyla açılır. Mevcut oturum konteynır bağlamı `sys_context('USERENV', 'CON_NAME')` ve active oturumlar `v$session` sorgusu ile doğrulanır.\n* **Sürüm Durumu:** Kaynaklar bu multitenant mimari prensiplerini IFS Applications (IFS Cloud, IFS Applications 10/9) ortamları için açıklar; ancak bu ifadelerin özel olarak hangi veritabanı sürümüne (örneğin Oracle Database 19c) ait olduğunu ayrıca belirtmemektedir.\n\n---\n\n### Hedef 2: PDB Seviyesinde sga_target ve pga_aggregate_limit Parametreleri ile Kaynak Kotalarını Belirleme\n\n* **Bellek İzolasyonu ve Kaynak Sınırları:** çok kiracılı bir ortamda ağır test komut dosyaları veya toplu işler gibi üretim dışı iş yüklerinin üretim (PROD) performansını düşürmesini ve bellek kaynaklarını tüketmesini önlemek için PDB seviyesinde kaynak sınırlarının uygulandığını öğrenir.\n* **PDB Seviyesinde Bellek Eşikleri:** Bellek kotaları (`sga_min_size`, `sga_target` ve `pga_aggregate_limit`) PDB bazında yapılandırılarak tek bir konteynerdeki kontrolden çıkmış sorguların sunucuda paylaşılan belleği tüketmesi engellenir.\n* **Uygulama Örneği:** Üretim dışı bir PDB bağlamına geçilerek (`ALTER SESSION SET CONTAINER = ifstest;`) bellek sınırları `ALTER SYSTEM SET pga_aggregate_limit = 4G SCOPE = BOTH;` ve `ALTER SYSTEM SET sga_target = 8G SCOPE = BOTH;` komutlarıyla ayarlanır ve `SHOW PARAMETER pga_aggregate_limit;` ile doğrulanır.\n* **PDB Resource Manager Profilleri:** CPU payları, paralel yürütme kuyrukları ve oturum sınırları PDB Resource Manager profilleri aracılığıyla PDB başına tahsis edilir.\n* **Sürüm Durumu:** Kaynaklar PDB seviyesinde bellek parametresi yapılandırmasını tanımlamakta, ancak spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir.\n\n---\n\n### Hedef 3: PDB Klonlama, Takma, Çıkarma ve PDB$SEED Üzerinden Yeni PDB Oluşturma Operasyonları\n\n* **PDB$SEED ile Yeni PDB Oluşturma:** PDB$SEED yapısının ek IFS ortamları için yeni pluggable veritabanlarını hızlı bir şekilde oluşturmak üzere sistem tarafından sağlanan bir şablon olduğunu öğrenir.\n* **Bağımsız Yaşam Döngüsü Operasyonları:** Veritabanı yöneticileri (DBA), aynı konteyner örneğinde çalışan kardeş PDB'lerdeki operasyonları ve yürütülen iş yüklerini kesintiye uğratmadan bireysel bir PDB'yi çıkarabilir (unplug), klonlayabilir (clone) veya silebilir (drop).\n* **Kapsam Notu:** Kaynaklar PDB$SEED şablon kullanımını ve bir PDB'nin diğer kardeş PDB'leri etkilemeden unplug, clone veya drop edilebildiğini belirtmekte; ancak bu operasyonların komut satırı sözdizimi adımlarını ayrıntılandırmayıp kısa tutmaktadır.\n* **Sürüm Durumu:** Kaynaklar yaşam döngüsü operasyonlarının hangi veritabanı sürümüne ait olduğunu açıkça belirtmemektedir.\n\n---\n\n💡 **Sonraki Adımlar:** PDB seviyesinde Resource Manager profillerini test etmek veya `v$pdbs` ve `v$session` görünümlerinden aktif oturum dağılımını sorgulayan örnek DDL/DML komutlarını incelemek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-2.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "summary": "Oracle Database 19c proaktif yama stratejileri ile Release Update (RU) ve Release Update Revision (RUR) yaşam döngüsü öğrenilir. OPatch ve datapatch araçlarını kullanarak ikili dosya ve SQL metadata güncellemelerini iki aşamalı olarak IFS bakım pencerelerine hizalamayı kavrar. Ayrıca AutoUpgrade, DBUA ve Parallel Upgrade Utility araçları ile Oracle 19c veritabanı yükseltme süreçlerini yönetir.", "objectives": ["üç aylık Release Update (RU) ve Release Update Revision (RUR) yama stratejilerini IFS Cloud ve IFS Applications bakım pencereleriyle hizalayabilir.", "OPatch ve datapatch otomasyonunu kullanarak CDB$ROOT ve tüm PDB'lerde iki aşamalı yama uygulama adımlarını çalıştırabilir.", "AutoUpgrade ve DBUA araçları ile Oracle Database 19c sürüm yükseltme planlarını hazırlayıp uygulayabilir."], "lectures": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": "", "type": "gemini_chat"}, {"title": "Patch Application Execution", "url": "", "type": "gemini_chat"}, {"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf", "type": "pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/", "type": "web_page"}, {"title": "Oracle Database Database Upgrade Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/upgrd/", "type": "web_page"}], "notes": "Sağlanan kaynaklara dayanarak, belirtilen öğrenme hedefleri doğrultusunda öğrenilenler aşağıda açıklanmaktadır:\n\n---\n\n### Hedef 1: Üç Aylık Release Update (RU) ve Release Update Revision (RUR) Yama Stratejilerini IFS Cloud ve IFS Applications Bakım Pencereleriyle Hizalama\n\n* **Yama Döngüsü ve IFS Ortamlarıyla Hizalanma:** IFS Applications (IFS Cloud, IFS Applications 10 ve IFS Applications 9) altyapısını destekleyen Oracle veritabanı sistemlerinin güvenliğini ve kararlılığını korumak için Oracle'ın üç aylık (Ocak, Nisan, Temmuz, Ekim) yama bakım döngüsünün IFS Güncelleme ve Sürüm döngüleri ile hizalanması gerektiğini öğrenir.\n* **Release Update (RU) Stratejisi:** Release Update (RU), güvenlik açığı düzeltmelerini, proaktif yüksek değerli hata düzeltmelerini ve kritik kararlılık geliştirmelerini içeren üç aylık birikimli bir yamadır. RU uygulaması veritabanını yeni bir ikincil sürüme taşır (örneğin 19.11 sürümünden 19.12 sürümüne). Performans değişikliklerini ve yürütme planlarını doğrulamak amacıyla ana IFS güncelleme döngüleri sırasında üretim dışı ortamlarda (DEV/TEST) kullanılması önerilir.\n* **Release Update Revision (RUR) Stratejisi:** Release Update Revision (RUR), sonraki RU'lardan yeni işlevsel hata düzeltmeleri eklemeden, belirli bir RU için kritik güvenlik düzeltmeleri ve regresyon düzeltmeleri sunarak mevcut bir RU'nun ömrünü uzatır (her RU için 2 revizyona kadar). RUR uygulaması revizyon rakamını artırır (örneğin 19.11.0 sürümünden 19.11.1 sürümüne). Sıkı değişiklik yönetimi politikaları gerektiren ve temel yürütme davranışını kilitlerken güvenlik güncellemeleri gerektiren üretim (PROD) ortamlarında tercih edilir.\n* **Sürüm Durumu:** Eğitim çalışma notları bu yama stratejilerini IFS Applications (IFS Cloud, IFS Applications 10 ve IFS Applications 9) ortamlarına uygular ve veritabanı sürüm örneği olarak Oracle Database 19c revizyonlarını (19.11, 19.12) sunar.\n\n---\n\n### Hedef 2: OPatch ve datapatch Otomasyonu ile CDB$ROOT ve Tüm PDB'lerde İki Aşamalı Yama Uygulama Adımlarını Çalıştırma\n\n* **Yama Öncesi Doğrulama ve Hazırlık:** Herhangi bir yama kurulumu çalıştırılmadan önce `opatch` yardımcı programı Oracle Patch Readme dosyasında belirtilen minimum sürüme güncellenmelidir. `$ORACLE_HOME` üzerinde çakışma tespiti (conflict detection) yapılarak kısmi yama uygulamaları önlenir ve veritabanı servisleri durdurulmadan önce tüm önkoşullar doğrulanır.\n* **İki Aşamalı Yama Boru Hattı:**\n 1. *İkili Dosya Yamalama (`opatch apply`):* Veritabanı servisleri kapalı durumdayken `$ORACLE_HOME` dizinindeki yürütülebilir ikili dosyaları, kütüphaneleri ve başlık dosyalarını değiştirir.\n 2. *Yama Sonrası SQL Otomasyonu (`datapatch`):* Veritabanı yeniden açıldıktan sonra `CDB$ROOT` ve tüm Pluggable Database (PDB) yapılarında SQL metadatasını, veri sözlüğü nesnelerini ve PL/SQL paketlerini günceller.\n* **Yama Kaydı Doğrulaması:** Veritabanı yöneticileri (DBA), `registry$history` ve `dba_registry_sqlpatch` veri sözlüğü görünümlerini sorgulayarak `CDB$ROOT` ve tüm PDB'lerde uygulanan RU/RUR seviyelerini ve SQL yama kaydını doğrular.\n* **Sürüm Durumu:** Çalışma notları iki aşamalı yama boru hattını CDB ve PDB çok kiracılı mimarisine uygular; kaynaklar bu komutlar için belirli bir veritabanı sürüm kısıtlaması belirtmemektedir.\n\n---\n\n### Hedef 3: AutoUpgrade ve DBUA Araçları ile Oracle Database 19c Sürüm Yükseltme Planlarını Hazırlayıp Uygulama\n\n* **Yükseltme Kılavuzu ve Yöntemleri:** Resmî Oracle belgesi \"Oracle Database Database Upgrade Guide, 19c\", Oracle Database 19c sürümüne geçiş süreçlerini düzenler. Kılavuz; yükseltme hazırlığı, otomatik ve manuel taşıma yöntemleri, sorun giderme, yükseltme sonrası görevler ve olası geri alma (downgrade) adımlarını kapsar.\n* **AutoUpgrade Aracı:** \"Using AutoUpgrade for Oracle Database Upgrades\" (Bölüm 3) altında tanımlanan AutoUpgrade aracı, veritabanı yükseltmelerinin otomasyonunu, ön denetimlerin (pre-checks) çalıştırılmasını ve yükseltme aşamalarının yönetilmesini sağlar.\n* **Database Upgrade Assistant (DBUA):** \"Upgrading with Oracle Database Upgrade Assistant (DBUA)\" (Ek C) altında tanımlanan DBUA aracı, grafiksel arayüz üzerinden veritabanı yükseltme adımlarını yönetir.\n* **Manuel ve Alternatif Yöntemler:** Kılavuz ayrıca Parallel Upgrade Utility ile manuel yükseltme (Bölüm 4) ve Oracle Data Pump ile veri taşıma (Bölüm 9) yöntemlerini de içerir.\n* **Sürüm Durumu:** Resmî kılavuz bu yükseltme planlarını ve araçlarını doğrudan Oracle Database 19c sürümüne özgü olarak belgeler.\n\n---\n\n💡 **Sonraki Adımlar:** `registry$history` ve `dba_registry_sqlpatch` görünümlerini sorgulayan örnek SQL kodlarını incelemek veya AutoUpgrade yapılandırma dosyası parametrelerini gözden geçirmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-3.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "summary": "Oracle Automatic Storage Management (ASM) DATA ve RECO disk grubu mimarisi ile OLTP yükleri için striping ve redundancy modelleri öğrenilir. Veritabanı tablo bölümleme (Range, List, Hash) stratejileri ve yerel indeks yapılandırmaları ile veri büyümesini ve bölüm bakım operasyonlarını yönetmeyi kavrar. Ayrıca OEM ve DBMS_SERVER_ALERT ile tablespace ve ASM alan eşik değerlerini izleme yeteneği kazanır.", "objectives": ["Oracle ASM üzerinde DATA ve RECO disk gruplarını fine-grained ve coarse-grained şeritlendirme modellerine göre yapılandırabilir.", "IFS Cloud veritabanlarında yüksek hacimli işlem tabloları için tablo bölümleme ve yerel indeks stratejilerini uygulayabilir.", "DBMS_SERVER_ALERT ve OEM üzerinden tablespace ve ASM disk grubu için yüzde 85 uyarı ve yüzde 95 kritik alan eşiklerini tanımlayabilir."], "lectures": [{"title": "Disk Group Architecture (DATA & RECO)", "url": "", "type": "gemini_chat"}, {"title": "ASM Striping & Redundancy for OLTP", "url": "", "type": "gemini_chat"}, {"title": "Tablespace & ASM Disk Space Thresholds", "url": "", "type": "gemini_chat"}, {"title": "Oracle Automatic Storage Management Administrator's Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/ostmg/", "type": "web_page"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-010-planning-installation-010-storage-tier-considerations-010-oracle-db-19c-Oracle-19c-Enterprise-Edition-19c-options-and-feat.pdf", "url": "", "type": "pdf"}], "notes": "Seçilen kaynaklara dayanarak, belirtilen öğrenme hedefleri doğrultusunda öğrenilenler aşağıda açıklanmaktadır:\n\n---\n\n### Hedef 1: Oracle ASM Üzerinde DATA ve RECO Disk Gruplarını Fine-Grained ve Coarse-Grained Şeritlendirme Modellerine Göre Yapılandırma\n\n* **Disk Grubu Rolleri ve Depolama Ayrımı:**\n * Oracle Automatic Storage Management (ASM), fiziksel diskleri mantıksal Disk Gruplarına ayırarak veriyi tüm üye diskler üzerinde otomatik olarak dengeler.\n * **DATA Disk Grubu:** Aktif veri dosyalarını, indeks tablespace'lerini, sistem tablespace'lerini (SYSTEM, SYSAUX), geçici dosyaları (temporary files) ve online redo log gruplarını depolayan birincil operasyonel depolama alanıdır. IFS Applications (IFS Cloud, IFS Applications 10/9) orta katman işlemlerini yürütmek için yüksek okuma ve yazma IOPS performansına öncelik verir.\n * **RECO (veya FRA) Disk Grubu:** Arşiv logları, RMAN yedek kümeleri, kontrol dosyası kopyaları, Flashback logları ve online redo logların çoklanan kopyalarını depolayan adanmış kurtarma depolama alanıdır. Kurtarma dosyalarının izole edilmesi, yedekleme veya arşivleme işlemlerinin DATA grubundaki birincil veri operasyonlarıyla disk bant genişliği yarışına girmesini engeller.\n* **ASM Şeritlendirme (Striping) Stratejileri:**\n * **Coarse-Grained Striping (Kaba Taneli Şeritlendirme):** Genellikle 1 MB ila 4 MB veya daha büyük Allocation Unit (AU) boyutunu kullanır. Veritabanı veri dosyaları, indeks tablespace'leri, geçici dosyalar ve RMAN yedek kümeleri gibi büyük ve sıralı I/O operasyonları için tasarlanmıştır.\n * **Fine-Grained Striping (İnce Taneli Şeritlendirme):** Allocation Unit birimlerini tüm diskler üzerine dağıtılan 128 KB boyutundaki daha küçük şerit kümelerine böler. Online Redo Logs (ORLs), Control Files ve Flashback Logs gibi düşük gecikmeli, küçük boyutlu yazma operasyonları için optimize edilmiştir.\n* **ASM Yedeklilik (Redundancy) Modelleri:**\n * **External Redundancy:** ASM seviyesinde aynalama yapmaz; veri korumasını tamamen donanım RAID kontrolcülerine veya SAN mimarisine devreder.\n * **Normal Redundancy:** ASM Failure Groups arasında 2 yönlü (2-way) aynalama uygular ve en az iki Failure Group gerektirir.\n * **High Redundancy:** ASM Failure Groups arasında 3 yönlü (3-way) aynalama uygular ve en az üç Failure Group gerektirir. En yüksek erişilebilirlik gerektiren görev kritik IFS kurulumları için standarttır.\n* **İnceleme ve Yapılandırma Operasyonları:**\n * Veritabanı yöneticileri (DBA), ASM örneğine (`+ASM`) bağlanarak `V$ASM_FILE` ve `V$ASM_ALIAS` görünümlerinden dosyaların fine veya coarse şeritlendirme durumlarını sorgular.\n * Disk grubu şablonları (templates) değiştirilerek yeni oluşturulan online redo log dosyalarının otomatik olarak fine-grained şeritlendirme ve high redundancy alması sağlanabilir.\n * ASM disk grubu kapasitesi, Allocation Unit boyutları ve yedeklilik modelleri `V$ASM_DISKGROUP` veya `v$asm_diskgroup` görünümünden doğrulanır.\n * Oracle Managed Files (OMF) parametreleri yapılandırılarak veri dosyalarının ve kurtarma varlıklarının otomatik olarak ilgili DATA ve RECO disk gruplarına yönlendirilmesi sağlanır.\n* **Sürüm Bağlamı:** Resmî Oracle kılavuzu \"Oracle Automatic Storage Management Administrator's Guide\", bu ASM yönetimi ve disk grubu süreçlerini Release 19c için belgeler. Eğitim programının çalışma notları bu depolama ve şeritlendirme stratejilerini IFS Applications (IFS Cloud, IFS Applications 10/9) iş yüklerine uygular.\n\n---\n\n### Hedef 2: IFS Cloud Veritabanlarında Yüksek Hacimli İşlem Tabloları İçin Tablo Bölümleme ve Yerel İndeks Stratejilerini Uygulama\n\n* **Kaynak Kapsamı ve Destek Durumu:** Resmî IFS Cloud teknik dokümantasyonu (\"screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-010-planning-installation-010-storage-tier-considerations-010-oracle-db-19c-Oracle-19c-Enterprise-Edition-19c-options-and-feat.pdf\"), Oracle Database Options tablosunda Oracle Partitioning seçeneğinin IFS Cloud ile kullanımının desteklendiğini ('Y') belirtmektedir.\n* **Test Edilen Özellikler:** Resmî doküman, tablo bölümleme (table partitioning) ile küresel ve yerel indeks bölümlerinin (global and local index partitions) IFS Applications 9 & 10 üzerinde test edildiğini ve doğrulandığını ifade etmektedir.\n* **Ayrıntı Düzeyi:** Seçilen kaynaklar yüksek hacimli işlem tabloları için tablo bölümleme ve yerel indeks stratejilerinin adım adım uygulanmasına dair daha fazla teknik ayrıntı veya özel komut sözdizimi içermemektedir. Kaynaklar bu noktayı kısa ele aldığı için kaynaklarda yer almayan hususlar kapsama dahil edilmemiştir.\n\n---\n\n### Hedef 3: DBMS_SERVER_ALERT ve OEM Üzerinden Tablespace ve ASM Disk Grubu İçin Yüzde 85 Uyarı ve Yüzde 95 Kritik Alan Eşiklerini Tanımlama\n\n* **OEM Metrik Eşik Mimarisi:** Oracle Enterprise Manager (OEM) Cloud Control, izlenen hedefleri önceden tanımlanmış depolama sınırlarına göre değerlendirerek kullanım yüzdeleri eşikleri aştığında alarmlar üretir.\n * **Uyarı Eşiği (Warning Threshold):** Kapasite kullanımının %85 seviyesine ulaşması durumunda tetiklenir. Veritabanı yöneticilerine büyüyen veri dosyalarını inceleme, eski staging tablolarını temizleme veya rutin bakım pencerelerinde alan genişletme planlama imkanı verir.\n * **Kritik Eşik (Critical Threshold):** Kapasite kullanımının %95 seviyesine ulaşması durumunda tetiklenir. Veritabanı duraklamalarını ve aniden alan tükenmesi nedeniyle oluşacak kesintileri önlemek için acil idari müdahale gerektiğini gösterir.\n* **Tablespace ve ASM Disk Grubu Uyarı Ayrımı:**\n * **Tablespace Eşikleri:** Bireysel veri dosyaları ile CDB/PDB konteyner veritabanları içindeki mantıksal alan tahsisini izler.\n * **ASM Disk Group Eşikleri:** DATA ve RECO gibi paylaşılan depolama havuzlarındaki fiziksel diskler ve Failure Group'lar genelindeki fiziksel boş alanı izler.\n* **DBMS_SERVER_ALERT Paketi İle Programatik Yapılandırma:**\n * `DBMS_SERVER_ALERT.SET_THRESHOLD` yordamı çalıştırılarak `metric_id => DBMS_SERVER_ALERT.TABLESPACE_SPACE_USAGE`, `warning_operator => DBMS_SERVER_ALERT.OPERATOR_GE`, `warning_value => '85'`, `critical_operator => DBMS_SERVER_ALERT.OPERATOR_GE`, `critical_value => '95'`, `observation_period => 1`, `consecutive_occurrences => 1`, `dbobject_type => 'TABLESPACE'` ve `dbobject_name => 'USERS'` parametreleriyle %85 uyarı ve %95 kritik eşikleri tanımlanır.\n * Yapılandırılan eşik ayarları `DBA_THRESHOLDS` veri sözlüğü görünümünden (`SELECT metric_name, object_name, warning_value, critical_value FROM dba_thresholds WHERE metric_name LIKE '%Space Used%';`) sorgulanarak doğrulanır.\n* **ASM Disk Grubu Kullanımının `v$asm_diskgroup` İle İzlenmesi:**\n * Veritabanı yöneticileri ASM örneğine (`+ASM`) bağlanarak `v$asm_diskgroup` görünümünden (`SELECT name, total_mb / 1024 AS total_gb, free_mb / 1024 AS free_gb, ROUND((1 - (free_mb / total_mb)) * 100, 2) AS used_percent FROM v$asm_diskgroup;`) DATA ve RECO disk gruplarının toplam kapasitesini, boş alanını ve yüzde kullanım oranını sorgular.\n* **Sürüm Bağlamı:** Eğitim programının çalışma notları bu alan eşiği uyarılarını IFS Applications (IFS Cloud, IFS Applications 10/9) ortamlarındaki ERP, EAM ve FSM yüklerine uygular. Kaynaklar `DBMS_SERVER_ALERT` paketi ve eşik yapılandırması için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir.\n\n---\n\n💡 **Sonraki Adımlar:** Studio paneline eklenen **IFS Cloud ASM Depolama ve Kapasite Yönetimi** sesli özetini dinlemek veya **Oracle Storage** uygulamasındaki soruları çözerek bilginizi pekiştirmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-4.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "summary": "Oracle Real Application Clusters (RAC) ve Grid Infrastructure bileşenleri ile private Interconnect ve High Availability IP (HAIP) yapılandırması öğrenilir. Cache Fusion veri bloğu transferleri ve Global Resource Directory (GRD) kilit koordinasyon mekanizmalarını yönetmeyi kavrar. Dynamic Database Services, SCAN dinleyicileri ve Fast Application Notification (FAN) ile yük dengeleme ve kesintisiz bağlantı failover yapısını kurar.", "objectives": ["Oracle Grid Infrastructure mimarisinde HAIP ve özel interconnect ağını yapılandırarak Cache Fusion ve GRD koordinasyonunu optimize edebilir.", "Oracle RAC ortamında aktif-aktif düğüm kümeleme ve shared storage erişim mimarisini yönetebilir.", "Dynamic Database Services, SCAN listeners ve FAN altyapısını yapılandırarak otomatik bağlantı yük dengelemesi ve failover sağlayabilir."], "lectures": [{"title": "Active-Active Node Clustering", "url": "", "type": "gemini_chat"}, {"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": "", "type": "gemini_chat"}, {"title": "I/O Bottleneck Identification", "url": "", "type": "gemini_chat"}, {"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf", "type": "pdf"}, {"title": "Oracle Real Application Clusters Real Application Clusters Administration and Deployment Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/", "type": "web_page"}], "notes": "Seçili kaynaklara dayanarak, belirtilen öğrenme hedefleri doğrultusunda öğrenilenler aşağıda açıklanmaktadır:\n\n---\n\n### Hedef 1: Oracle Grid Infrastructure Mimarisinde HAIP ve Özel Interconnect Ağını Yapılandırarak Cache Fusion ve GRD Koordinasyonunu Optimize Etme\n\n* **Grid Infrastructure Yazılım Yığını:** Oracle Grid Infrastructure yazılımının Oracle Clusterware ve Automatic Storage Management (Oracle ASM) teknolojilerini işletim sistemi ile veritabanı örnekleri arasında tek bir yazılım yığınında birleştirdiğini öğrenir.\n * **Cluster Synchronization Services (CSS):** CSS bileşeni küme düğüm üyeliğini takip eder, düğüm yanıt verme durumunu denetler ve iletişim kopukluğu veya düğüm arızası durumunda split-brain senaryolarını önlemek için düğüm tahliyesini (node eviction) gerçekleştirir.\n * **Cluster Ready Services (CRS/CRSD):** CRSD ana süreci; VIP adresleri, SCAN (Single Client Access Name) dinleyicileri, veritabanı örnekleri ve servisler gibi yüksek erişilebilirlik kaynaklarını yönetir, başarısız olan kaynakları otomatik olarak yeniden başlatır veya taşır.\n * **Event Manager (EVM/EVMD):** EVM bileşeni küme olaylarını ve uyarılarını yayınlayarak hızlı failover rutinlerini başlatır.\n* **Özel Interconnect Ağı ve HAIP Yapılandırması:** Düğümler arası ve örnekler arası iletişim için özel bir interconnect ağı kullanılır. Interconnect ağı internal küme iletişimini, heartbeat sinyallerini ve disk I/O operasyonuna gerek duymadan bellekler arası Cache Fusion veri bloğu transferlerini yürütür.\n * **Protokol Bilgisi:** Interconnect ağı üzerinde örnekler arası iletişim için UDP veya Reliable Data Socket (RDS) protokolleri kullanılır; Clusterware ise UDP protokolünü kullanır.\n * **High Availability IP (HAIP):** Oracle Grid Infrastructure 11g Release 2 (11.2) ve sonraki sürümlerde sunulan Redundant Interconnect Usage / HAIP (High Availability IP) veya işletim sistemi seviyesinde ağ kartı birleştirme (NIC bonding), birden fazla fiziksel NIC kullanarak yüksek verim ve ağ kartı arızasında kesintisiz çalışma sağlar.\n * **Doğrulama Görünümleri:** Veritabanı yöneticileri özel interconnect yapılandırmasını `V$CLUSTER_INTERCONNECTS`, `V$CONFIGURED_INTERCONNECTS` veya `GV$CLUSTER_INTERCONNECTS` dinamik performans görünümlerini sorgulayarak doğrular.\n* **Cache Fusion ve Global Resource Directory (GRD) Koordinasyonu:** Cache Fusion, bir veritabanı örneğinin bellek önbelleğinde bulunan veri bloklarının kopyalarını özel interconnect ağı üzerinden talep eden diğer örneğin bellek önbelleğine doğrudan aktaran disksiz bir bellek tutarlılık mekanizmasıdır.\n * **Kaynak Yönetimi:** Global Cache Service (GCS) ve Global Enqueue Service (GES) süreçleri, tampon bellek bloklarını ve kilitleri Global Resource Directory (GRD) içinde koordine eder.\n * **GRD Bellek Tüketimi:** GRD içeriği tüm aktif veritabanı örnekleri arasında dağıtılır ve bellek kullanımı toplam SGA alanının yaklaşık yüzde 10'una denk gelir.\n * **Arka Plan Süreçleri:** Global Cache Service Processes (LMS/LMSn) veri dosyası durumlarını ve önbelleğe alınmış blok bilgilerini GRD kayıtlarına işler, mesaj akışını yönetir ve blok görüntülerini aktarır. Global Enqueue Service Monitor (LMON) küme genelindeki kilitleri ve kaynakları izler, kilit kurtarmayı yönetir. Global Enqueue Service Daemon (LMD) ise gelen uzak kaynak taleplerini yönetir.\n* **Sürüm Uygulaması:** Resmî Oracle belgeleri bu özellikleri Oracle Database 19c ve Oracle Grid Infrastructure 19c sürümleri için detaylandırır. Eğitim mimari notları ise Grid Infrastructure ve interconnect yapılandırmasını IFS Applications (IFS Cloud, IFS Applications 10/9) ortamlarına uygular.\n\n---\n\n### Hedef 2: Oracle RAC Ortamında Aktif-Aktif Düğüm Kümeleme ve Shared Storage Erişim Mimarisini Yönetme\n\n* **Aktif-Aktif Düğüm Kümeleme Mimarisi:** Aktif-aktif düğüm kümelemesi, tek bir veritabanına erişen birden fazla veritabanı örneği (one-to-many ilişkisi) çalıştırarak tekil sunucu darboğazlarını ortadan kaldırır.\n * **Eşzamanlı İşlem:** Aktif-pasif yapıların aksine, aktif-aktif mimarideki tüm düğümler eşzamanlı olarak aktif bağlantıları kabul eder ve IFS Applications (ERP, EAM, FSM) orta katman bağlantı havuzlarından gelen işlemleri yürütür.\n * **Bağımsız Bellek ve Arka Plan Süreçleri:** Kümedeki her bir düğüm kendi System Global Area (SGA) bellek yapılarını ve arka plan süreçlerini çalıştırır.\n * **Veritabanı Nesneleri:** Her veritabanı örneği en az bir ek redo izine (thread of redo) ve örneğe özel bir undo tablespace alanına sahiptir.\n* **Paylaşılan Depolama (Shared Storage) Mimarisi:** Tüm küme örnekleri aynı paylaşılan veritabanı dosyalarını (veri dosyaları, kontrol dosyaları, SPFILE ve online redo log dosyaları) okur ve yazar.\n * **Depolama Seçenekleri:** Paylaşılan depolama küme uyumlu çözümler gerektirir; Oracle Automatic Storage Management (Oracle ASM), Oracle Automatic Storage Management Cluster File System (Oracle ACFS) veya sertifikalı NFS çözümleri desteklenir.\n * **Yedeklilik Modelleri:** Oracle ASM disk grupları veri güvenliğini sağlamak için Normal Redundancy (2 yönlü aynalama), High Redundancy (3 yönlü aynalama) veya External Redundancy (donanım/SAN aynalaması) modellerini sunar.\n* **Küme Yönetimi ve Doğrulama:**\n * **Yönetim Modelleri:** Oracle RAC veritabanları Administrator-managed (örneklerin belirli düğümlere statik atanması) veya Policy-managed (server pool ve kardinalite bazlı) modelleriyle yönetilebilir.\n * **Küme Durumu Doğrulama:** Veritabanı yöneticileri kümedeki aktif veritabanı örneklerinin durumunu ve paylaşılan veritabanı özelliklerini SQL*Plus üzerinden global dinamik performans görünümlerini (`GV$`) sorgulayarak veya SRVCTL ve Enterprise Manager araçlarını kullanarak doğrular.\n* **Sürüm Uygulaması:** Resmî Oracle belgeleri aktif-aktif kümeleme ve paylaşılan depolama yönetimini Oracle Database 19c için tanımlar. Eğitim mimari notları bu aktif-aktif küme mimarisini IFS Applications (IFS Cloud, IFS Applications 10/9) platformlarına uygular.\n\n---\n\n### Hedef 3: Dynamic Database Services, SCAN Listeners ve FAN Altyapısını Yapılandırarak Otomatik Bağlantı Yük Dengelemesi ve Failover Sağlama\n\n* **Dynamic Database Services Yapılandırması:** Uygulamaların veritabanına kamu ağı (public network) üzerinden bağlanması için Dynamic Database Services kullanılması önerilir.\n * **Özel Servis Oluşturma:** Veritabanı kurulumuyla otomatik oluşturulan varsayılan veritabanı servisleri (`DB_NAME`, `DB_UNIQUE_NAME`, `PDB_NAME`) uygulama bağlantıları için kullanılmamalıdır; DBAlar `srvctl` veya Enterprise Manager ile kullanıcı tanımlı dinamik servisler oluşturmalıdır.\n * **Servis Yerleşimi:** Servisler belirli veritabanı örneklerine veya server pool yapılarına adanarak singleton (tek bir örnekte çalışan) veya uniform (tüm aktif örneklerde çalışan) olarak tanımlanabilir.\n* **Single Client Access Name (SCAN) ve Dinleyici Yönlendirmesi:** SCAN, DNS veya Grid Naming Service (GNS) içinde tanımlanan ve kümedeki üç SCAN VIP adresine döngüsel (round-robin) olarak çözümlenen tek bir ağ adıdır.\n * **Bağlantı Yönlendirme Adımları:**\n 1. İstemci SCAN adına (public ağdaki SCAN VIP) bağlanarak servis adını SCAN dinleyicisine iletir.\n 2. SCAN dinleyicisi ilgili servisi barındıran en uygun veritabanı örneğini belirler ve istemciyi o düğümdeki yerel dinleyiciye (local/node listener) yönlendirir.\n 3. Düğüm VIP adresi üzerinde dinleyen yerel dinleyici, istemci bağlantısını yerel veritabanı örneğine bağlar.\n * **HTTP Protokol Desteği:** Oracle Database 12c Release 2 (12.2) ile birlikte SCAN dinleyicileri HTTP protokolünü tanıyarak HTTP istemcilerini küme düğümlerine yönlendirme yeteneğine sahip olmuştur.\n * **Valid Node Checking:** Valid Node Checking for Registration (VNCR) özelliği, yalnızca izin verilen IP adresi veya alt ağların SCAN dinleyicisine dinamik servis kaydı yapmasını sağlar.\n* **Fast Application Notification (FAN) ve ONS Altyapısı:** FAN, Oracle RAC yüksek erişilebilirlik çerçevesinin bir parçası olup veritabanı, düğüm, ağ ve servis durum değişikliklerini (UP ve DOWN olayları) ile Load Balancing Advisory metriklerini gerçek zamanlı yayınlar.\n * **ONS İletim Mekanizması:** Oracle Database 12c Release 2 (12.2) ve sonraki sürümlerde tüm istemciler FAN olaylarını almak için Oracle Notification Service (ONS) kullanır.\n * **Fast Connection Failover (FCF):** Entegre Oracle istemcileri (JDBC Thin, OCI, ODP.NET, Universal Connection Pool, WebLogic Server Active GridLink) ONS üzerinden FAN olaylarına abone olarak Fast Connection Failover (FCF) sağlar; bu sayede istemciler TCP/IP zaman aşımı askıda kalmalarından anında kurtulur ve kesintiye uğrayan ölü bağlantıları derhal temizler.\n* **Yük Dengeleme (Load Balancing) Yöntemleri:**\n * **Client-Side Load Balancing:** İstemci bağlantı tanımında `LOAD_BALANCE=ON` ayarlanarak gelen isteklerin SCAN dinleyicileri arasında rastgele dağıtılması sağlanır.\n * **Server-Side Load Balancing:** SCAN dinleyicileri, servisin `-clbgoal` parametresine (`SHORT` veya `LONG`, Oracle tarafı `LONG` önerir) göre istemciyi en az yüklü veritabanı örneğine yönlendirir.\n * **Runtime Connection Load Balancing:** Bağlantı havuzları, ONS üzerinden yayınlanan Load Balancing Advisory olaylarını (`SERVICEMETRICS`) ve `-rlbgoal` ayarlarını (`SERVICE_TIME` veya `THROUGHPUT`) kullanarak iş taleplerini en iyi servis kalitesini sunan veritabanı örneklerine dinamik olarak yönlendirir.\n * **İstemci Bağlantı Dizesi Parametreleri:** İstemci TNS veya JDBC bağlantı dizelerinde `CONNECT_TIMEOUT`, `RETRY_COUNT`, `RETRY_DELAY`, `TRANSPORT_CONNECT_TIMEOUT` ve `FAILOVER=ON` parametrelerinin tanımlanması önerilir.\n* **Oturum Boşaltma (Session Draining) ve Uygulama Sürekliliği:**\n * **Server-Side Session Draining:** Oracle Database 18c ile birlikte veritabanı seviyesinde sunucu tarafı oturum boşaltma özelliği getirilmiştir. Planlı bakım öncesinde gönderilen FAN planned DOWN olayları, FAN uyumlu bağlantı havuzlarının boşta duran oturumları kapatmasını ve aktif oturumları belirlenen `-drain_timeout` süresi içinde istek sınırlarında (request boundaries) kesintisiz boşaltmasını sağlar.\n * **Transparent Application Continuity (TAC):** Oracle Database 18c ile tanıtılan ve servis üzerinde `FAILOVER_TYPE=AUTO` ayarlanarak etkinleştirilen TAC, oturum ve işlem durumlarını şeffaf bir şekilde izleyerek kesintiler sonrasında oturumların güvenli bir şekilde failover edilmesini ve replaying yapılmasını sağlar.\n* **Sürüm Uygulaması:** Resmî belgeler SCAN dinleyici HTTP desteğini Oracle Database 12c Release 2 (12.2), sunucu tarafı session draining özelliğini Oracle Database 18c, TAC özelliğini Oracle Database 18c ve ONS varsayılan iletimini Oracle Database 12c Release 2 (12.2) olarak belirtir. Eğitim mimari notları EVM ve FAN altyapısını IFS Applications bağlantı havuzları failover rutinlerine uygular.\n\n---\n\n💡 **Sonraki Adımlar:** Küme genelindeki Cache Fusion trafiğini incelemek üzere `GV$CLUSTER_INTERCONNECTS` sorgularını çalıştırmak veya Studio panelinde hazır bulunan **RAC ve Grid Infrastructure** test uygulamasını çözerek bilgilerinizi pekiştirmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-5.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "summary": "Oracle Maximum Availability Architecture (MAA) Silver, Gold ve Platinum referans mimarileri ile Oracle Database@Azure entegrasyonu öğrenilir. Data Guard Broker (dgmgrl) ile otomatik planlı switchover ve acil durum failover runbook'larını çalıştırmayı kavrar. Standby Redo Logs (SRLs) ve Real-Time Redo Apply yapılandırması ile RPO = 0 ve RTO < 5 dakika hedeflerine ulaşmayı sağlar.", "objectives": ["Oracle Database 19c için MAA Silver, Gold ve Platinum mimarilerini değerlendirip felaket kurtarma çözümlerini uygulayabilir.", "Data Guard Broker (dgmgrl) kullanarak Standby Redo Logs ve Real-Time Redo Apply ile planlı switchover ve failover operasyonlarını yönetebilir.", "Active Data Guard fiziksel standby veritabanını salt okunur modda açarak raporlama yüklerini ikincil veritabanına aktarabilir."], "lectures": [{"title": "Automated Switchover & Failover Runbooks", "url": "", "type": "gemini_chat"}, {"title": "Gold & Platinum MAA Standards Implementation", "url": "", "type": "gemini_chat"}, {"title": "RPO & RTO High Availability Optimization", "url": "", "type": "gemini_chat"}, {"title": "Real-Time Replica Synchronization", "url": "", "type": "gemini_chat"}, {"title": "Read-Only Query & Reporting Offloading", "url": "", "type": "gemini_chat"}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": "", "type": "gemini_chat"}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": "", "type": "markdown"}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf", "type": "pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/", "type": "web_page"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html", "type": "web_page"}], "notes": "Seçili kaynaklara dayanarak, belirtilen öğrenme hedefleri doğrultusunda öğrenilenler aşağıda açıklanmaktadır:\n\n---\n\n### Hedef 1: Oracle Database 19c İçin MAA Silver, Gold ve Platinum Mimarilerini Değerlendirme ve Felaket Kurtarma Çözümlerini Uygulama\n\n* **MAA Çerçevesi ve Mimari Katmanlar:**\n * **Bronze Katmanı:** Tek veritabanı örneği, ASM ve Flashback Teknolojisi ile uzaktan depolama yedekleme replikasyonunu birleştirir; Kurtarma Süresi Hedefi (RTO) saatler veya günler düzeyinde olup Kurtarma Noktası Hedefi (RPO) > 0 değerine sahiptir; üretim dışı, geliştirme ve sandbox ortamlarını hedefler.\n * **Silver Katmanı:** Oracle Real Application Clusters (RAC) veya RAC One Node ile yerel yüksek erişilebilirlik ve replike yedek depolama sunar; RTO yerel düğüm arızasında dakikalar mertebesindedir. Oracle Database@Azure ortamında Exadata Database Service on Dedicated Infrastructure (ExaDB-D) üzerinde tek bir Availability Zone (AZ) içinde yerel donanım ve yazılım arızalarına karşı koruma sağlar. Uygulama sanal makineleri (VM) ile veritabanı kümesi arasındaki gecikme aynı AZ içinde 300 mikrosaniye, AZ'ler arasında 500 mikrosaniyedir. Autonomous Recovery Service (ARS) entegrasyonu ile \"incremental forever\" (artımlı sonsuz) yedekleme politikası sunarak saatte 42 TB yedekleme ve 8.7 TB geri yükleme hızı sağlar.\n * **Gold Katmanı:** Oracle RAC aktif-aktif kümelemesini uzak alanda Oracle Data Guard veya Active Data Guard (ADG) fiziksel replikasyonu ile birleştirir. Yerel HA ve Fast-Start Failover (FSFO) sayesinde RTO < 1 dakika (veya < 5 dakika) ve sıfır veri kaybı (RPO = 0) sağlar. Görev kritik çekirdek ERP, EAM ve FSM sistemleri (IFS Applications, Oracle E-Business Suite, SAP) için zorunlu mimaridir.\n * **Platinum Katmanı:** Gold katmanı altyapısına Oracle GoldenGate aktif-aktif replikasyonu, Application Continuity ve Edition-Based Redefinition (EBR) teknolojilerini ekler. Kesintisiz 24/7/365 operasyonlar için sıfır bakım penceresi etkisi ve çevrimiçi uygulama şeması yükseltmeleri sunar.\n* **Kaynak Hiyerarşisi ve Çakışma Yönetimi:** Resmî kılavuz olan \"Oracle Maximum Availability Architecture for Oracle Database@Azure\" belgesi, MAA Platinum Seçenek 1 mimarisi için Oracle AI Database 26ai veya üzerini ve Oracle Active Data Guard şart koşmaktadır. Eğitim programının mimari notu olan \"Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads\" ise Platinum katman standartlarını Oracle Database 19c bağlamında ele almaktadır. Kaynak sıralama kuralı gereğince resmî Oracle dokümantasyonunun beyanı esas alınmış ve MAA Platinum Seçenek 1 mimarisinin Oracle AI Database 26ai veya daha yüksek bir sürüm gerektirdiği belirtilmiştir.\n* **Azure Üzerinde Bulut ve Bölgeler Arası Ağ Peering:**\n * Oracle Database@Azure üzerinde birincil ve standby Exadata sanal makine kümeleri ayrı Virtual Cloud Network (VCN) yapılarına dağıtılır.\n * Redo taşıma bant genişliğini artırmak ve taşıma gecikmesini düşürmek için OCI VCN Peering (Local Peering Gateway / Dynamic Routing Gateway ile) kullanılması önerilir; alternatif olarak Azure VNet Peering de kullanılabilir ancak tekil süreç redo aktarım hızı OCI Peering ile daha yüksektir. TDE şifreleme anahtarları OCI Private Vault içinde tutulur ve bölgeler arasında replike edilir.\n* **Sürüm Uygulaması:** Mimariler Oracle Database 19c için \"Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads\" notunda açıklanmış, Platinum Seçenek 1 için ise \"Oracle Maximum Availability Architecture for Oracle Database@Azure\" belgesinde Oracle 26ai vurgulanmıştır. Çalışma notları bu katmanları IFS Applications (IFS Cloud, IFS Applications 10/9) ortamlarına uygulamaktadır.\n\n---\n\n### Hedef 2: Data Guard Broker (dgmgrl) Kullanarak Standby Redo Logs ve Real-Time Redo Apply ile Planlı Switchover ve Failover Operasyonlarını Yönetme\n\n* **Standby Redo Logs (SRLs) Yapılandırma İlkeleri:**\n * Standby Redo Log (SRL) dosyaları hem birincil hem de standby veritabanlarında oluşturulmalıdır; böylece rol değişimlerinde her iki taraf da veri alabilir.\n * SRL dosya boyutları, birincil veritabanının Online Redo Log (ORL) dosyalarıyla birebir aynı boyutta olmalıdır.\n * Her bir redo kanalı (thread) için gerekli minimum SRL grup sayısı formülü: `Minimum SRL Grubu Sayısı = (Thread Başına ORL Grubu Sayısı) + 1` olarak hesaplanır.\n* **Veri Taşıma ve Real-Time Redo Apply Süreçleri:**\n * Birincil veritabanındaki Log Network Server (LNS) süreci redo verisini ağ üzerinden iletir; standby tarafındaki Remote File Server (RFS) süreci bu akışı alarak doğrudan aktif SRL dosyalarına yazar.\n * Recovery Writer (MRP0) süreci, gelen redo verilerini SRL dosyalarından bellek ve diske anında uygulayarak geleneksel arşiv log biriktirme gecikmesini ortadan kaldırır ve Real-Time Redo Apply sağlar.\n * Maksimum Kullanılabilirlik (Maximum Availability) koruma modunda varsayılan olarak senkron redo taşıması (SYNC AFFIRM) kullanılır; ağ kopması durumunda sistem asenkron (ASYNC) moda düşer ve ağ düzeldiğinde tekrar senkron moda döner.\n* **Data Guard Broker (`dgmgrl`) Yönetimi ve ORA-16698 Çözümü:**\n * Data Guard Broker (`dgmgrl`) aracı; yapılandırma oluşturmayı, sağlık denetimlerini ve rol geçişlerini otomatikleştirmeyi sağlar.\n * Broker başlatılırken karşılaşılan ORA-16698 hatası (manuel `LOG_ARCHIVE_DEST_n` parametresinde `SERVICE` özniteliğinin bulunması durumu), manuel arşiv hedeflerinin temizlenmesi (`ALTER SYSTEM SET LOG_ARCHIVE_DEST_2='' SCOPE=BOTH SID='*';`) ve Broker'ın etkinleştirilmesi (`ALTER SYSTEM SET DG_BROKER_START=TRUE SCOPE=BOTH SID='*';`) ile çözülür.\n* **Rol Değişim Playbook'ları (Switchover ve Failover):**\n * **Planlı Switchover:** Birincil ve standby veritabanları arasında iki yönlü, sıfır veri kayıpsız (RPO = 0) rol değişimidir. İşlem öncesinde tüm pending redo verileri standby tarafına aktarılır ve uygulanır. Veritabanlarının yeniden oluşturulmasına gerek yoktur.\n * **Acil Durum Failover:** Birincil veritabanının çökmesi durumunda standby veritabanını birincil role yükselten tek yönlü acil durum işlemidir.\n * **Fast-Start Failover (FSFO):** Üçüncü bir konumda çalışan bağımsız Observer süreci aracılığıyla failover sürecini otomatikleştiren yapıdır. Observer birincil veritabanına ulaşamadığında ve gecikme eşiği (`FastStartFailoverThreshold`, saniye cinsinden) dolduğunda otomatik failover başlatır. FSFO kullanımı için Flashback Database özelliğinin aktif olması kesinlikle zorunludur.\n* **Sürüm Uygulaması:** \"Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads\" notu bu komutları ve dgmgrl adımlarını Oracle Database 19c için detaylandırır. Çalışma notları ise bu adımları IFS Applications (IFS Cloud, IFS Applications 10/9) ortamlarında SCAN listeners ve Fast Connection Failover (FCF) entegrasyonu ile açıklar.\n\n---\n\n### Hedef 3: Active Data Guard Fiziksel Standby Veritabanını Salt Okunur Modda Açarak Raporlama Yüklerini İkincil Veritabanına Aktarma\n\n* **Active Data Guard Salt Okunur (Read-Only) Mimarisi:**\n * Active Data Guard, fiziksel standby veritabanının arka planda Managed Recovery Process (MRP0) ile gelen redo verilerini uygulamaya devam ederken (Real-Time Apply) aynı anda salt okunur erişim (`READ ONLY`) modunda açılmasına imkan tanır.\n* **Raporlama Yüklerini Devretme (Query Offloading):**\n * Ağır OLAP analitik sorguları, geniş finansal raporlar ve harici BI entegrasyonları birincil veritabanındaki CPU ve I/O kaynaklarını tüketmesin diye ikincil standby veritabanına yönlendirilir.\n * Böylece birincil veritabanındaki çekirdek OLTP işlemlerinin yanıt süreleri ve işlem hacmi korunur.\n* **Fiziksel Standby Veritabanını Salt Okunur Modda Yapılandırma Adımları:**\n 1. *Mevcut Yönetilen Kurtarmayı İptal Etme:* `ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL;`\n 2. *Standby Veritabanını Salt Okunur Modda Açma:* `ALTER DATABASE OPEN;`\n 3. *Real-Time Apply İle Yönetilen Kurtarmayı Başlatma:* `ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT;`\n* **Durum Doğrulama ve Teşhis Sorguları:**\n * `v$database` görünümünden `database_role` sütununun `PHYSICAL STANDBY` ve `open_mode` sütununun `READ ONLY` olduğu doğrulanır.\n * `v$managed_standby` görünümünden `MRP0` sürecinin durumunun `APPLYING_LOG` olduğu kontrol edilir.\n * `v$dataguard_stats` görünümünden `apply lag` (uygulama gecikmesi) metriğinin sıfıra yakın olduğu doğrulanır.\n* **Bağlantı Yönlendirmesi:**\n * İstemci bağlantı dizeleri ve özel veritabanı servisleri (Oracle Services) kullanılarak IFS raporlama işleri ve zamanlanmış görevler doğrudan ikincil standby veritabanına yönlendirilir.\n* **Sürüm Uygulaması:** Mimari notlar bu yapıyı Oracle 19c Gold MAA mimarisi bünyesinde sunmaktadır. Çalışma notları ise read-only offloading adımlarını ve SQL sözdizimini IFS Applications (IFS Cloud, IFS Applications 10/9) iş yüklerine uygulamaktadır. Kaynaklar genel SQL komutları için spesifik bir sürüm kısıtlaması belirtmemektedir.\n\n---\n\n💡 **Sonraki Adımlar:** Data Guard Broker `dgmgrl` komut setiyle Fast-Start Failover (FSFO) test senaryolarını çalıştırmak veya Studio panelinde mevcut olan **Oracle Data Guard Zero Loss Failover** sesli özeti ile **Oracle Quiz** uygulamasını incelemek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-6.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "summary": "Oracle Application Continuity (AC) ve Transparent Application Continuity (TAC) servis parametrelerinin srvctl ile yapılandırılması öğrenilir. Transaction Guard ve Logical Transaction ID (LTXID) mekanizmaları ile kesinti anında işlemlerin tekrarlanmasını ve kesintisiz oturum failover'ını kavrar. IFS orta katman bağlantı yeniden kurma mantığını ve Fast Connection Failover (FCF) entegrasyonunu test eder.", "objectives": ["srvctl ile Oracle Database 19c üzerinde TAC ve AC servis parametrelerini (-failovertype AUTO, -commit_outcome TRUE) yapılandırabilir.", "Application Continuity ve Transaction Guard ile kesintiler sırasında in-flight işlemlerin şeffaf bir şekilde yeniden çalıştırılmasını sağlayabilir.", "IFS orta katman bağlantı mantığını ONS ve SCAN üzerinden test ederek kesintisiz oturum aktarımı ve oturum boşaltma süreçlerini doğrulayabilir."], "lectures": [{"title": "IFS Mid-Tier Re-connection Logic Testing", "url": "", "type": "gemini_chat"}, {"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html", "type": "web_page"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf", "type": "pdf"}], "notes": "**srvctl ile Oracle Database 19c Üzerinde TAC ve AC Servis Parametrelerini Yapılandırma**\n\n* Oracle RAC ortamlarında Transparent Application Continuity (TAC) ve manuel Application Continuity (AC) destekleyen kullanıcı tanımlı veritabanı servisleri `srvctl` komut satırı aracı ile oluşturulur ve değiştirilir. Single-instance veritabanlarında ise servisler `DBMS_SERVICE` paketi kullanılarak yapılandırılır.\n* Servis oluşturulurken `-failovertype AUTO` parametresinin ayarlanması, Oracle Database 18c sürümünde tanıtılan ve Oracle Database 19c sürümünde desteklenen Transparent Application Continuity (TAC) modunu etkinleştirir. TAC, oturum durumunu ve işlem bağlamını şeffaf bir şekilde izleyerek uygulama kodunda değişiklik yapılmasına gerek kalmadan kesinti sonrası oturumların kurtarılmasını sağlar.\n* Servis üzerinde `-failovertype TRANSACTION` parametresinin ayarlanması, Oracle Database 12c Release 1 (12.1) sürümünde sunulan manuel Application Continuity (AC) modunu yapılandırır. Manuel AC, uygulama taraflı istek sınırlarının (`beginRequest` ve `endRequest`) tanımlanmasını gerektirir.\n* Servis parametresi `-commit_outcome TRUE` olarak ayarlandığında Transaction Guard etkinleştirilir. Transaction Guard, her işleme benzersiz bir Mantıksal İşlem Kimliği (LTXID) atayarak kesinti sonrasında işlemin taahhüt durumunu sorgular ve mükerrer işlem çalıştırılmasını önler.\n* Servis parametresi `-failover_restore AUTO` olarak ayarlandığında, TAC modunda oturum yeniden kurulurken yaygın NLS ayarları, zaman dilimleri, paket değişkenleri ve varsayılan oturum durumları otomatik olarak geri yüklenir. Oracle Database 19c sürümünde `-failovertype AUTO` tanımlandığında `-failover_restore` değeri otomatik olarak `AUTO` yapılır. Manuel AC modunda ise `-failover_restore LEVEL1` ayarlanarak önceden belirlenmiş temel oturum durumları geri yüklenir.\n* Oracle Database 19c sürümünde `FAILOVER_TYPE` parametresi `AUTO` yapıldığında, Oracle JDBC sürücüsü yeniden çalışma veri kaynağı üzerinden oluşturulan her yeni fiziksel bağlantıda implicit olarak bir istek başlatır (`beginRequest`), böylece üçüncü taraf bağlantı havuzları kod değişikliği yapmadan TAC kullanabilir.\n* Veritabanı yöneticileri `srvctl` komutu ile `-clbgoal SHORT` (veya `LONG`), `-rlbgoal SERVICE_TIME`, `-failoverretry 30` (veya `1`), `-failoverdelay 10` (veya `3`), `-replay_init_time 1800` (veya `600`), `-retention 86400`, `-notification TRUE`, `-drain_timeout 300` ve `-stopoption IMMEDIATE` parametrelerini tanımlar.\n* **Sürüm Bağlamı:** TAC ve `-failovertype AUTO` kullanımı Oracle Database 18c sürümünde getirilmiş ve Oracle Database 19c sürümünde desteklenmiştir. Manuel AC modundaki `-failovertype TRANSACTION` kullanımı Oracle Database 12c Release 1 (12.1) sürümüne aittir. Kaynaklar genel `srvctl` parametre sözdizimlerinin diğer sürümler için olan kısıtlamalarını ayrıca belirtmemektedir.\n\n---\n\n**Application Continuity ve Transaction Guard ile In-Flight İşlemlerin Şeffaf Şekilde Yeniden Çalıştırılması**\n\n* Application Continuity (AC), planlı bakım veya beklenmeyen veritabanı kesintileri sonrasında oturum durumunu ve işlem bağlamını yeniden inşa ederek taahhüt edilmemiş veya tamamlanmamış in-flight veritabanı isteklerini yeni veritabanı örneği üzerinde güvenli bir şekilde yeniden çalıştırır.\n* Application Continuity özelliğinin çalışması için Transaction Guard kullanımı zorunludur. Transaction Guard, kesinti sırasında işlemin veritabanında taahhüt edilip edilmediğini doğrulamak için LTXID yapısını kullanır ve mükerrer işlem yürütülmesini engeller.\n* Transparent Application Continuity (TAC), uygulama çağrılarını izleyerek durum kullanımını kategorize eder ve açık imleç veya açık işlem bulunmayan emniyetli noktalarda örtük istek sınırları (implicit request boundaries) tespit ederek işlemleri kod değişikliği gerektirmeden kurtarır.\n* Manuel Application Continuity (AC) modunda ise bağlantı havuzları veya uygulama kodları `oracle.jdbc.OracleConnection` arabirimindeki `beginRequest` ve `endRequest` API'lerini kullanarak istek sınırlarını açıkça bildirir; bu sınırlar bellek tüketimini azaltır ve kaydedilen çağrı geçmişini temizler.\n* Yeniden çalıştırma koruma seviyeleri ve metrikleri veritabanı içinde `V$SESSTAT`, `V$SYSSTAT` ve Oracle Database 19c sürümünün sonraki versiyonlarında `V$SERVICE_STATS` görünümleri üzerinden izlenebilir. Ayrıca `ReplayableConnection.getReplayStatistics()` API'si ile toplam istek, korunan çağrı ve başarılı replay sayıları elde edilebilir.\n* E-posta gönderimi (`UTL_SMTP`), HTTP çağrıları (`UTL_HTTP`) veya harici dosya aktarımı gibi tekrarlanmaması gereken harici yan etkileri (side effects) bulunan isteklerde, `ReplayableConnection` üzerindeki `disableReplay()` API'si çağrılarak ilgili istek için replay devre dışı bırakılır. TAC modunda ise sistem çalışma zamanında yan etkileri otomatik olarak tespit eder ve bu istekler için replay yakalamasını geçici olarak durdurur.\n* **Sürüm Bağlamı:** TAC ve örtük istek tespiti Oracle Database 18c sürümünde tanıtılmış ve Oracle Database 19c sürümünde desteklenmiştir. Manuel AC ise Oracle Database 12c Release 1 (12.1) sürümünden itibaren mevcuttur. `V$SERVICE_STATS` üzerinden koruma istatistiklerinin takibi Oracle Database 19c sürümünün sonraki versiyonlarına aittir.\n\n---\n\n**IFS Orta Katman Bağlantı Mantığını ONS ve SCAN Üzerinden Test Etme ve Oturum Boşaltma Süreçlerini Doğrulama**\n\n* Enterprise ortamlarda çalışan IFS Applications (IFS Cloud, IFS Applications 10/9) sistemleri, veritabanı kesintilerini ve Active Data Guard rol değişimlerini algılamak için Fast Connection Failover (FCF) ve Oracle Notification Service (ONS) altyapısını kullanır.\n* ONS, küme durum değişikliklerini (FAN olayları) varsayılan 6200 portu üzerinden yayınlayarak JDBC Universal Connection Pool (UCP) veya WebLogic Server bağlantı havuzlarını anında bilgilendirir. FCF mekanizması, kopan veya çöken veritabanı bağlantılarını geçersiz kılar ve bağlantı havuzunun TCP/IP zaman aşımı askıda kalmalarına düşmeden yeni bağlantılar açmasını sağlar.\n* SCAN dinleyicileri (Single Client Access Name), ilk bağlantı isteklerini aktif RAC düğümlerine yönlendirir ve küme genelinde yük dengelemesi sağlar.\n* İstemci JDBC bağlantı dizesinde `CONNECT_TIMEOUT`, `RETRY_COUNT`, `RETRY_DELAY`, `TRANSPORT_CONNECT_TIMEOUT`, `FAILOVER=ON` ve SCAN VIP adreslerini içeren `ADDRESS_LIST` tanımlarının yapılması gereklidir. UCP veri kaynaklarında ONS bildirimlerini almak için `fastConnectionFailoverEnabled=true` ayarlanır ve `onsConfiguration` veya auto-ONS yapılandırılır.\n* Planlı bakım sırasında, FAN planned-down olayları yayınlandığında FAN uyumlu bağlantı havuzları boşta duran oturumları kapatır ve aktif oturumların yürütülen iş tamamlandığında kesintisiz şekilde kapanmasını sağlar. İşlemler belirlenen `drain_timeout` (örneğin 300 saniye) süresi içinde tamamlanamazsa `stopoption` (`IMMEDIATE`) devreye girer. Oracle Database 18c sürümünden itibaren veritabanının kendisi de güvenli boşaltma noktalarını tespit ederek oturumları otomatik boşaltır.\n* **IFS Orta Katman Failover Test Adımları:**\n 1. IFS orta katman veri kaynağı bağlantı URL'si SCAN dinleyici sözdizimiyle yapılandırılır ve `PoolDataSourceFactory` üzerindeki `setONSConfiguration` mülkü ile ONS düğümleri tanımlanır.\n 2. Data Guard Broker arayüzünden `SWITCHOVER TO <standby_database>;` komutu çalıştırılarak birincil veritabanı rolü standby veritabanına devredilir.\n 3. IFS uygulama sunucusu günlük dosyaları (log files) incelenerek ONS FCF olaylarının alındığı, geçersiz bağlantıların havuzdan temizlendiği ve SQL sorgularının yeni birincil veritabanı örneği üzerinde kesintisiz çalışmaya devam ettiği doğrulanır.\n* **Sürüm Bağlamı:** Sunucu tarafı oturum boşaltma (server-side draining) Oracle Database 18c sürümünde getirilmiştir. Bağlantı dizesindeki `TRANSPORT_CONNECT_TIMEOUT` parametresi Oracle Database Release 12.1.0.2 sürümünden itibaren geçerlidir. İstemcide auto-ONS yapılandırması Oracle Database 12c ve sonrası istemci sürümlerinde desteklenmektedir.\n\n---\n\n💡 **Sonraki Adımlar:** Universal Connection Pool (UCP) verilerini incelemek üzere Studio panelinde hazır bulunan **Application Continuity and Resilience** bilgi grafiğini veya **Application Continuity Quiz** uygulamasını denemek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-7.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "summary": "SGA bellek havuzlarının (sga_target, pga_aggregate_target) ve oturum kapasite parametrelerinin (open_cursors, processes) optimize edilmesi öğrenilir. AWR raporları, ADDM önerileri ve ASH saniyelik örnekleme verilerini analiz ederek I/O darboğazlarını, satır seviyesi kilitlenmeleri ve bellek latch çekişmelerini tespit eder. Execution plan profilleme ve indeks stratejileri ile SQL sorgularını iyileştirir.", "objectives": ["sga_target, pga_aggregate_target, open_cursors ve processes parametrelerini ayarlayarak ORA-01000 ve ORA-00020 hatalarını önleyabilir.", "AWR raporları, ADDM önerileri ve ASH metriklerini değerlendirerek I/O darboğazlarını ve kilitlenme çekişmelerini izole edebilir.", "execution plan analizi ve wait event teşhisleri (C.3) ile IFS veritabanı SQL performansını optimize edebilir."], "lectures": [{"title": "Execution Plan Profiling & Index Strategies", "url": "", "type": "gemini_chat"}, {"title": "ADDM Report Analysis & Proactive Recommendations", "url": "", "type": "gemini_chat"}, {"title": "Peak Hours & Batch Run AWR Generation", "url": "", "type": "gemini_chat"}, {"title": "OEM Agent Administration across Nodes", "url": "", "type": "gemini_chat"}, {"title": "AWR Performance Metrics Interpretation", "url": "", "type": "gemini_chat"}, {"title": "Locking & Latch Contention Drill-Downs", "url": "", "type": "gemini_chat"}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html", "type": "web_page"}, {"title": "Database Performance Tuning Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/tgdba/", "type": "web_page"}, {"title": "Oracle Database Database Reference, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/refrn/", "type": "web_page"}], "notes": "### Hedef 1: Bellek ve Kapasite Parametreleri Yapılandırması (`sga_target`, `pga_aggregate_target`, `open_cursors`, `processes`)\n\n* **ADDM Teşhis Önerileri:** Otomatik Veritabanı Teşhis Monitörü (ADDM), AWR yakalamalarını otomatik inceleyerek veritabanı yapılandırmasını iyileştirmeye yönelik önceliklendirilmiş öneriler sunar.\n* **Bellek ve Bağlantı Parametreleri:** ADDM, veritabanı bellek havuzlarının (`sga_target`, `pga_aggregate_target`) ve bağlantı parametrelerinin (`open_cursors`, `processes`) ayarlanmasını yapılandırma seviyesinde aksiyon alınabilir çözümler olarak sunar.\n* **Kaynak Kapsamı Notu:** Seçilen kaynaklar bu parametrelerin ayarlanmasını ADDM önerileri kapsamında işlemekte, ancak ORA-01000 veya ORA-00020 hata kodlarına ve bu parametrelerin spesifik veritabanı sürüm kısıtlamalarına dair ayrıntıları bu pasajlarda açıkça belirtmemektedir.\n\n---\n\n### Hedef 2: AWR Raporları, ADDM Önerileri ve ASH Metrikleri İle Performans Teşhisi\n\n* **Otomatik Veritabanı Teşhis Monitörü (ADDM):** ADDM, her AWR yakalamasının ardından (varsayılan olarak her 60 dakikada bir) son iki snapshot arasındaki performans farkını toplam veritabanı süresi (DB Time) odaklı analiz eder. Üst düzey CPU ve bekleme süresi dağılımlarından başlayarak SQL ifadelerine, veritabanı nesnelerine ve donanım kaynaklarına kadar ağaç yapısında yukarıdan aşağıya darboğaz analizi yürütür ve verimli çalışan bileşenleri eleyerek doğrudan yüksek etkili sorunlara odaklanır. ADDM bulguları `DBA_ADDM_FINDINGS` ve `DBA_ADDM_TASKS` görünümlerinden sorgulanabilir veya `addmrpt.sql` betiği ile raporlanabilir.\n* **Otomatik İş Yükü Deposu (AWR) Analizi:** AWR, veritabanı istatistiklerini varsayılan olarak 60 dakikalık snapshot aralıklarıyla yakalar ve `SYSAUX` tablespace alanındaki depoda tutar. AWR raporları, aktif kullanıcı oturumlarının harcadığı toplam süreyi gösteren DB Time değerini geçen süre (Elapsed Time) ile kıyaslar; DB Time değerinin Elapsed Time değerini belirgin şekilde aşması sistemde yüksek eşzamanlılık veya kaynak çekişmesi olduğunu gösterir. Yük Profili (Load Profile) bölümü saniyelik ve işlem başına mantıksal okuma, fiziksel okuma, blok değişimi, redo boyutu ve sabit ayrıştırma (hard parse) metriklerini sunar. AWR Raporları `awrrpt.sql` ile, yama öncesi ve sonrası gibi iki farklı dönemin kıyası ise AWR Compare Period raporları (`awrddrpt.sql` veya RAC için `awrddrpi.sql`) ile üretilir.\n* **Aktif Oturum Geçmişi (ASH) Örneklemesi:** ASH, SGA halka tamponunda (`v$active_session_history`) her saniye aktif oturumları örnekleyerek AWR snapshot saatlik ortalamalarının gizlediği kısa süreli performans sıçramalarını yakalar. Disk üzerine aktarılan geçmiş ASH verileri `dba_hist_active_sess_history` görünümünden sorgulanır.\n* **I/O Darboğazlarının İzolasyonu:** Fiziksel I/O baskısı yaratan durumlar ASH sorgularıyla tespit edilir:\n * `db file sequential read` (tek blok indeks okumaları) yüksek bekleme sayıları gösterdiğinde unindexed sorgulara veya parçalanmış B-Tree indekslerine işaret eder.\n * `db file scattered read` (çoklu blok tam tablo taramaları) toplu iş süreçlerindeki Full Table Scan operasyonlarını gösterir.\n * `direct path read` ve `direct path write` doğrudan disk I/O işlemlerini temsil eder.\n * `v$active_session_history` görünümü `dba_users` ve `dba_objects` ile birleştirilerek disk çekişmesine neden olan SQL ID (`sql_id`), kullanıcı adı, program ve veritabanı nesnesi (tablo veya indeks) doğrudan izole edilir.\n* **Kilitlenme ve Latch Çekişmelerinin İzolasyonu:**\n * Satır seviyesinde kilitlenme çekişmeleri `enq: TX - row lock contention` bekleme olayı ile tespit edilir; IFS ortamlarında müşteri siparişleri, stok bakiyeleri veya muhasebe kayıtlarının eşzamanlı güncellenmesi sırasında taahhüt edilmemiş işlemlerden kaynaklanır.\n * Bellek latch çekişmelerinde `Cache Buffers Chains` latch çekişmesi sık erişilen sıcak bloklardan (hot blocks) kaynaklanır. Shared Pool ve Library Cache latch/mutex çekişmeleri (örneğin `cursor: mutex S`, `cursor: mutex X`, `cursor: pin S`, `cursor: pin S wait on X`, `cursor: pin X`, `library cache: mutex X`) yüksek miktarda sabit ayrıştırma ve paylaşılmayan SQL ifadelerinden tetiklenir.\n* **Sürüm Uygulaması:** AWR, ADDM ve ASH analiz yöntemleri temel veritabanı ayarları olarak açıklanmakta, AWR Compare Period raporlarında yama güncellemeleri (Release Update / Release Update Revision) değerlendirilmektedir.\n\n---\n\n### Hedef 3: Execution Plan Analizi ve Wait Event Teşhisleri (C.3) İle SQL Performans Optimizasyonu\n\n* **Resmî Wait Event Kataloğu (C.3):** Resmî Oracle kılavuzu \"Database Reference 18\" bünyesindeki \"C.3 Descriptions of Wait Events\" bölümü, oturumların hangi operasyonel nedenlerle durakladığını açıklayan veri sözlüğü kataloğudur. Bu katalogda `buffer busy waits`, `cursor: mutex S`, `cursor: mutex X`, `cursor: pin S`, `cursor: pin S wait on X`, `cursor: pin X`, `db file scattered read`, `db file sequential read`, `direct path read`, `direct path write`, `enq: TX - row lock contention`, `latch free`, `library cache: mutex X` ve `log file sync` gibi bekleme olaylarının çalışma mekanizmaları ve parametreleri tanımlanmaktadır.\n* **Maliyet Tabanlı Eniyileyici (CBO) ve Yürütme Planları:** CBO; tablo istatistikleri, indeksler ve sorgu koşullarına dayanarak veri erişim yollarını belirler. Tablo erişim yöntemlerinde `TABLE ACCESS FULL` (yüksek su seviyesine kadar tüm blokların taranması), `Index Unique Scan`, `Index Range Scan` ve `Index Fast Full Scan` değerlendirilir. Birleştirme yöntemlerinde ise `Nested Loops`, `Hash Join` ve `Sort Merge Join` kullanılır.\n* **Çalışma Zamanı Yürütme Planı Profilleme:** Bellekte aktif çalışan bir SQL cümlesinin gerçek yürütme planı `v$sql_plan` ve `dbms_xplan.display_cursor(sql_id => '&target_sql_id', cursor_child_number => NULL, format => 'ALLSTATS LAST')` çağrısıyla çekilir. Yürütme planındaki Tahmini Satır Sayısı (`E-Rows`) ile Gerçekleşen Satır Sayısı (`A-Rows`) arasındaki büyük farklar bayat veya eksik tablo istatistiklerine işaret eder.\n* **ASH ve Yürütme Planı Korelasyonu İle İyileştirme:**\n 1. ASH taranarak en yüksek I/O veya CPU süresi tüketen SQL ID ve bekleme sınıfı tespit edilir.\n 2. ASH üzerinde `db file scattered read` bekleniyorsa yürütme planında büyük ERP tablolarındaki `TABLE ACCESS FULL` adımları incelenir.\n 3. Hatalı maliyet hesaplamalarında tablo istatistikleri `DBMS_STATS.GATHER_TABLE_STATS(ownname => 'IFSAPP', tabname => 'CUSTOMER_ORDER_TAB', cascade => TRUE)` komutuyla güncellenir.\n 4. Tam tablo taramalarını önlemek için B-Tree veya kompozit indeksler tasarlanır ve ilerideki çalıştırmalarda performans kararlılığı sağlamak için SQL Plan Baselines mekanizması uygulanır.\n* **Sürüm Uygulaması:** Bekleme olayları açıklamaları resmî doküman \"Database Reference 18\" (Sürüm 18) kataloğuna aittir. Performans akortlama temelleri \"Database Performance Tuning Guide 19c\" kılavuzunda sunulmaktadır. Optimizasyon adımları ve `IFSAPP` şema örnekleri çalışma notlarında IFS ortamlarına uygulanmaktadır.\n\n---\n\n💡 **Sonraki Adımlar:** Studio paneline eklenen **Database Performance Management and Tuning** bilgi grafiğini incelemek veya **Oracle Performance Quiz** uygulamasını çözerek AWR, ADDM ve ASH analiz yeteneklerinizi test etmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-8.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "summary": "Oracle Enterprise Manager (OEM) Cloud Control 13c/14c altyapı bileşenlerinin (OMS, OMR/SYSMAN, OMA) emctl CLI ile yönetimi öğrenilir. OEM olay yönetimi, incident rule set mantığı, karartma (blackout) takvimleri ve bildirim yöntemlerini yapılandırır. Ayrıca IFS Cloud 25R1 ve 26R2 ortamlarında Application Monitoring Console (AMM), Server Alert Log kategorileri, Oracle Advanced Queues ve EFK stack panellerini kullanır.", "objectives": ["OEM Cloud Control 13c/14c altyapı bileşenlerini ve emctl komut satırı aracını yönetebilir.", "OEM olay yönetimi ve incident rule set mantığı ile yanlış alarmları bastırıp kritik metrikleri olaylara dönüştürebilir.", "IFS Cloud 25R1 ve 26R2 ortamlarında AMM metrikleri, Server Alert Log kategorileri, Advanced Queues ve EFK stack panelleri ile izleme yapabilir."], "lectures": [{"title": "OEM 13c/14c Infrastructure Setup", "url": "", "type": "gemini_chat"}, {"title": "Automated Incident Rule sets & Notifications", "url": "", "type": "gemini_chat"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": "", "type": "pdf"}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": "", "type": "markdown"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": "", "type": "pdf"}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": "", "type": "pdf"}], "notes": "Seçilen kaynaklara dayanarak, kurumsal Oracle veritabanı yöneticileri ve IFS Cloud operasyon mühendisleri için belirtilen her bir öğrenme hedefi doğrultusunda öğrenilenler aşağıda açıklanmaktadır.\n\n---\n\n### Hedef 1: OEM Cloud Control 13c/14c Altyapı Bileşenlerini ve `emctl` Komut Satırı Aracını Yönetme\n\n* **Çok Katmanlı OEM Altyapı Mimarisi:** Oracle Enterprise Manager (OEM) Cloud Control mimarisinin veritabanı küme bileşenlerini, ASM depolama katmanını ve sunucu donanımlarını izleyen çok katmanlı bir yapıda tasarlandığını öğrenir.\n* **Oracle Management Service (OMS):** Oracle WebLogic Server üzerinde çalışan OMS orta katman Java EE uygulaması, host agent süreçlerinden gelen verileri işler, web tabanlı Cloud Control yönetim konsolunu sunar, yönetim işlerini yönlendirir ve bildirim alarmlarını yönetir.\n* **Oracle Management Repository (OMR):** `SYSMAN` şemasını barındıran adanmış Oracle veritabanı olan OMR, yapılandırma verilerini, hedef sağlık metriklerini, geçmiş performans verilerini, iş yürütme günlüklerini ve olay takip verilerini saklar.\n* **Oracle Management Agent (OMA):** Yönetilen her hedef sunucuda doğrudan çalışan hafif OMA süreci, hedef metriklerini toplar, OMS tarafından dağıtılan görevleri yürütür ve durum güncellemelerini TCP 3872 portu üzerinden OMS ortamına yükler.\n* **Management Plug-in Bileşenleri:** Özel donanım dizileri, üçüncü taraf veritabanları veya uygulama orta katmanları için izleme yeteneklerini genişleten yazılım eklentileridir.\n* **`emctl` Komut Satırı İle Yönetim:** Veritabanı yöneticileri, OMS sunucusu üzerinde `emctl` komut satırı aracını çalıştırarak WebLogic servislerinin, HTTP sunucusunun ve repository bağlantısının çalışma durumunu doğrular.\n* **Yönetilen Düğümlerde `emctl` Kullanımı:** Yönetilen hedef düğümlerde (örneğin bir Oracle RAC düğümünde) `emctl` komut satırı aracı ile OMA süreç sağlığı ve OMS ile agent arasındaki iletişim durumu denetlenir.\n* **Sürüm Bağlamı:** Eğitim çalışma notlarında bu altyapı kurulumu \"OEM 13c/14c Infrastructure Setup\" başlığı altında sunulmuştur. Kaynaklar bu altyapı bileşenlerinin çalışma prensipleri ve `emctl` komutları için 13c ile 14c sürümleri arasında spesifik bir işlevsel fark belirtmemektedir.\n\n---\n\n### Hedef 2: OEM Olay Yönetimi ve Incident Rule Set Mantığı İle Yanlış Alarmları Bastırıp Kritik Metrikleri Olaylara Dönüştürme\n\n* **Event ve Incident Yaşam Döngüsü:** Oracle Management Agent (OMA) hedef metriklerini sürekli örnekler; bir metrik uyarı veya kritik eşiği geçtiğinde (örneğin sunucu CPU kullanımı %95 seviyesini aştığında) sistem bir Event üretir.\n* **Events to Incidents Promotion:** Üretilen event, ciddiyet seviyesine ve önceden tanımlanmış olay kurallarına dayanarak idari müdahale gerektiren bir Incident seviyesine otomatik yükseltilir.\n* **Incident Rule Set Mantığı:** Rule set yapıları, event ve incident süreçlerinin temel işleyiş mantığını belirler; hedef kriterlerine, ciddiyet seviyelerine ve zaman aralıklarına göre otomatik e-posta bildirimleri gönderme, düzeltici eylem betikleri çalıştırma veya dış biletleme sistemlerinde (ServiceNow, Jira) otomatik bilet açma adımlarını yönetir.\n* **Bildirim İletim Yöntemleri:** Bildirim iletim kanalları olarak SMTP (E-posta), SNMP tuzakları ve işletim sistemi betikleri veya webhook yöntemleri kullanılır.\n* **Blackout Takvimleri İle Bastırma:** Planlı bakım pencerelerinde idari Blackout takvimleri tanımlanarak bildirimler geçici olarak bastırılır ve IFS staging veya üretim ortamlarında yanlış alarmların (false-positive) oluşması engellenir.\n* **Repository Olay Kaydı Doğrulaması:** Veritabanı yöneticileri OMR repository yönetim görünümü `sysman.em_incidents` sorgusunu çalıştırarak kritik alarmların (örneğin %95'i aşan tablespace kullanımı, %95'i aşan CPU kullanımı veya 900 saniyeyi aşan Data Guard uygulama gecikmesi) başarıyla kaydedildiğini ve takip edildiğini doğrular.\n* **Sürüm Bağlamı:** Çalışma notları bu olay yönetimi mantığını IFS Applications (IFS Cloud, IFS Applications 10/9) ortamlarına uygular. Kaynaklar olay yönetimi kuralları, blackout takvimleri ve `sysman.em_incidents` görünüm sorgulaması için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir.\n\n---\n\n### Hedef 3: IFS Cloud 25R1 ve 26R2 Ortamlarında AMM Metrikleri, Server Alert Log Kategorileri, Advanced Queues ve EFK Stack Panelleri İle İzleme Yapma\n\n* **IFS Cloud 25R1 EFK Stack Log İzleme Panelleri:** IFS Cloud 25R1 Remote Deploy mimarisinde günlük izleme işlemleri Elasticsearch, Fluentd ve Kibana bileşenlerinden oluşan bir EFK stack üzerinden yürütülür. Elasticsearch günlük verilerini 7 günlük saklama süresiyle tutar ve günlük çalışan curator cronjob 7 günden eski günlükleri otomatik siler. Fluentd log toplayıcı ve iletici rolünü üstlenir; Kibana ise Kibana Query Language (KQL) kullanarak veri görselleştirme, sorgulama ve dashboard inceleme imkanı verir.\n* **Response Time Detail View Dashboard:** Kibana arayüzüne aktarılan Response Time Detail View Dashboard, projeksiyon ve varlık (projections and entities) metriklerini varsayılan olarak en yüksek yanıt süresinden en düşük yanıt süresine doğru sıralayarak görüntüler.\n* **IFS Cloud 26R2 Application Monitoring Metrics (AMM):** AMM mimarisi arka planda metrikleri tanımlanmış ifadelere göre değerlendirir ve OK, Warning, Critical veya Unknown servis durum kodlarını üretir.\n* **IFS Cloud 26R2 Application Monitoring Console (AppMon):** Solution Manager / Monitoring / Application Monitoring altından erişilen AppMon konsolu, metrikleri uyarı limitlerine göre sunar; \"Show Alarms Only\" filtresi ile problemli metrikler izole edilir ve Details ekranından detaylı veriler (örneğin aktif batch queue süreçleri) incelenir. Foundation1 Monitoring zamanlanmış görevi günlük olarak çalışarak aktif metrikleri değerlendirir.\n* **IFS Cloud 26R2 Server Alert Log Kategorileri:** Solution Manager / Monitoring / Server Alert Log Categories penceresinden yapılandırılan her kategori Enable (etkinleştirme), Cleanup (temizlik bayrağı) ve Days to keep (saklama süresi) parametrelerine sahiptir. Standart kategoriler: Ddl Audit (DDL komutlarını veritabanı tetikleyicisiyle izler), Debug, Deployment, Deployment detail, Event errors, Server Errors (tüm ORA- hatalarını AFTER ERROR tetikleyicisiyle izler), Sql Injections (Assert_SYS güvenlik denetimi hatalarını izler) ve In-Memory (In-Memory indeks silme olaylarını izler).\n* **IFS Cloud 26R2 Oracle Advanced Queues:** Solution Manager / Monitoring / Oracle Queues penceresinden asenkron mesajlaşma kuyruk tabloları başlatılabilir, durdurulabilir ve temizlenebilir; Oracle Queue Subscribers penceresinden ise aktif aboneler izlenebilir ve kaldırılabilir.\n* **IFS Cloud 26R2 Streams Arka Plan İş Bildirimleri:** Streams işlevselliği, `Transaction_SYS.Deferred_Call` tek seferlik işleri ve `Batch_SYS.New_Batch_Schedule` zamanlanmış görevleri tamamlandığında `Transaction_SYS.Process_All_Pending` zamanlayıcısı üzerinden son kullanıcılara bildirim gönderir. Bildirimler `stream_msg_on_completion_` (TRUE) ve `stream_notes_` parametreleri ile etkinleştirilir ve `Transaction_SYS.Modify_Stream_Notification` Hooking API'si ile özelleştirilebilir.\n* **Sürüm Bağlamı:** Kaynaklar EFK stack panellerinin ve Kibana Response Time Detail View Dashboard aracının IFS Cloud 25R1 sürümüne; AMM metriklerinin, AppMon konsolunun, Server Alert Log kategorilerinin, Oracle Queues arayüzünün ve Streams bildirimlerinin ise IFS Cloud 26R2 sürümüne ait olduğunu açıkça belirtmektedir.\n\n---\n\n💡 **Sonraki Adımlar:** Studio paneline eklenen **Monitoring and Incident Management Overview** bilgi grafiğini incelemek veya **IFS Cloud Quiz** uygulamasını çözerek izleme ve olay yönetimi bilgilerinizi pekiştirmek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-9.jpg", "aofInfographic": null, "nlmInfographic": null}, {"title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "summary": "Recovery Manager (RMAN) yedekleme, geri yükleme ve kurtarma operasyonlarının Oracle Database 19c ve 26ai ortamlarında yönetimi öğrenilir. RMAN RECOVER TABLE PITR ile silinen tabloları auxiliary destination kullanarak veritabanı kesintisi olmadan kurtarır. Ayrıca kesinti incelemesi hazırlığı, dba_scheduler_job_run_details ve v$diag_alert_ext sorguları ile canlıya geçiş öncesi kontrol listelerini ve eğitim ilerleme durumunu değerlendirir.", "objectives": ["RMAN RESTORE, RECOVER, DUPLICATE ve FLASHBACK DATABASE komutlarını Data Recovery Advisor (DRA) amortismanını dikkate alarak çalıştırabilir.", "Oracle 12c, 19c ve 26ai veritabanlarında RMAN RECOVER TABLE PITR ile auxiliary destination kullanarak tablo seviyesinde nokta zamanlı kurtarma yapabilir.", "dba_scheduler_job_run_details ve v$diag_alert_ext sorguları ile kesinti sonrası incelemeleri yürüterek canlıya alım kontrol listelerini güncelleyebilir."], "lectures": [{"title": "IFS Enterprise Oracle Architecture & DBA Training Program Practice Test", "url": "", "type": "gemini_chat"}, {"title": "IFS Oracle DBA Training Progress", "url": "", "type": "gemini_chat"}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": "", "type": "gemini_chat"}, {"title": "Training Progress and Chapter 6 Start", "url": "", "type": "gemini_chat"}, {"title": "Kesinti incelemesi hazırlığı, 11.11.2026.docx", "url": "", "type": "docx"}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": "", "type": "gemini_chat"}, {"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf", "type": "pdf"}, {"title": "Backup and Recovery User Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/", "type": "web_page"}, {"title": "Recovering Tables and Table Partitions", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-recovering-tables-partitions.html", "type": "web_page"}, {"title": "Transporting Data Across Platforms", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-transporting-data-across-platforms.html", "type": "web_page"}], "notes": "### Data Recovery Advisor (DRA) Amortismanı ve RMAN RESTORE, RECOVER, DUPLICATE ve FLASHBACK DATABASE Operasyonları\n\n* **Data Recovery Advisor (DRA) Amortismanı (Deprecation):** Resmî Oracle dokümanı \"Oracle Database Backup and Recovery Reference - Oracle Help\", Oracle Database 19c sürümünden itibaren Data Recovery Advisor (DRA) özelliğinin kullanımının kaldırıldığını (deprecated) belirtmektedir. DRA özelliğinin amortismanı ile birlikte Recovery Manager (RMAN) bünyesindeki `LIST FAILURE`, `ADVISE FAILURE`, `REPAIR FAILURE` ve `CHANGE FAILURE` komutları da kullanımdan kaldırılmıştır. Veritabanı yöneticileri Oracle Database 19c sürümünde bu komutlara erişememektedir ve DRA için sunulmuş herhangi bir alternatif özellik bulunmamaktadır.\n* **RMAN `RESTORE` Komutu Operasyonları:** `RESTORE` komutu; veri dosyalarını, kontrol dosyalarını, sunucu parametre dosyasını (spfile) veya arşiv redo log dosyalarını yedek kümelerinden (backup sets) veya disk kopyalarından varsayılan ya da yeni bir konuma geri yükler. Oracle Database 19c (ve 18c) sürümünde `RESTORE`, kurum içi (on-premises) veritabanı ile Oracle Cloud arasında şifrelenmemiş veya şifrelenmiş veritabanlarını taşırken `AS ENCRYPTED` veya `AS DECRYPTED` yan tümcelerini destekler. `RESTORE` komutu, `RESTORE FROM PLATFORM` veya `RESTORE ALL FOREIGN DATAFILES` kullanarak platformlar arası yedeklerin geri yüklenmesini sağlar.\n* **RMAN `RECOVER` Komutu Operasyonları:** `RECOVER` komutu, geri yüklenen veri dosyalarına veya veri dosyası kopyalarına redo log dosyalarını ve artımlı yedekleri (incremental backups) uygulayarak dosyaları ileriye dönük günceller. Oracle Database 19c sürümünde depolama anlık görüntüleri (storage snapshots) kullanarak nokta zamanlı kurtarma yapmayı sağlayan `RECOVER...SNAPSHOT TIME` yöntemi kullanımdan kaldırılmıştır (deprecated). Oracle, depolama anlık görüntüsü almadan önce ve sonra `ALTER DATABASE BEGIN/END BACKUP` komutlarının çalıştırılmasını, ardından `END BACKUP` tamamlanma zamanından sonraki bir zamana veya SCN değerine `RECOVER...UNTIL TIME` ile kurtarma yapılmasını önermektedir. `RECOVER` komutu, fişlenebilir veritabanı kurtarma (`RECOVER PLUGGABLE DATABASE`) ve tablo seviyesinde kurtarma (`RECOVER TABLE`) işlemlerini yürütür.\n* **RMAN `DUPLICATE` Komutu Operasyonları:** `DUPLICATE` komutu, kaynak veritabanının yedeklerini kullanarak test amaçlı benzersiz bir DBID değerine sahip kopyalanmış bir veritabanı (duplicate database) veya Data Guard ortamı için birincil veritabanı DBID değerini koruyan bir ikincil veritabanı (standby database) oluşturur. Çevrimiçi açık veritabanından doğrudan veritabanı kopyalama (active duplication) ve yedek tabanlı kopyalama (backup-based duplication) modlarını destekler. Oracle Database 18c sürümünde tanıtılan ve Oracle Database 19c sürümünde desteklenen `DUPLICATE PLUGGABLE DATABASE` komutu, `COMPATIBLE` parametresi 18.0.0 veya üzeri olduğunda bir PDB'yi mevcut bir CDB içerisine kopyalamaya izin verir.\n* **RMAN `FLASHBACK DATABASE` Komutu Operasyonları:** `FLASHBACK DATABASE` komutu, veri dosyalarını yedekten geri yüklemeye gerek kalmadan Hızlı Kurtarma Alanı (FRA) içinde saklanan flashback log dosyalarını kullanarak tüm veritabanını (CDB) veya belirli bir PDB'yi belirtilen bir SCN, zaman, log sıra numarası veya geri yükleme noktasına (restore point) geri sarar. Proxy PDB üzerinde flashback operasyonları desteklenmemektedir.\n\n---\n\n### RMAN `RECOVER TABLE PITR` ve Yardımcı Hedef (Auxiliary Destination) İle Tablo Seviyesinde Nokta Zamanlı Kurtarma\n\n* **Amaç ve Kullanım Senaryoları:** RMAN `RECOVER TABLE` komutu, veritabanının diğer nesnelerini etkilemeden ve tüm veritabanını geri yükleme ihtiyacı veya sistem kesintisi yaratmadan, silinen veya mantıksal olarak bozulan tabloları ya da tablo bölümlerini RMAN yedeklerinden belirli bir geçmiş nokta zamana kurtarır. Bu işlem; geri alma (undo) verisi yetersiz olduğu için Flashback Table kullanılamadığında veya DDL yapısal değişiklikleri (truncate table gibi) Flashback Table kullanımını engellediğinde tercih edilir.\n* **Gereksinimler ve Yedek Kapsamı:** Hedef veritabanının ARCHIVELOG modunda ve okuma-yazma modunda olması gerekir. Fişlenebilir veritabanlarında (PDB) tablo kurtarma işlemi için root konteyner (CDB$ROOT), CDB şablonu (PDB$SEED) ve ilgili PDB'nin SYSTEM, SYSAUX ve undo tablespace yedekleri ile tablonun bulunduğu tablespace yedeği zorunludur. SYS şemasına ait nesneler veya SYSTEM/SYSAUX tablespace içindeki tablolar bu yöntemle kurtarılamaz.\n* **Nokta Zaman Belirleme:** Kurtarma noktası `UNTIL TIME` (zaman ifadesi), `UNTIL SCN` (Sistem Değişim Numarası) veya `UNTIL SEQUENCE` (log sıra numarası) parametreleriyle tanımlanır.\n* **Otomatik Yardımcı Veritabanı (Auxiliary Database) Süreci:**\n 1. RMAN, belirtilen zaman noktasına karşılık gelen uygun yedekleri belirler.\n 2. RMAN, hedef sunucudaki disk alanını kontrol eder ve `AUXILIARY DESTINATION` tümcesi (veya `SET NEWNAME` komutları) ile belirtilen konumda otomatik olarak geçici bir yardımcı veritabanı örneği oluşturur.\n 3. RMAN gerekli veri dosyalarını geri yükler ve yardımcı veritabanı içinde hedef tabloları belirtilen zaman noktasına kadar kurtarır.\n 4. RMAN, kurtarılan nesneleri içeren bir Data Pump döküm dosyası (export dump file) oluşturur. Döküm dosyası konumu `DATAPUMP DESTINATION` ile belirlenir (belirtilmezse `AUXILIARY DESTINATION` konumu, o da yoksa varsayılan işletim sistemi dizini kullanılır; Linux üzerinde varsayılan dizin $ORACLE_HOME/dbs konumudur).\n 5. Varsayılan olarak RMAN, Data Pump döküm dosyasını hedef veritabanına otomatik aktarır (import eder). `NOTABLEIMPORT` yan tümcesi kullanılırsa import adımı atlanır ve döküm dosyası ileride manuel Data Pump Import ile aktarılmak üzere saklanır.\n* **Şema, Tablo ve Tablespace Yeniden Eşleme:** `REMAP TABLE` tümcesi kurtarılan tabloların adını değiştirmeyi sağlar. Oracle Database 12c Release 2 (12.2) sürümünden itibaren `REMAP TABLE` yan tümcesi tabloların orijinal şemadan farklı bir yeni şemaya aktarılmasına imkan tanır. `REMAP TABLESPACE` tümcesi ise tabloların farklı bir tablespace alanına aktarılmasını sağlar.\n* **PDB Desteği:** Fişlenebilir veritabanlarında tablolar `RECOVER TABLE ... OF PLUGGABLE DATABASE <pdb_name>` komut satırı ile root konteynere veya ilgili PDB'ye yerel bağlanılarak kurtarılır.\n* **Sürüm Durumu ve Kaynak Kapsamı:** Resmî Oracle belgeleri `RECOVER TABLE` süreçlerini Oracle Database 19c için açıklamakta ve şema yeniden eşleme özelliğinin Oracle Database 12c Release 2 (12.2) sürümünde getirildiğini belirtmektedir. Seçilen kaynaklar Oracle 26ai sürümü için `RECOVER TABLE` konusuna dair herhangi bir bilgi veya kural içermemektedir, bu nedenle Oracle 26ai detayları kaynak kapsamı dışında bırakılmıştır.\n\n---\n\n### Kesinti Sonrası `dba_scheduler_job_run_details` ve `v$diag_alert_ext` Sorguları İle İnceleme ve Canlıya Alım Kontrol Listelerini Güncelleme\n\n* **Kesinti Analizi ve Sıralı Temizleme (Cleanup) Mantığı:** Eğitim kesinti notları (\"Kesinti incelemesi hazırlığı, 11.11.2026.docx\"), yazılım canlıya alımı (deploy) öncesinde temizlenmesi gereken toplu işlerin (batch jobs) tamamlanmaması nedeniyle yaşanan sistem kesintilerini inceler. Gece ve hafta sonu çalışan Cleanup süreçlerinin sıralı (sequential) çalıştığı, bir adım takıldığında sonraki adımların beklediği belirtilmektedir.\n* **Teşhis Amaçlı Salt Okunur SQL Sorgularının Çalıştırılması:** Olay anına ait anlık görünümler (`gv$session` gibi) geçmiş veriyi korumadığı için, Diagnostics Pack veya Tuning Pack lisansı gerektirmeyen salt okunur SQL sorguları veritabanı yöneticisi (DBA) yetkileriyle çalıştırılır:\n * **`dba_scheduler_job_run_details` Görünümü:** Olay zaman aralığında (`WHERE actual_start_date BETWEEN :bas AND :bit`) Oracle Scheduler işlerinin çalışma geçmişini incelemek amacıyla `owner`, `job_name`, `status`, `actual_start_date`, `run_duration` ve `error#` sütunları sorgulanır.\n * **`v$diag_alert_ext` Görünümü:** Olay zaman aralığında (`WHERE originating_timestamp BETWEEN :bas AND :bit`) Oracle alert log kayıtlarını incelemek amacıyla mesaj metninde `%ORA-%` veya `%deadlock%` geçen ifadeler `originating_timestamp` ve `message_text` sütunlarından sorgulanır.\n* **Canlıya Alım (Deploy) Kontrol Listeleri ve İzleme Eşiklerinin Güncellenmesi:**\n * Kesinti incelemesi bulguları doğrultusunda canlıya alım öncesinde açık arka plan işi kalıp kalmadığını denetleyen (\"çalışan arka plan işi yok\" / no active background jobs) denetim adımı canlıya alım kontrol listesine ve DBA runbook belgelerine eklenir.\n * Çalışmakta olan arka plan işlerinin çalışma sürelerini, bekleyen veya hatalı biten iş sayılarını ve Cleanup görevinin son başarılı çalışma zamanını takip eden izleme kuralları ve alarm eşikleri yapılandırılır.\n\n---\n\n💡 **Sonraki Adımlar:** RMAN komut kalıplarını ve `RECOVER TABLE` adımlarını pekiştirmek için Studio panelindeki **Backup and Recovery Operational Practice** bilgi grafiğini incelemek veya **RMAN Quiz** uygulamasını denemek ister misiniz?", "cites": [], "image": "assets/teknik-gelistirim-tr/chapter-10.jpg", "aofInfographic": null, "nlmInfographic": null}], "quiz": [{"question": "Oracle veritabanı yama yönetimi yaşam döngüsünde Release Update (RU) ile Release Update Revision (RUR) arasındaki temel fark nedir?", "answerOptions": [{"text": "RU; güvenlik güncellemeleri, yüksek değerli hata düzeltmeleri ve kararlılık iyileştirmelerini içeren çeyreklik birikimli yamadır; RUR ise yeni işlevsel hata düzeltmeleri sunmadan mevcut bir RU'nun ömrünü uzatan güvenlik ve regresyon odaklı yamadır.", "isCorrect": true, "rationale": "RU çeyreklik birikimli güncellemeleri sağlarken, RUR yeni işlevsel düzeltme eklemeden mevcut RU sürümünün kararlılığını ve güvenliğini korumak üzere tasarlanmıştır."}, {"text": "RU yalnızca güvenlik açıklarını kapatırken, RUR veritabanı ana sürümünü bir üst versiyona yükseltir.", "isCorrect": false, "rationale": "RUR ana veritabanı sürümünü yükseltmez, mevcut RU sürümünün ömrünü uzatır."}, {"text": "RUR çeyreklik olarak yeni özellikler ekler, RU ise yalnızca acil durum yaması (one-off patch) olarak uygulanır.", "isCorrect": false, "rationale": "RUR yeni özellikler eklemez, güvenlik ve regresyon odaklı bir uzatma yamasıdır."}, {"text": "RU ve RUR aynı içeriğe sahiptir; tek fark RU'nun PDB$SEED için, RUR'un ise CDB$ROOT için uygulanmasıdır.", "isCorrect": false, "rationale": "RU ve RUR ayrımı konteyner türüne göre değil, yama içeriği ve yaşam döngü amacına göredir."}], "hint": "Yama türlerinden birinin yeni işlevsel hata düzeltmeleri sunmadan mevcut sürümün kararlılığını uzatma amacını düşünün.", "type": "multiple_choice"}, {"question": "IFS Enterprise Oracle mimarisinde Automatic Storage Management (ASM) disk grubu tasarımında +DATA ve +RECO grupları için önerilen şeritlenme (striping) stratejisi hangisidir?", "answerOptions": [{"text": "+DATA için kaba şeritlenme (coarse-grained striping), +RECO için ince şeritlenme (fine-grained striping).", "isCorrect": true, "rationale": "+DATA kaba şeritlenme ile veri ve indeks dosyalarının I/O başarımını optimize ederken, +RECO ince şeritlenme ile redo ve kurtarma varlıklarını yönetir."}, {"text": "+DATA için ince şeritlenme (fine-grained striping), +RECO için kaba şeritlenme (coarse-grained striping).", "isCorrect": false, "rationale": "+DATA veri dosyaları için kaba, +RECO ise redo ve kurtarma varlıkları için ince şeritlenme kullanmalıdır."}, {"text": "Her iki disk grubu için de yalnızca ince şeritlenme (fine-grained striping) uygulanmalıdır.", "isCorrect": false, "rationale": "Veri dosyalarının yer aldığı +DATA disk grubu kaba şeritlenme gerektirir."}, {"text": "+DATA için şeritlenme tamamen kapatılmalı, +RECO için kaba şeritlenme kullanılmalıdır.", "isCorrect": false, "rationale": "ASM mimarisinde şeritlenme kapatılmaz ve +RECO ince şeritlenme kullanır."}], "hint": "Redo log dosyaları ile veri/indeks dosyalarının I/O erişim gereksinimlerini göz önüne alın.", "type": "multiple_choice"}, {"question": "IFS Cloud 26R2 ortamında arka plan işlerinin (background jobs) temizlik parametreleri ayarlanırken tamamlanmış işler ve Hata (Error) durumundaki işler için önerilen saklama süreleri sırasıyla kaç gündür?", "answerOptions": [{"text": "Tamamlanmış işler için 7 gün, Hata (Error) durumundaki işler için 180 gün.", "isCorrect": true, "rationale": "Tamamlanan işlerin 7 gün tutulması çekirdek tabloları lean tutarken, hatalı işlerin 180 gün saklanması kök neden analizi için yeterli teşhis geçmişi sağlar."}, {"text": "Tamamlanmış işler için 30 gün, Hata (Error) durumundaki işler için 90 gün.", "isCorrect": false, "rationale": "Sistem yönetişim standartları tamamlanmış işler için 7 gün, hatalı işler için 180 gün kuralını öngörür."}, {"text": "Tamamlanmış işler için 1 gün, Hata (Error) durumundaki işler için 30 gün.", "isCorrect": false, "rationale": "180 günlük hatalı iş saklama süresi arıza teşhisi için zorunlu kılınmıştır."}, {"text": "Tamamlanmış işler için 14 gün, Hata (Error) durumundaki işler için 365 gün.", "isCorrect": false, "rationale": "Mevcut IFS parametre standartlarında tanımlanan süreler 7 gün ve 180 gündür."}], "hint": "Çekirdek tabloları hafif tutmak için tamamlanan işlerin kısa sürede, arıza teşhisi için ise hatalı işlerin daha uzun süre saklanması gerektiğini düşünün.", "type": "multiple_choice"}, {"question": "Oracle High Availability mimarisinde veritabanı örneği (database instance) ile veritabanı (database) arasındaki fark aşağıdakilerden hangisinde doğru tanımlanmıştır?", "answerOptions": [{"text": "Veritabanı örneği, tek bir düğümde çalışan ve veritabanını istemcilere sunan sunucu süreçleri ve bellek yapıları kümesidir; veritabanı ise kalıcı depolamada bulunan paylaşımlı dosyalar kümesidir.", "isCorrect": true, "rationale": "Veritabanı örneği RAM ve sunucu süreçlerini ifade ederken, veritabanı persistent storage üzerindeki data, index, control ve initialization dosyalarını kapsar."}, {"text": "Veritabanı örneği disktedir, veritabanı ise yalnızca RAM üzerinde çalışan geçici bir süreçtir.", "isCorrect": false, "rationale": "Veritabanı örneği RAM ve süreçlerden oluşur, diskteki dosyalar ise veritabanının kendisidir."}, {"text": "Veritabanı örneği PDB$SEED yapısını temsil ederken, veritabanı yalnızca CDB$ROOT konteynerini ifade eder.", "isCorrect": false, "rationale": "Veritabanı ve veritabanı örneği kavramları multitenant konteyner türleriyle sınırlı değildir."}, {"text": "Veritabanı örneği birden fazla fiziksel kümede ortak paylaşılan depolamadır, veritabanı ise istemci bağlantı havuzudur.", "isCorrect": false, "rationale": "Veritabanı örneği depolama değil, sunucu bellek ve süreç kümesidir."}], "hint": "Biri sunucu bellek ve süreçlerini, diğeri ise disk üzerindeki kalıcı dosyaları temsil eder.", "type": "multiple_choice"}, {"question": "Oracle Application Continuity (AC/TAC) ve planlı bakım sürecinde, bağlantı boşaltma (connection draining) konfigürasyonu yapılırken `replay_init_time` parametresi için önerilen değer yaklaşımı nedir?", "answerOptions": [{"text": "`replay_init_time` değeri, oturum durumunun korunması ve yeniden yürütme için `drain_timeout` süresinden belirgin şekilde daha uzun (örneğin en az 3 katı) olmalıdır.", "isCorrect": true, "rationale": "`replay_init_time`, bağlantı kesildikten sonra oturumun yeniden çalıştırılabilmesi için gerekli zaman penceresini tanımlar ve `drain_timeout` süresinden daha uzun tutulmalıdır."}, {"text": "`replay_init_time` değeri her zaman `drain_timeout` değerinden tam olarak 10 saniye kısa olmalıdır.", "isCorrect": false, "rationale": "`replay_init_time` değeri `drain_timeout` değerinden kısa olursa oturumlar başarılı bir şekilde yeniden çalıştırılamaz."}, {"text": "`replay_init_time` parametresi yalnızca `failover_type` kapatıldığında sıfır (0) olarak ayarlanmalıdır.", "isCorrect": false, "rationale": "Sıfır değeri veya parametrenin devre dışı bırakılması TAC replay mekanizmasını engeller."}, {"text": "`replay_init_time` ve `drain_timeout` parametreleri her zaman birbirine eşit ve maksimum 5 saniye olmalıdır.", "isCorrect": false, "rationale": "Parametrelerin eşit veya çok kısa olması, uzun süren işlemlerin replay edilmesini başarısız kılar."}], "hint": "Bağlantı boşaltma süresi dolduktan sonra oturumun başarılı bir şekilde yeniden başlatılabilmesi için gereken zaman penceresini düşünün.", "type": "multiple_choice"}, {"question": "Oracle Database Backup and Recovery Reference dokümanına göre, RMAN ve Multitenant mimarisi ile ilgili aşağıda verilen ifadelerden hangisi doğrudur?", "answerOptions": [{"text": "Proxy PDB yedeğinin alınması (backing up a proxy PDB) desteklenmemektedir.", "isCorrect": true, "rationale": "RMAN mimarisinde proxy PDB yapıları doğrudan yedekleme işlemlerini desteklememektedir."}, {"text": "Uzaktan ağ üzerinden veri geri yüklenirken `FROM SERVICE` seçeneğinin kullanımı yasaklanmıştır.", "isCorrect": false, "rationale": "Uzak sunucudan restore yaparken `FROM SERVICE` komutu kullanılır ve desteklenmektedir."}, {"text": "RMAN `RESTORE` işleminde veri aktarımı sırasında `SET ENCRYPTION` komutu kullanılamaz.", "isCorrect": false, "rationale": "Ağ üzerinden aktarılan verilerin şifrelenmesi için `SET ENCRYPTION` desteklenir."}, {"text": "Multisection yedek setleri oluşturmak için `SECTION SIZE` parametresi yalnızca yerel disklerde kullanılabilir.", "isCorrect": false, "rationale": "`SECTION SIZE` ağ üzerinden uzak servis restorasyonlarında da kullanılabilir."}], "hint": "Dokümantasyonda PDB türlerinden biriyle ilgili yedekleme kısıtlamasına dair özel bir not bulunmaktadır.", "type": "multiple_choice"}, {"question": "Oracle veritabanında Application Continuity mimarisinin temel yapı taşı olan 'Servis' (Service) kavramı hangi yönetimsel birimlerden oluşur?", "answerOptions": [{"text": "Yönetim birimi (unit for management), kullanılabilirlik birimi (unit for availability) ve performans birimi (unit for performance).", "isCorrect": true, "rationale": "Servisler konum şeffaflığı sağlayan yönetim birimi, bağımsız kurtarma sağlayan kullanılabilirlik birimi ve AWR ile ölçülen performans birimi olarak tanımlanır."}, {"text": "Ağ birimi, disk grubu birimi ve hafıza alanı birimi.", "isCorrect": false, "rationale": "Bu bileşenler servis soyutlamasının işlevsel boyutları değildir."}, {"text": "Düğüm birimi, dinleyici (listener) birimi ve örnek (instance) birimi.", "isCorrect": false, "rationale": "Düğümler ve dinleyiciler servisin uygulama katmanına gizlediği alt altyapı elemanlarıdır."}, {"text": "Şema birimi, tablo birimi ve indeks birimi.", "isCorrect": false, "rationale": "Bunlar veritabanı nesne türleridir, servis birimleri değildir."}], "hint": "Servislerin iş yükünü yönetme, hızlı kurtarma sağlama ve hizmet kalitesi eşiklerini ölçme rollerini hatırlayın.", "type": "multiple_choice"}, {"question": "IFS Cloud \"System Performance\" ekranında yer alan \"Custom Field Runtime Performance Overview\" görünümü, sorunlu SQL ifadelerini tespit etmek için varsayılan olarak hangi filtreleme kriterini uygular?", "answerOptions": [{"text": "Çalıştırma başına ortalama geçen süresi (average elapsed time per execution) 2 saniyeden büyük olan özel alan sorgularını filtreler.", "isCorrect": true, "rationale": "Ekran, çalıştırma başına ortalama geçen süresi 2 saniyeyi aşan özel alan SQL ifadelerini otomatik olarak öne çıkarır."}, {"text": "Yalnızca hard parse sayısı 1000'i geçen ve Shared Pool dışına taşan SQL'leri filtreler.", "isCorrect": false, "rationale": "Filtreleme parse sayısına değil, ortalama çalışma süresine dayanır."}, {"text": "Yalnızca CPU süresi 10 saniyeyi aşan PL/SQL bloklarını filtreler.", "isCorrect": false, "rationale": "Özel alan ekranı CPU süresi yerine elapsed time kriterini 2 saniye sınırı ile uygular."}, {"text": "Sadece `db file sequential read` bekleme olayına takılan sorguları filtreler.", "isCorrect": false, "rationale": "Filtre belirli bir wait event'e değil, geçen süreye göre çalışır."}], "hint": "Özel alanlarla ilgili performans sorunlarını daraltmak için belirlenen saniye cinsinden ortalama yürütme süresi eşiğini hatırlayın.", "type": "multiple_choice"}, {"question": "IFS Enterprise Oracle Mimari Standartlarına göre, Maximum Availability Architecture (MAA) Gold ve Platinum katmanlarında hedeflenen RPO (Recovery Point Objective) ve RTO (Recovery Time Objective) değerleri nelerdir?", "answerOptions": [{"text": "Sıfır veri kaybı ($RPO = 0$) ve 5 dakikanın altında neredeyse sıfır kesinti süresi ($RTO < 5\\text{ dk}$).", "isCorrect": true, "rationale": "Gold ve Platinum MAA standartları senkron taşıma ile RPO=0 ve altyapı failover tasarımları ile RTO < 5 dk hedefler."}, {"text": "$RPO \\le 1\\text{ saat}$ ve $RTO \\le 24\\text{ saat}$.", "isCorrect": false, "rationale": "Gold/Platinum standartları çok daha katı koruma hedeflerine sahiptir."}, {"text": "$RPO = 24\\text{ saat}$ ve $RTO = 0$.", "isCorrect": false, "rationale": "Gold ve Platinum MAA mimarilerinde veri kaybı hedefi sıfırdır."}, {"text": "$RPO < 5\\text{ dk}$ ve $RTO = 0$.", "isCorrect": false, "rationale": "RPO değeri kesin olarak 0 (sıfır veri kaybı) olarak tanımlanır."}], "hint": "Senkron redo taşıma modları ile veritabanı seviyesinde tam koruma ve hızlı felaket kurtarımı hedeflerini göz önüne alın.", "type": "multiple_choice"}, {"question": "IFS Cloud 26R2 mimarisinde, Application Monitoring Metrics (AMM) eşik değerlerini günlük olarak değerlendirerek sistem uyarılarını tetikleyen zamanlanmış görev hangisidir?", "answerOptions": [{"text": "Foundation1 Monitoring", "isCorrect": true, "rationale": "Foundation1 Monitoring görevi günlük olarak çalışarak yapılandırılmış uyarı limitlerine göre metrikleri değerlendirir."}, {"text": "Transaction_SYS.Process_All_Pending", "isCorrect": false, "rationale": "Bu görev ertelenmiş arka plan işlerini yürütür, AMM eşik değerlendirmesi yapmaz."}, {"text": "Batch_Processor_Main", "isCorrect": false, "rationale": "Bu görev kuyruk işleyicisidir, izleme uyarılarını tetiklemez."}, {"text": "AMM_Alert_Evaluator_Task", "isCorrect": false, "rationale": "Sistemde bu isimde tanımlı varsayılan izleme zamanlanmış görevi bulunmamaktadır."}], "hint": "Mimaride altyapının izleme bileşenlerini günlük periyotta çalıştıran temel zamanlanmış görevin adını hatırlayın.", "type": "multiple_choice"}, {"question": "Oracle Real Application Clusters (RAC) mimarisinde, düğümler arasında bellek bloklarının tutarlılığını sağlamak ve kaynakları yönetmek için kullanılan temel mekanizmalar hangileridir?", "answerOptions": [{"text": "Cache Fusion, Düşük gecikmeli Interconnect ve Global Resource Directory (GRD).", "isCorrect": true, "rationale": "RAC düğümleri Cache Fusion ve Interconnect trafiği üzerinden GRD aracılığıyla bellek bloklarını tutarlı şekilde paylaşır."}, {"text": "Automatic Shared Memory Management (ASMM) ve Single Instance Listener.", "isCorrect": false, "rationale": "ASMM tekil veritabanı örneklerinde bellek alanlarını dinamik yönetir, düğümler arası blok aktarımını yapmaz."}, {"text": "Block Change Tracking (BCT) ve Recovery Catalog.", "isCorrect": false, "rationale": "BCT ve Recovery Catalog RMAN yedekleme bileşenleridir."}, {"text": "Enterprise Manager Cloud Control ve Database Vault Realm.", "isCorrect": false, "rationale": "Bu bileşenler merkezi yönetim ve güvenlik katmanına aittir."}], "hint": "RAC düğümlerinin veri bloklarını disk üzerinden okumadan doğrudan birbirlerinin RAM belleğinden aktarmasını sağlayan teknolojiyi düşünün.", "type": "multiple_choice"}, {"question": "Oracle veritabanı bellek tuning adımlarında, büyük toplu işler (batch runs) sırasında sıralama (sort) ve hash join işlemlerinin geçici tablo alanına (temporary tablespace) taşmasını önlemek için kullanılan parametre hangisidir?", "answerOptions": [{"text": "`pga_aggregate_target`", "isCorrect": true, "rationale": "`pga_aggregate_target` parametresi, süreç başına bellek tahsisini optimize ederek sort ve hash join operasyonlarının diske taşmasını önler."}, {"text": "`sga_target`", "isCorrect": false, "rationale": "`sga_target`, Shared Pool ve Buffer Cache gibi ortak SGA alanlarını yönetir."}, {"text": "`open_cursors`", "isCorrect": false, "rationale": "`open_cursors`, oturum başına açılabilecek imleç sayısını belirler."}, {"text": "`processes`", "isCorrect": false, "rationale": "`processes`, veritabanına bağlanabilecek maksimum süreç sayısını sınırlar."}], "hint": "Süreç başına düşen ve SQL operasyonlarının (sort, hash join) bellekte yürütülmesini sağlayan bellek parametresini düşünün.", "type": "multiple_choice"}], "pair": "teknik-gelistirim", "audio": {"1": {"src": "audio/teknik-gelistirim-tr/chapter-1.mp3", "dur": 425, "bytes": 3403337}, "2": {"src": "audio/teknik-gelistirim-tr/chapter-2.mp3", "dur": 355, "bytes": 2839241}, "3": {"src": "audio/teknik-gelistirim-tr/chapter-3.mp3", "dur": 357, "bytes": 2855561}, "4": {"src": "audio/teknik-gelistirim-tr/chapter-4.mp3", "dur": 300, "bytes": 2403977}, "5": {"src": "audio/teknik-gelistirim-tr/chapter-5.mp3", "dur": 328, "bytes": 2624393}, "6": {"src": "audio/teknik-gelistirim-tr/chapter-6.mp3", "dur": 369, "bytes": 2949833}, "7": {"src": "audio/teknik-gelistirim-tr/chapter-7.mp3", "dur": 392, "bytes": 3138569}, "8": {"src": "audio/teknik-gelistirim-tr/chapter-8.mp3", "dur": 363, "bytes": 2902409}, "9": {"src": "audio/teknik-gelistirim-tr/chapter-9.mp3", "dur": 362, "bytes": 2896841}, "10": {"src": "audio/teknik-gelistirim-tr/chapter-10.mp3", "dur": 340, "bytes": 2721353}}}];
